// Web Animations needs a timeline, and this engine has none: frames come
// from input and invalidation, not from a clock an animation could
// sample. An animation finishes at once, on the next task, without
// changing what is drawn, so code that waits on finish or onfinish, as a
// framework's transitions do, goes on as when the animation has run.
interface FinishedAnimationSlots extends EventTargetSlots {
	settle: (animation: FinishedAnimation) => void;
	fail: (error: unknown) => void;
}

interface FinishedAnimation {
	readonly [internals]: FinishedAnimationSlots;
}

class FinishedAnimation extends EventTarget {
	id: string;
	effect: globalThis.AnimationEffect | null;
	timeline: globalThis.AnimationTimeline | null;
	startTime: number | null;
	currentTime: number | null;
	playbackRate: number;
	pending: boolean;
	replaceState: globalThis.AnimationReplaceState;
	playState: globalThis.AnimationPlayState;
	onfinish: ((event: Event) => unknown) | null;
	oncancel: ((event: Event) => unknown) | null;
	onremove: ((event: Event) => unknown) | null;
	readonly ready: Promise<this>;
	readonly finished: Promise<this>;

	constructor(duration: number) {
		super();
		this.id = "";
		this.effect = null;
		this.timeline = null;
		this.startTime = null;
		this.currentTime = 0;
		this.playbackRate = 1;
		this.pending = false;
		this.replaceState = "active";
		this.playState = "running";
		this.onfinish = null;
		this.oncancel = null;
		this.onremove = null;
		this.ready = Promise.resolve(this);
		const slots = _(this);
		this.finished = new Promise<this>((resolve, reject) => {
			slots.settle = resolve as (animation: FinishedAnimation) => void;
			slots.fail = reject;
		});
		this.finished.catch(() => {});
		setTimeout(() => {
			if (this.playState === "running") {
				this.currentTime = duration;
				this.finish();
			}
		}, 0);
	}

	finish(): void {
		if (this.playState === "finished") {
			return;
		}
		this.playState = "finished";
		_(this).settle(this);
		const event = constructInternal(() => new Event("finish"));
		this.onfinish?.(event);
		this.dispatchEvent(event);
	}

	cancel(): void {
		if (this.playState === "idle") {
			return;
		}
		const wasFinished = this.playState === "finished";
		this.playState = "idle";
		this.currentTime = null;
		if (!wasFinished) {
			_(this).fail(domError("AbortError", "The animation was canceled"));
		}
		const event = constructInternal(() => new Event("cancel"));
		this.oncancel?.(event);
		this.dispatchEvent(event);
	}

	play(): void {}
	pause(): void {}
	reverse(): void {}
	persist(): void {}
	commitStyles(): void {}
	updatePlaybackRate(rate: number): void {
		this.playbackRate = rate;
	}
}

