	setHTMLUnsafe(html: string): void {
		const fragment = parseHTMLFragment(String(html ?? ""), this, true);
		replaceAll(fragment, getMarkupHost(this));
	}

	insertAdjacentElement(
		where: InsertPosition,
		element: globalThis.Element,
	): globalThis.Element | null {
		return insertAdjacent(
			this,
			String(where),
			element as unknown as Element,
		) as unknown as globalThis.Element |
		null;
	}

	insertAdjacentText(where: InsertPosition, data: string): void {
		const text = new Text(String(data));
		_(text).document = _(this).document;
		insertAdjacent(this, String(where), text);
	}

	insertAdjacentHTML(position: InsertPosition, text: string): void {
		const where = toASCIILowercase(String(position));
		let context: Node;
		const slots = _(this);
		switch (where) {
			case "beforebegin":
			case "afterend": {
				const parent = objectOf(slots.parent);
				if (parent === null || nodeTypeOf(parent) === DOCUMENT_NODE) {
					throw domError(
						"NoModificationAllowedError",
						"There is nowhere to insert that HTML",
					);
				}
				context = nodeTypeOf(parent) === ELEMENT_NODE
					? parent
					: createElementInternal(slots.document, "body", HTML_NAMESPACE);
				break;
			}
			case "afterbegin":
			case "beforeend":
				context = this;
				break;
			default:
				throw domError("SyntaxError", `"${position}" is not a position`);
		}
		let element = context as Element;
		if (
			nodeTypeOf(element) !== ELEMENT_NODE ||
			(isHTMLDocument(_(element).document) &&
				_(element).localName === "html" &&
				_(element).namespace === HTML_NAMESPACE)
		) {
			element = createElementInternal(slots.document, "body", HTML_NAMESPACE);
		}
		const fragment = parseHTMLFragment(String(text), element);
		switch (where) {
			case "beforebegin":
				preInsert(fragment, objectOf(slots.parent) as Node, this);
				break;
			case "afterbegin":
				preInsert(fragment, this, objectOf(slots.firstChild));
				break;
			case "beforeend":
				preInsert(fragment, this, null);
				break;
			case "afterend":
				preInsert(
					fragment,
					objectOf(slots.parent) as Node,
					objectOf(slots.next),
				);
				break;
		}
	}

