// Inert removes an element from every focusable area, so focus() refuses
// it and the focus walk skips it, wherever in a shadow tree it is.
function isInertTree(element: Element): boolean {
	let node: Element | null = element;
	while (node !== null) {
		if (hasAttributeOf(node, "inert")) {
			return true;
		}
		const parent = node.parentElement as unknown as Element | null;
		if (parent !== null) {
			node = parent;
			continue;
		}
		const root = getRoot(node);
		node = isShadowRoot(root)
			? (_((root as ShadowRoot)).extra.host as Element)
			: null;
	}
	return false;
}

// Zero for elements that are in the sequential focus navigation order
// without an attribute, minus one for every other element.
function getDefaultTabIndex(element: Element): number {
	const elementSlots = _(element);
	if (elementSlots.namespace !== HTML_NAMESPACE) {
		return -1;
	}
	switch (elementSlots.localName) {
		case "a":
		case "area":
		case "button":
		case "frame":
		case "iframe":
		case "input":
		case "object":
		case "select":
		case "textarea":
			return 0;
		case "summary": {
			const parent = objectOf(elementSlots.parent);
			return parent !== null &&
				nodeTypeOf(parent) === ELEMENT_NODE &&
				_((parent as Element)).namespace === HTML_NAMESPACE &&
				_((parent as Element)).localName === "details" &&
				getFirstChildElement(parent, "summary") === element
				? 0
				: -1;
		}
		default:
			return -1;
	}
}

function getFirstChildElement(parent: Node, localName: string): Element | null {
	for (let nodeSlots = _(parent).firstChild;
		nodeSlots !== null;
		nodeSlots = nodeSlots.next) {
		const node = objectOf(nodeSlots);
		if (nodeTypeOf(node) !== ELEMENT_NODE) {
			continue;
		}
		const element = node as Element;
		if (
			_(element).namespace === HTML_NAMESPACE &&
			_(element).localName === localName
		) {
			return element;
		}
	}
	return null;
}

