const SUBMITTABLE_TAGS = new Set([
	"button",
	"input",
	"object",
	"select",
	"textarea",
]);

function isSubmittable(element: Element): boolean {
	if (isFormAssociatedCustom(element)) {
		return true;
	}
	return isHTMLTag(element, SUBMITTABLE_TAGS);
}

// Every kind of button, not only the ones that submit: a reset button and
// a plain button are skipped for the same reason a submit button that did
// not submit is.
function isButtonControl(element: Element): boolean {
	if (element instanceof HTMLButtonElement) {
		return true;
	}
	if (element instanceof HTMLInputElement) {
		const type = element.type;
		return (
			type === "submit" ||
			type === "image" ||
			type === "reset" ||
			type === "button"
		);
	}
	return false;
}

function hasDataListAncestor(element: Element): boolean {
	for (
		let nodeSlots = _(element).parent;
		nodeSlots !== null;
		nodeSlots = nodeSlots.parent
	) {
		const node = objectOf(nodeSlots);
		if (node instanceof HTMLDataListElement) {
			return true;
		}
	}
	return false;
}

function getSubmittableElements(form: HTMLFormElement): Element[] {
	const controls: Element[] = [];
	for (const node of descendants(getRoot(form))) {
		if (nodeTypeOf(node) !== ELEMENT_NODE) {
			continue;
		}
		const element = node as Element;
		if (isSubmittable(element) && getFormOwner(element) === form) {
			controls.push(element);
		}
	}
	return controls;
}

// A submission normalizes a textarea's newlines, which the value itself
// holds as line feeds.
function normalizeToCRLF(value: string): string {
	return value.replace(/\r\n|\r|\n/g, "\r\n");
}

// What a custom element reported through setFormValue: a string, a File,
// a FormData whose entries all join, or null for nothing at all.
function appendSubmissionValue(entries: FormDataEntry[], field: Element): void {
	const value = _maybe(_(field).internals)?.submissionValue ?? null;
	if (value === null) {
		return;
	}
	const reported = readFormDataEntries(value);
	if (reported !== null) {
		entries.push(...reported);
		return;
	}
	const name = attributeOf(field, "name");
	if (name === null || name === "") {
		return;
	}
	entries.push(createEntry(name, value));
}

const OCTET_STREAM = "application/octet-stream";

const DIRNAME_INPUT_TYPES = new Set([
	"text",
	"search",
	"tel",
	"url",
	"email",
	"password",
]);

function appendFieldEntries(
	entries: FormDataEntry[],
	field: Element,
	submitter: Element | null,
): void {
	if (hasDataListAncestor(field) || isActuallyDisabled(field)) {
		return;
	}
	if (isButtonControl(field) && field !== submitter) {
		return;
	}
	if (field instanceof HTMLInputElement) {
		const type = field.type;
		if ((type === "checkbox" || type === "radio") && !field.checked) {
			return;
		}
		if (type === "image") {
			const given = attributeOf(field, "name");
			const prefix = given === null || given === "" ? "" : `${given}.`;
			entries.push(createEntry(`${prefix}x`, "0"));
			entries.push(createEntry(`${prefix}y`, "0"));
			return;
		}
	}
	if (isFormAssociatedCustom(field)) {
		appendSubmissionValue(entries, field);
		return;
	}
	const name = attributeOf(field, "name");
	if (name === null || name === "") {
		return;
	}
	if (field instanceof HTMLSelectElement) {
		for (const option of field.selectedOptions) {
			if (!isActuallyDisabled(option)) {
				entries.push(createEntry(name, option.value));
			}
		}
		return;
	}
	if (field instanceof HTMLInputElement) {
		const type = field.type;
		if (type === "checkbox" || type === "radio") {
			entries.push(createEntry(name, attributeOf(field, "value") ?? "on"));
			return;
		}
		if (type === "file") {
			const files = field.files;
			if (files === null || files.length === 0) {
				entries.push(
					createEntry(name, createFile([], "", {type: OCTET_STREAM})),
				);
			} else {
				for (const file of files) {
					entries.push(createEntry(name, file));
				}
			}
			return;
		}
	}
	if (field instanceof HTMLObjectElement) {
		return;
	}
	if (
		field instanceof HTMLInputElement &&
		field.type === "hidden" &&
		toASCIILowercase(name) === "_charset_"
	) {
		entries.push(createEntry(name, "UTF-8"));
		return;
	}
	if (field instanceof HTMLTextAreaElement) {
		entries.push(createEntry(name, normalizeToCRLF(field.value)));
		appendDirectionEntry(entries, field);
		return;
	}
	entries.push(
		createEntry(name, (field as HTMLInputElement | HTMLButtonElement).value),
	);
	if (
		field instanceof HTMLInputElement && DIRNAME_INPUT_TYPES.has(field.type)
	) {
		appendDirectionEntry(entries, field);
	}
}

function appendDirectionEntry(entries: FormDataEntry[], field: Element): void {
	const dirname = attributeOf(field, "dirname");
	if (dirname !== null && dirname !== "") {
		entries.push(createEntry(dirname, getDirectionality(field)));
	}
}

/**
 * The names and values the form would send, in tree order. Null when the
 * form is already building a list, which is what a FormData built inside
 * a formdata listener would be doing.
 */
function constructEntryList(
	form: HTMLFormElement,
	submitter: Element | null,
): FormDataEntry[] | null {
	const formSlots = _(form);
	if (formSlots.extra.constructingEntryList) {
		return null;
	}
	formSlots.extra.constructingEntryList = true;
	const built: FormDataEntry[] = [];
	let data: FormData;
	try {
		for (const field of getSubmittableElements(form)) {
			appendFieldEntries(built, field, submitter);
		}
		data = formDataFromEntries(built);
		dispatch(
			form,
			constructInternal(() =>
				new FormDataEvent("formdata", {formData: data, bubbles: true}),
			),
		);
	} finally {
		formSlots.extra.constructingEntryList = false;
	}
	// A listener may have added to, removed from or rewritten the entries.
	return readFormDataEntries(data)!;
}

// WebIDL has this inherit HTMLCollection, so it does. What it returns
// for a shared name is wider than the inherited return type, which a
// subclass cannot declare in TypeScript, so the merged interface below
// declares it instead. lib.dom gets the same result by splitting the base
// in two, which no engine does.
class HTMLFormControlsCollection
	extends (HTMLCollection as new (
		...args: ConstructorParameters<typeof HTMLCollection>
	) => Omit<HTMLCollection, "namedItem" | typeof kListNames>) {
	constructor(compute: () => Element[], owner: Node | null = null) {
		// The form attribute can associate a control anywhere in the tree, and
		// what counts as a control depends on its attributes, so the list is
		// document-wide and any attribute is an input to it.
		super(compute, owner, null, anyAttribute, true);
		_(this).owner = owner;
	}

	namedItem(name: string): RadioNodeList | Element | null {
		const key = String(name);
		if (key === "") {
			return null;
		}
		const matches = createMatchingCollection(this, key);
		if (matches.length === 0) {
			return null;
		}
		if (matches.length === 1) {
			return matches[0] as Element;
		}
		// A shared name returns the list of everything that shares it.
		return live(
			new RadioNodeList(() =>
				createMatchingCollection(this, key), _(this).owner),
		) as unknown as Element;
	}

	[kListNames](
		this: Slots<HTMLFormControlsCollection>,
		items: Node[],
	): Map<string, Node> {
		const counts = new Map<string, Node[]>();
		for (const item of items) {
			const element = item as Element;
			for (const key of [
				attributeOf(element, "id"),
				attributeOf(element, "name"),
			]) {
				if (key === null || key === "") {
					continue;
				}
				const list = counts.get(key);
				if (list === undefined) {
					counts.set(key, [element]);
				} else if (!list.includes(element)) {
					list.push(element);
				}
			}
		}
		const named = new Map<string, Node>();
		for (const [key, list] of counts) {
			named.set(
				key,
				list.length === 1
					? list[0]
					: (live(
						new RadioNodeList(() =>
							createMatchingCollection(ownerOf(this), key), this.owner),
					) as unknown as Node),
			);
		}
		return named;
	}
}

function createMatchingCollection(
	collection: HTMLFormControlsCollection,
	key: string,
): Node[] {
	const matches: Node[] = [];
	for (const item of ensureList(collection)) {
		const element = item as Element;
		if (
			attributeOf(element, "id") === key || attributeOf(element, "name") === key
		) {
			matches.push(element);
		}
	}
	return matches;
}

