// Long enough that no bar on this screen can exceed it.
function getGaugeGlyphs(host: Element, glyph: string): string {
	const view = (host.ownerDocument as {defaultView?: {innerWidth?: number}})
		.defaultView;
	const width = view?.innerWidth === undefined
		? undefined
		: view.innerWidth / getCellSize(host).width;
	return glyph.repeat(
		Math.max(40, typeof width === "number" && width > 0 ? width : 40),
	);
}

// What a canvas context's "inherit" direction resolves to.
function getCanvasDirection(canvas: Element): "ltr" | "rtl" {
	return getComputedValue(canvas, "direction") === "rtl" ? "rtl" : "ltr";
}

// A full-width track holding a bar whose width is the fraction filled.
// Both are painted by their backgrounds, as a browser paints a gauge.
function buildGaugeRoot(
	host: Element,
	attached: AttachedDocument,
): globalThis.HTMLElement {
	const document = getUADocument(host);
	const root = buildUAShadowTree(host, attached);
	const track = addPart(root, "track");
	track.removeChild(track.firstChild!);
	const bar = document.createElement("span");
	bar.setAttribute("part", "bar");
	track.appendChild(bar);
	return bar;
}

function setGaugeFill(
	bar: globalThis.HTMLElement,
	fraction: number | null,
): void {
	const width = fraction === null
		? "0%"
		: `${Math.max(0, Math.min(1, fraction)) * 100}%`;
	if (bar.style.width !== width) {
		bar.style.width = width;
	}
}

const METER_ATTRIBUTES = new Set([
	"value",
	"min",
	"max",
	"low",
	"high",
	"optimum",
]);

// Six numbers, each parsed relative to the ones around it. The element
// renders a closed shadow tree it owns: a bar filled to where `value`
// sits between `min` and `max`, with a level attribute
// computed from the low/high/optimum ranges, which the UA sheet uses to
// color the bar.
interface HTMLMeterElementExtra extends NodeExtra {
	upgraded: boolean;
	bar: globalThis.HTMLElement | null;
}

interface HTMLMeterElementSlots extends HTMLElementSlots {
	extra: HTMLMeterElementExtra;
	[kEnsureUAShadowTree]: Step<HTMLMeterElement[typeof kEnsureUAShadowTree]>;
	[kSyncUAShadowTree]: Step<HTMLMeterElement[typeof kSyncUAShadowTree]>;
}

interface HTMLMeterElement {
	readonly [internals]: HTMLMeterElementSlots;
}

class HTMLMeterElement extends HTMLElement {
	constructor(...args: ConstructorParameters<typeof HTMLElement>) {
		super(...args);
		const slots = _(this);
		slots.extra.upgraded = false;
		slots.extra.bar = null;
	}

	get min(): number {
		return parseFloatingPoint(this.getAttribute("min") ?? "") ?? 0;
	}

	set min(value: number) {
		this.setAttribute("min", String(toDouble(value)));
	}

	get max(): number {
		const max = parseFloatingPoint(this.getAttribute("max") ?? "") ?? 1;
		return Math.max(max, this.min);
	}

	set max(value: number) {
		this.setAttribute("max", String(toDouble(value)));
	}

	get value(): number {
		const value = parseFloatingPoint(this.getAttribute("value") ?? "") ?? 0;
		return Math.min(Math.max(value, this.min), this.max);
	}

	set value(value: number) {
		this.setAttribute("value", String(toDouble(value)));
	}

	get low(): number {
		const low = parseFloatingPoint(this.getAttribute("low") ?? "");
		if (low === null) {
			return this.min;
		}
		return Math.min(Math.max(low, this.min), this.max);
	}

	set low(value: number) {
		this.setAttribute("low", String(toDouble(value)));
	}

	get high(): number {
		const high = parseFloatingPoint(this.getAttribute("high") ?? "");
		if (high === null) {
			return this.max;
		}
		return Math.min(Math.max(high, this.low), this.max);
	}

	set high(value: number) {
		this.setAttribute("high", String(toDouble(value)));
	}

	get optimum(): number {
		const optimum = parseFloatingPoint(this.getAttribute("optimum") ?? "");
		if (optimum === null) {
			return (this.min + this.max) / 2;
		}
		return Math.min(Math.max(optimum, this.min), this.max);
	}

	set optimum(value: number) {
		this.setAttribute("optimum", String(toDouble(value)));
	}

	get labels(): NodeListOf<HTMLLabelElement> {
		return getLabels(this);
	}

	[kEnsureUAShadowTree]?(this: Slots<HTMLMeterElement>): void {
		const slots = this;
		if (slots.extra.upgraded) {
			syncUAShadowTree(ownerOf(this));
			return;
		}
		const attached = getAttachedDocument(ownerOf(this));
		if (attached === undefined) {
			return;
		}
		slots.extra.upgraded = true;
		slots.extra.bar = buildGaugeRoot(ownerOf(this), attached);
		syncUAShadowTree(ownerOf(this));
	}

	[kSyncUAShadowTree]?(this: Slots<HTMLMeterElement>): void {
		const slots = this;
		if (!slots.extra.upgraded) {
			return;
		}
		const bar = slots.extra.bar!;
		const min = ownerOf(this).min;
		const span = ownerOf(this).max - min;
		setGaugeFill(bar, span > 0 ? (ownerOf(this).value - min) / span : 0);
		const barLevel = getMeterLevel(ownerOf(this))!;
		const part = `bar ${barLevel}`;
		if (attributeOf(bar, "part") !== part) {
			bar.setAttribute("part", part);
		}
	}

	override [kAttributeChangeSteps](
		this: Slots<HTMLMeterElement>,
		localName: string,
		oldValue: string | null,
		value: string | null,
		namespace: string | null,
	): void {
		superStep(HTMLMeterElement, kAttributeChangeSteps).call(
			this,
			localName,
			oldValue,
			value,
			namespace,
		);
		if (namespace === null && METER_ATTRIBUTES.has(localName)) {
			syncUAShadowTree(ownerOf(this));
		}
	}
}

declareExtraSlots(HTMLMeterElement);

// Follows HTML's rendering rules. The optimum region is determined by
// where `optimum` sits relative to `low` and `high`. A value in that
// region is optimum, one region away is suboptimum, and two away is even
// less good.
export function getMeterLevel(element: Element): string | null {
	if (!(element instanceof HTMLMeterElement)) {
		return null;
	}
	const {low, high, optimum, value} = element;
	if (optimum < low) {
		if (value < low) {
			return "optimum";
		}
		return value <= high ? "suboptimum" : "even-less-good";
	}
	if (optimum > high) {
		if (value > high) {
			return "optimum";
		}
		return value >= low ? "suboptimum" : "even-less-good";
	}
	return value >= low && value <= high ? "optimum" : "suboptimum";
}

/** css-forms-1's :low-value and :high-value: a meter past a threshold. */
export function isMeterValue(
	element: Element,
	threshold: "low" | "high",
): boolean {
	if (!(element instanceof HTMLMeterElement)) {
		return false;
	}
	return threshold === "low"
		? element.value < element.low
		: element.value > element.high;
}

