	const options = getOptionList(select);
	if (options.length === 0) {
		return;
	}
	let index = select.selectedIndex;
	if (index < 0) {
		index = options.findIndex((o) => !optionIsDisabled(o));
	}
	_(select).extra.pickerHighlight = index;
	syncUAShadowTree(select);
