// The content box's size, plus the offset of its top-left corner INSIDE
// the border box. Deliberately not a rect. `top` and `left` are
// distances from the border edge, not positions in the document, and
// calling it a DOMRect would invite exactly the arithmetic (comparing it
// against a border box, intersecting it with the viewport) that its
// coordinates cannot support. ResizeObserver reports these four numbers
// as contentRect, which is where the confusion comes from.
interface ContentBox {
	width: number;
	height: number;
	top: number;
	left: number;
}

// The observers' measuring hook, an internal step, which author code
// must never see on an observer it holds.
const kMeasure = Symbol("measure");

// Keyed by document, not by a registry object, because the document is
// what an observer can reach from the target it was given. That is why
// `new ResizeObserver(callback)` needs only its callback.
const documentObservers = new WeakMap<object, Set<AnyObserver>>();

/**
 * Run a document's observers against the layout just computed for it. The
 * frame the renderer is finishing is what an IntersectionObserver measures
 * against and what a ResizeObserver reports the time of.
 */
export function flushObservers(
	document: globalThis.Document,
	layout: Layout,
	viewport: globalThis.DOMRect,
	frame: number,
): void {
	const observers = documentObservers.get(document);
	if (observers === undefined || observers.size === 0) {
		return;
	}
	// Iterate a copy. A callback may observe or disconnect, and mutating the
	// set mid-iteration would visit a new observer against a layout it has
	// not been measured for, or skip one that is still live.
	for (const observer of [...observers]) {
		try {
			checkObserver(observer, layout, viewport, frame);
		} catch (error) {
			reportError(error, document as Document);
		}
	}
}

/** A torn-down document delivers nothing. */
export function disconnectObservers(document: globalThis.Document): void {
	documentObservers.get(document)?.clear();
	engineObservers.get(document as Document)?.disconnect();
}

// What ResizeObserver and IntersectionObserver both hold: which elements
// are watched, what was last reported for each, and the documents whose
// frames measure them. Each supplies only how to measure one target.
interface ObserverSlots<TState, TEntry, TOptions> {
	observerCallback: (entries: TEntry[], observer: never) => void;
	// One entry per target, as the DOM says. A second observe() of the same
	// target replaces the first's options.
	targets: Map<
		globalThis.Element,
		{options: TOptions | undefined; last: TState | null}
	>;
	// One entry per document the observer has a target in.
	homes: Set<object>;
	[kMeasure](
		target: globalThis.Element,
		last: TState | null,
		layout: Layout,
		viewport: globalThis.DOMRect,
		frame: number,
		options: TOptions | undefined,
	): {state: TState; entry: TEntry} | null;
}

interface ObserverState<TState, TEntry, TOptions> {
	readonly [internals]: ObserverSlots<TState, TEntry, TOptions>;
}

type AnyObserver = ObserverState<unknown, unknown, unknown>;

function observeTarget<TState, TEntry, TOptions>(
	observer: ObserverState<TState, TEntry, TOptions>,
	target: globalThis.Element,
	options: TOptions | undefined,
): void {
	// A fresh target has no last state, so its first measurement always
	// counts as a change. That fires the initial callback the DOM promises.
	_(observer).targets.set(target, {
		options,
		last: _(observer).targets.get(target)?.last ?? null,
	});
	const document = target.ownerDocument;
	if (document === null) {
		return;
	}
	getObservers(document).add(observer as unknown as AnyObserver);
	_(observer).homes.add(document);
	// Observations are gathered in a frame, and nothing else may be about
	// to draw one.
	const attached = getAttachedDocument(document as unknown as Node);
	if (attached !== undefined) {
		void _(attached).extra.render();
	}
}

function unobserveTarget(
	observer: AnyObserver,
	target: globalThis.Element,
): void {
	_(observer).targets.delete(target);
	if (_(observer).targets.size === 0) {
		disconnectObserver(observer);
	}
}

function disconnectObserver(observer: AnyObserver): void {
	_(observer).targets.clear();
	for (const document of _(observer).homes) {
		documentObservers.get(document)?.delete(observer);
	}
	_(observer).homes.clear();
}

function getObservers(document: globalThis.Document): Set<AnyObserver> {
	let observers = documentObservers.get(document);
	if (observers === undefined) {
		observers = new Set<AnyObserver>();
		documentObservers.set(document, observers);
	}
	return observers;
}

function checkObserver<TState, TEntry, TOptions>(
	observer: ObserverState<TState, TEntry, TOptions>,
	layout: Layout,
	viewport: globalThis.DOMRect,
	frame: number,
): void {
	const entries: TEntry[] = [];
	for (const [target, observation] of _(observer).targets) {
		const result = _(observer)[kMeasure](
			target,
			observation.last,
			layout,
			viewport,
			frame,
			observation.options,
		);
		if (!result) {
			continue;
		}
		observation.last = result.state;
		entries.push(result.entry);
	}
	if (entries.length > 0) {
		_(observer).observerCallback(entries, observer as never);
	}
}

interface ResizeObserverSize {
	inlineSize: number;
	blockSize: number;
}

interface ResizeObserverEntry {
	target: globalThis.Element;
	contentRect: globalThis.DOMRect;
	borderBoxSize: readonly ResizeObserverSize[];
	contentBoxSize: readonly ResizeObserverSize[];
	devicePixelContentBoxSize: readonly ResizeObserverSize[];
}

type ResizeObserverCallback = (
	entries: ResizeObserverEntry[],
	observer: ResizeObserver,
) => void;

interface ResizeSize {
	width: number;
	height: number;
}

const RESIZE_BOXES = new Set([
	"border-box",
	"content-box",
	"device-pixel-content-box",
]);

type ResizeObserverOptions = globalThis.ResizeObserverOptions;

interface ResizeObserverSlots
	extends ObserverSlots<
		ResizeSize,
		ResizeObserverEntry,
		ResizeObserverOptions
	> {
	[kMeasure]: Step<ResizeObserver[typeof kMeasure]>;
}

interface ResizeObserver
	extends ObserverState<
		ResizeSize,
		ResizeObserverEntry,
		ResizeObserverOptions
	> {
	readonly [internals]: ResizeObserverSlots;
}

class ResizeObserver {
	constructor(callback: ResizeObserverCallback) {
		seal(this, new.target, ResizeObserver);
		const slots = _(this);
		slots.observerCallback =
			callback as ResizeObserverSlots["observerCallback"];
		slots.targets = new Map();
		slots.homes = new Set();
	}

	// `box` names which box's size change is worth reporting. Every entry
	// still carries all of them, as the DOM says. An unrecognized value is
	// rejected by the enumeration, as WebIDL requires, rather than quietly
	// ignored.
	observe(target: globalThis.Element, options?: ResizeObserverOptions): void {
		const box = options?.box;
		if (box !== undefined && !RESIZE_BOXES.has(box)) {
			throw new TypeError(
				`Failed to execute 'observe' on 'ResizeObserver': The provided value '${box}' is not a valid enum value of type ResizeObserverBoxOptions.`,
			);
		}
		observeTarget(this, target, options);
	}

	unobserve(target: globalThis.Element): void {
		unobserveTarget(this as unknown as AnyObserver, target);
	}

	disconnect(): void {
		disconnectObserver(this as unknown as AnyObserver);
	}

	[kMeasure](
		target: globalThis.Element,
		last: ResizeSize | null,
		layout: Layout,
		_viewport: globalThis.DOMRect,
		_frame: number,
		options: ResizeObserverOptions | undefined,
	): {state: ResizeSize; entry: ResizeObserverEntry} | null {
		// An element with no box (display:none, or detached) has a size, and
		// that size is zero. Reporting it is how the DOM lets a component
		// notice it has been hidden.
		const cells =
			getContentBox(target, layout) ?? {width: 0, height: 0, top: 0, left: 0};
		const content = {
			width: pxFromCells(cells.width, false, target),
			height: pxFromCells(cells.height, true, target),
			top: pxFromCells(cells.top, true, target),
			left: pxFromCells(cells.left, false, target),
		};

		const borderCells = layout.getRect(target);
		const border = borderCells && toPixelRect(target, borderCells);
		// device-pixel-content-box is the content box: devicePixelRatio is 1,
		// so a CSS pixel is a device pixel.
		const watched = options?.box === "border-box"
			? {
				width: border?.width ?? content.width,
				height: border?.height ?? content.height,
			}
			: {width: content.width, height: content.height};

		if (
			last && last.width === watched.width && last.height === watched.height
		) {
			return null;
		}

		const box: ResizeObserverSize = {
			inlineSize: content.width,
			blockSize: content.height,
		};
		return {
			state: watched,
			entry: {
				target,
				// The origin is the content box's offset inside the border box
				// (the padding and border before it), not zero.
				contentRect: new DOMRect(
					content.left,
					content.top,
					content.width,
					content.height,
				),
				contentBoxSize: [box],
				borderBoxSize: [
					{
						inlineSize: border?.width ?? content.width,
						blockSize: border?.height ?? content.height,
					},
				],
				devicePixelContentBoxSize: [box],
			},
		};
	}
}

declareSealedRoot(ResizeObserver);

// Returns null when the element generates no box at all (display:none
// or detached). The observer turns that into an all-zero rect.
function getContentBox(
	element: globalThis.Element,
	layout: Layout,
): ContentBox | null {
	const border = layout.getRect(element);
	const content = layout.contentRect(element);
	if (!border || !content) {
		return null;
	}
	// Origin relative to the border box: what precedes the content on each
	// axis.
	return {
		width: content.width,
		height: content.height,
		top: content.y - border.y,
		left: content.x - border.x,
	};
}

type IntersectionObserverInit = globalThis.IntersectionObserverInit;

type IntersectionObserverEntry = globalThis.IntersectionObserverEntry;

type IntersectionObserverCallback = (
	entries: IntersectionObserverEntry[],
	observer: IntersectionObserver,
) => void;

// The absolute lengths a margin may use, in pixels each.
const MARGIN_UNITS: Record<string, number> = {
	px: 1,
	in: 96,
	cm: 96 / 2.54,
	mm: 96 / 25.4,
	q: 96 / 101.6,
	pt: 96 / 72,
	pc: 16,
};

const MARGIN_COMPONENT =
	/^([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?)(px|in|cm|mm|q|pt|pc|%)$/i;

// IntersectionObserver's "parse a margin": one to four absolute lengths
// or percentages, a length in pixels, and the four sides written out as
// the getter serializes them. Anything else is a SyntaxError.
function checkObserverMargin(margin: string, what: string): string {
	const parts = margin.trim().split(/\s+/).filter(Boolean);
	const values = parts.map((part) => {
		const match = MARGIN_COMPONENT.exec(part);
		if (match === null) {
			return null;
		}
		const unit = match[2].toLowerCase();
		if (unit === "%") {
			return `${Number(match[1])}%`;
		}
		const px = Number(match[1]) * MARGIN_UNITS[unit];
		return `${Math.round(px * 1e6) / 1e6}px`;
	});
	if (
		values.length === 0 ||
		values.length > 4 ||
		values.some((value) => value === null)
	) {
		throw domError("SyntaxError", `"${margin}" is not a ${what} margin`);
	}
	const [top, right = top, bottom = top, left = right] = values as string[];
	return `${top} ${right} ${bottom} ${left}`;
}

interface IntersectionObserverSlots
	extends ObserverSlots<number, IntersectionObserverEntry, void> {
	intersectionRoot: globalThis.Element | globalThis.Document | null;
	[kMeasure]: Step<IntersectionObserver[typeof kMeasure]>;
}

interface IntersectionObserver {
	readonly [internals]: IntersectionObserverSlots;
}

class IntersectionObserver {
	readonly rootMargin: string;
	readonly scrollMargin: string;
	readonly thresholds: readonly number[];
	constructor(
		callback: IntersectionObserverCallback,
		init: IntersectionObserverInit = {},
	) {
		seal(this, new.target, IntersectionObserver);
		const slots = _(this);
		slots.observerCallback =
			callback as IntersectionObserverSlots["observerCallback"];
		slots.targets = new Map();
		slots.homes = new Set();
		slots.intersectionRoot = init.root ?? null;
		// An empty margin is the spec's own spelling of the default.
		this.rootMargin = checkObserverMargin(init.rootMargin || "0px", "root");
		this.scrollMargin = checkObserverMargin(
			init.scrollMargin || "0px",
			"scroll",
		);

		// A single number, an array, or the default of "any intersection at
		// all".
		const t = init.threshold ?? 0;
		this.thresholds = Object.freeze(
			(Array.isArray(t) ? [...t] : [t]).sort((a, b) => a - b),
		);
	}

	get root(): globalThis.Element | globalThis.Document | null {
		return _(this).intersectionRoot;
	}

	observe(target: globalThis.Element): void {
		observeTarget(this, target, undefined);
	}

	unobserve(target: globalThis.Element): void {
		unobserveTarget(this as unknown as AnyObserver, target);
	}

	disconnect(): void {
		disconnectObserver(this as unknown as AnyObserver);
	}

	// Records are computed and delivered in the same pass (see the
	// manager's flush), so nothing is ever queued undelivered and this is
	// always empty. It exists because the interface has it and code checks
	// for it.
	takeRecords(): IntersectionObserverEntry[] {
		return [];
	}

	[kMeasure](
		this: Slots<IntersectionObserver>,
		target: globalThis.Element,
		last: number | null,
		layout: Layout,
		viewport: globalThis.DOMRect,
		frame: number,
	): {state: number; entry: IntersectionObserverEntry} | null {
		const boxCells = layout.getRect(target);
		if (!boxCells) {
			return null;
		}
		const box = toPixelRect(target, boxCells);

		// The root is an explicit element's border box or the viewport. Either
		// way it is grown by rootMargin, which is the point of that option: it
		// lets a list start loading a row before it scrolls into view.
		const root = this.intersectionRoot;
		const rootCells = root && nodeTypeOf(root) === ELEMENT_NODE
			? layout.getRect(root as globalThis.Element)
			: viewport;
		if (!rootCells) {
			return null;
		}
		const rootBox = toPixelRect(target, rootCells);
		const rootBounds = applyRootMargin(rootBox, ownerOf(this).rootMargin);

		const {ratio, rect} = getIntersectionRatio(box, rootBounds);
		const index = getThresholdIndex(ownerOf(this), ratio);
		if (last === index) {
			return null;
		}

		return {
			state: index,
			entry: {
				target,
				isIntersecting: index > 0,
				intersectionRatio: ratio,
				boundingClientRect: box,
				intersectionRect: index > 0 ? rect : new DOMRect(0, 0, 0, 0),
				rootBounds,
				time: frame,
			},
		};
	}
}

declareSealedRoot(IntersectionObserver);

// From 0 (disjoint) to 1 (contained).
function getIntersectionRatio(
	box: globalThis.DOMRect,
	clip: globalThis.DOMRect,
): {ratio: number; rect: globalThis.DOMRect} {
	const left = Math.max(box.left, clip.left);
	const top = Math.max(box.top, clip.top);
	const right = Math.min(box.left + box.width, clip.left + clip.width);
	const bottom = Math.min(box.top + box.height, clip.top + clip.height);

	const width = Math.max(0, right - left);
	const height = Math.max(0, bottom - top);
	const area = box.width * box.height;

	return {
		ratio: area > 0 ? (width * height) / area : width > 0 && height > 0 ? 1 : 0,
		rect: new DOMRect(left, top, width, height),
	};
}

// The root-margin rules: one to four lengths, in the order top, right,
// bottom, left, in CSS pixels like the rects they grow. Percentages are
// resolved against the root's own size, as the spec requires.
function applyRootMargin(
	rect: globalThis.DOMRect,
	margin: string,
): globalThis.DOMRect {
	const [t, r, b, l] = CSSValues.parseEdgeLengths(margin);
	if (t === null && r === null && b === null && l === null) {
		return rect;
	}
	const resolve = (value: CSSValues.UnitValue, basis: number): number =>
		value === null
			? 0
			: typeof value === "number" ? value : (value.percentage / 100) * basis;
	const top = resolve(t, rect.height);
	const right = resolve(r, rect.width);
	const bottom = resolve(b, rect.height);
	const left = resolve(l, rect.width);

	return new DOMRect(
		rect.left - left,
		rect.top - top,
		Math.max(0, rect.width + left + right),
		Math.max(0, rect.height + top + bottom),
	);
}

// This is what the spec actually watches. An observation fires when
// this CHANGES, so a target scrolling through `[0, 0.5, 1]` reports at
// each step. Tracking only the boolean "is it intersecting" collapsed
// all of those into one callback and made threshold arrays decorative.
function getThresholdIndex(
	observer: IntersectionObserver,
	ratio: number,
): number {
	let index = 0;
	while (
		index < observer.thresholds.length && ratio >= observer.thresholds[index]
	) {
		// A zero threshold means "any overlap at all", so a ratio of exactly
		// zero has not reached it.
		if (observer.thresholds[index] === 0 && ratio === 0) {
			break;
		}
		index++;
	}
	return index;
}

// A window here is not the global object, so there is no "current
// global object" to consult. A bare `new Text()` belongs to whichever
// document was last attached to a window, or to one created here if
// none has been.
function getCurrentDocument(): Document {
	if (currentDocumentForConstruction !== null) {
		return currentDocumentForConstruction;
	}
	if (ambientDocument === null) {
		const document = new Document();
		ambientDocument = document;
		fillHTMLDocument(document, "");
	}
	return ambientDocument;
}

/** Whether `node` is the document element of its document. */
export function isDocumentElement(node: globalThis.Node): boolean {
	const slots = _(node as Node);
	const parent = slots.parent;
	return parent !== null &&
		parent.nodeType === DOCUMENT_NODE &&
		slots.nodeType === ELEMENT_NODE;
}

function isHTMLDocument(document: Document): boolean {
	return _(document).extra.type === "html";
}

