function validateXMLName(name: string): void {
	if (!XML_NAME.test(name)) {
		throw domError("InvalidCharacterError", `"${name}" is not a valid name`);
	}
}

function validateElementLocalName(name: string): void {
	if (!VALID_ELEMENT_LOCAL_NAME.test(name)) {
		throw domError(
			"InvalidCharacterError",
			`"${name}" is not a valid element name`,
		);
	}
}

// The next frame switches back to the main screen.
function leaveFullscreen(document: Document): Element | null {
	const stack = getFullscreenStack(document);
	if (stack.length === 0) {
		return null;
	}
	const exiting = stack.pop()!;
	fireFullscreenEvent("fullscreenchange", exiting);
	return exiting;
}

// CSSOM View's "potentially scrollable": the element has a box, and
// neither it nor its parent leaves overflow visible on both axes. A body
// that scrolls its own content is not what scrolls the viewport.
function isPotentiallyScrollable(body: Element): boolean {
	const view = body.ownerDocument?.defaultView as
		{
			getComputedStyle?(element: Element): {
				getPropertyValue(p: string): string;
			};
		} |
		null |
		undefined;
	if (view?.getComputedStyle === undefined) {
		return false;
	}
	// An absent computed value is the initial one, and overflow's initial
	// value is visible.
	const hidden = (value: string): boolean =>
		value !== "" && value !== "visible";
	const scrolls = (element: Element): boolean => {
		const style = view.getComputedStyle!(element);
		return (
			hidden(style.getPropertyValue("overflow-x")) ||
			hidden(style.getPropertyValue("overflow-y"))
		);
	};
	const parent = objectOf(_(body).parent);
	return (
		parent != null &&
		nodeTypeOf(parent) === ELEMENT_NODE &&
		scrolls(parent as Element) &&
		scrolls(body)
	);
}

// One live collection per document and kind, so `document.forms` is the
// same object on every read, as the HTML Standard requires. `watched`
// names the attribute that decides membership, if one does.
const documentCollections =
	new WeakMap<Document, Map<string, HTMLCollection>>();

function getDocumentCollection(
	document: Document,
	kind: string,
	match: (element: Element) => boolean,
	watched: string | null = null,
): HTMLCollection {
	let collections = documentCollections.get(document);
	if (collections === undefined) {
		collections = new Map();
		documentCollections.set(document, collections);
	}
	let collection = collections.get(kind);
	if (collection === undefined) {
		collection = live(
			new HTMLCollection(() => {
				const found: Element[] = [];
				for (const node of descendants(document)) {
					if (nodeTypeOf(node) === ELEMENT_NODE && match(node as Element)) {
						found.push(node as Element);
					}
				}
				return found;
			}, document, null, watched),
		);
		collections.set(kind, collection);
	}
	return collection;
}

// The elements HTML names by their name attribute in document.all.
const ALL_NAMED_ELEMENTS = new Set([
	"a",
	"button",
	"embed",
	"form",
	"frame",
	"frameset",
	"iframe",
	"img",
	"input",
	"map",
	"meta",
	"object",
	"select",
	"textarea",
]);

function isAllNamed(element: Element, name: string): boolean {
	if (attributeOf(element, "id") === name) {
		return true;
	}
	return (
		namespaceOf(element) === HTML_NAMESPACE &&
		ALL_NAMED_ELEMENTS.has(localNameOf(element)) &&
		attributeOf(element, "name") === name
	);
}

// Every element of the document, in tree order, named by id and by the
// name attribute of the elements HTML lists. A browser's document.all is
// also falsy and reports its typeof as "undefined", which no JavaScript
// object can do, so here it is an ordinary collection.
interface HTMLAllCollectionSlots extends LiveListSlots {
	[kListMembers]: Step<HTMLAllCollection[typeof kListMembers]>;
	[kListNames]: Step<HTMLAllCollection[typeof kListNames]>;
	[kAttributeSync]: Step<HTMLAllCollection[typeof kAttributeSync]>;
}

interface HTMLAllCollection extends LiveList {
	readonly [internals]: HTMLAllCollectionSlots;
}

class HTMLAllCollection {
	[index: number]: Element;
	declare [Symbol.iterator]: () => ArrayIterator<Element>;

	constructor(document: Document) {
		seal(this, new.target, HTMLAllCollection);
		if (!internalConstruction) {
			throw new TypeError("Illegal constructor");
		}
		initLiveList(this, true, document);
	}

	get length(): number {
		return ensureList(this).length;
	}

	// An index reads as an index and anything else as a name.
	item(
		nameOrIndex?: string,
	): globalThis.HTMLCollection | globalThis.Element | null {
		if (nameOrIndex === undefined) {
			return null;
		}
		const key = String(nameOrIndex);
		if (/^(?:0|[1-9]\d*)$/.test(key) && Number(key) < 4294967295) {
			const items = ensureList(this);
			const at = Number(key);
			return at < items.length
				? (items[at] as unknown as globalThis.Element)
				: null;
		}
		return this.namedItem(key);
	}

	// One element by that name, or every one when several share it.
	namedItem(
		name: string,
	): globalThis.HTMLCollection | globalThis.Element | null {
		const key = String(name);
		if (key === "") {
			return null;
		}
		const matches = (ensureList(this) as Element[]).filter((element) =>
			isAllNamed(element, key),
		);
		if (matches.length === 0) {
			return null;
		}
		if (matches.length === 1) {
			return matches[0] as unknown as globalThis.Element;
		}
		const document = _(this).owner as Document;
		return live(
			new HTMLCollection(() =>
				getDescendantElements(document, []).filter((element) =>
					isAllNamed(element, key),
				), document, null, anyAttribute),
		);
	}

	[kListMembers](this: Slots<HTMLAllCollection>): Node[] {
		return getDescendantElements(this.owner as Document, []);
	}

	[kListNames](items: Node[]): Map<string, Node> {
		const named = new Map<string, Node>();
		for (const item of items) {
			const element = item as Element;
			const id = attributeOf(element, "id");
			if (id !== null && id !== "" && !named.has(id)) {
				named.set(id, element);
			}
			const name = attributeOf(element, "name");
			if (
				name !== null &&
				name !== "" &&
				!named.has(name) &&
				isAllNamed(element, name)
			) {
				named.set(name, element);
			}
		}
		return named;
	}

	// An id or name moves the named properties without moving a member.
	[kAttributeSync](
		this: Slots<HTMLAllCollection>,
		element: Element,
		localName: string,
	): void {
		if (localName !== "id" && localName !== "name") {
			LiveList.prototype[kAttributeSync].call(this, element, localName);
			return;
		}
		if (this.exact) {
			defineListProperties(ownerOf(this));
		}
	}
}

