function stripAndCollapseWhitespace(value: string): string {
	return value.replace(/[\t\n\f\r ]+/g, " ").replace(/^ | $/g, "");
}

function copyDocumentState(from: Document, to: Document): void {
	const fromSlots = _(from);
	const toSlots = _(to);
	toSlots.extra.type = fromSlots.extra.type;
	toSlots.extra.contentType = fromSlots.extra.contentType;
	toSlots.extra.encoding = fromSlots.extra.encoding;
	toSlots.extra.documentURL = fromSlots.extra.documentURL;
	toSlots.extra.mode = fromSlots.extra.mode;
}

// The registry given, null if the caller asked for no registry,
// undefined if it did not ask.
function extractRegistry(
	options: {customElementRegistry?: unknown} | string | undefined,
): CustomElementRegistry | null | undefined {
	if (options == null) {
		return undefined;
	}
	if (typeof options !== "object") {
		return undefined;
	}
	if (!("customElementRegistry" in options)) {
		return undefined;
	}
	const value = options.customElementRegistry;
	if (value == null) {
		return null;
	}
	if (!(value instanceof CustomElementRegistry)) {
		throw new TypeError("That is not a custom element registry");
	}
	return value;
}

function extractIs(options: {is?: string} | string | undefined): string | null {
	if (options == null) {
		return null;
	}
	if (typeof options === "string") {
		return null;
	}
	const is = (options as {is?: unknown}).is;
	return is === undefined ? null : String(is);
}

function addToIdMap(document: Document, element: Element): void {
	const id = attributeOf(element, "id");
	if (id !== null && id !== "") {
		addIdEntry(document, id, element);
	}
	const name = getExposedName(element);
	if (name !== null) {
		addNameEntry(document, name, element);
	}
}

function removeFromIdMap(document: Document, element: Element): void {
	const id = attributeOf(element, "id");
	if (id !== null && id !== "") {
		removeIdEntry(document, id, element);
	}
	const name = getExposedName(element);
	if (name !== null) {
		removeNameEntry(document, name, element);
	}
}

function addMapEntry(
	map: Map<string, Element[]>,
	key: string,
	element: Element,
): void {
	const entries = map.get(key);
	if (entries === undefined) {
		map.set(key, [element]);
	} else if (!entries.includes(element)) {
		entries.push(element);
	}
}

function removeMapEntry(
	map: Map<string, Element[]>,
	key: string,
	element: Element,
): void {
	const entries = map.get(key);
	if (entries === undefined) {
		return;
	}
	const index = entries.indexOf(element);
	if (index !== -1) {
		entries.splice(index, 1);
	}
	if (entries.length === 0) {
		map.delete(key);
	}
}

function addIdEntry(document: Document, id: string, element: Element): void {
	addMapEntry(_(document).extra.idMap, id, element);
	syncNamedProperty(document, id);
}

function removeIdEntry(document: Document, id: string, element: Element): void {
	removeMapEntry(_(document).extra.idMap, id, element);
	syncNamedProperty(document, id);
}

function addNameEntry(
	document: Document,
	name: string,
	element: Element,
): void {
	addMapEntry(_(document).extra.nameMap, name, element);
	syncNamedProperty(document, name);
}

function removeNameEntry(
	document: Document,
	name: string,
	element: Element,
): void {
	removeMapEntry(_(document).extra.nameMap, name, element);
	syncNamedProperty(document, name);
}

// The elements whose name attribute names them on the Window, as the HTML
// Standard lists them.
const NAMED_BY_NAME = new Set(["embed", "form", "img", "object"]);

function isNamedByName(element: Element): boolean {
	const elementSlots = _(element);
	return (
		elementSlots.namespace === HTML_NAMESPACE &&
		NAMED_BY_NAME.has(elementSlots.localName)
	);
}

function getExposedName(element: Element): string | null {
	if (!isNamedByName(element)) {
		return null;
	}
	const name = attributeOf(element, "name");
	return name === null || name === "" ? null : name;
}

interface DOMImplementationSlots {
	document: Document;
}

interface DOMImplementation {
	readonly [internals]: DOMImplementationSlots;
}

class DOMImplementation {
	constructor(document: Document) {
		seal(this, new.target, DOMImplementation);
		_(this).document = document;
	}

	createDocumentType(
		qualifiedName: string,
		publicId: string,
		systemId: string,
	): DocumentType {
		if (arguments.length < 3) {
			throw new TypeError("createDocumentType needs three arguments");
		}
		const name = String(qualifiedName);
		validateDoctypeName(name);
		const doctype = new DocumentType(name, String(publicId), String(systemId));
		_(doctype).document = _(this).document;
		return doctype;
	}

	createDocument(
		namespace: string | null,
		qualifiedName: string | null,
		doctype: globalThis.DocumentType | null = null,
	): XMLDocument {
		if (arguments.length < 2) {
			throw new TypeError("createDocument needs a namespace and a name");
		}
		const document = new XMLDocument();
		const documentSlots = _(document);
		documentSlots.extra.type = "xml";
		documentSlots.extra.contentType = "application/xml";
		let element: Element | null = null;
		const name = qualifiedName === null ? "" : String(qualifiedName);
		if (name !== "") {
			element = document.createElementNS(
				namespace == null ? null : String(namespace),
				name,
			) as unknown as Element;
		}
		if (doctype != null) {
			appendNode(doctype as unknown as DocumentType, document);
		}
		if (element !== null) {
			appendNode(element, document);
		}
		const ns = namespace === "" || namespace == null ? null : String(namespace);
		if (ns === HTML_NAMESPACE) {
			documentSlots.extra.contentType = "application/xhtml+xml";
		} else if (ns === SVG_NAMESPACE) {
			documentSlots.extra.contentType = "image/svg+xml";
		}
		return document;
	}

	createHTMLDocument(title?: string): Document {
		return createHTMLDocument(
			title === undefined ? undefined : String(title),
			"about:blank",
			null,
		);
	}

	hasFeature(..._args: any[]): true {
		return true;
	}
}

declareSealedRoot(DOMImplementation);

function validateDoctypeName(name: string): void {
	if (!VALID_DOCTYPE_NAME.test(name)) {
		throw domError(
			"InvalidCharacterError",
			`"${name}" is not a valid doctype name`,
		);
	}
}

Object.defineProperty(DOMImplementation.prototype, Symbol.toStringTag, {
	value: "DOMImplementation",
	configurable: true,
});

// The one document of a realm that no parser builds. It carries the
// realm's registry, exactly as a parsed document does. The
// DOMImplementation method of the same name does not: a document an
// author builds through the DOM has no browsing context, and no registry
// until one claims it.
function createHTMLDocument(
	title?: string,
	url = "about:blank",
	registry: CustomElementRegistry | null = null,
): Document {
	const document = new Document();
	const documentSlots = _(document);
	documentSlots.registry = registry;
	fillHTMLDocument(document, title);
	documentSlots.extra.documentURL = url;
	return document;
}

function fillHTMLDocument(document: Document, title?: string): void {
	const previous = currentDocumentForConstruction;
	currentDocumentForConstruction = document;
	try {
		buildHTMLSkeleton(document, title);
	} finally {
		currentDocumentForConstruction = previous;
	}
}

function buildHTMLSkeleton(document: Document, title?: string): void {
	const documentSlots = _(document);
	documentSlots.extra.type = "html";
	documentSlots.extra.contentType = "text/html";
	const doctype = new DocumentType("html", "", "");
	_(doctype).document = document;
	appendNode(doctype, document);
	const html = createElementInternal(document, "html", HTML_NAMESPACE);
	appendNode(html, document);
	const head = createElementInternal(document, "head", HTML_NAMESPACE);
	appendNode(head, html);
	if (title !== undefined) {
		const titleElement = createElementInternal(
			document,
			"title",
			HTML_NAMESPACE,
		);
		appendNode(titleElement, head);
		const text = new Text(title);
		_(text).document = document;
		appendNode(text, titleElement);
	}
	const body = createElementInternal(document, "body", HTML_NAMESPACE);
	appendNode(body, html);
}

type Insertable = Node | string;

function convertNodesIntoNode(nodes: Insertable[], document: Document): Node {
	if (nodes.length === 1 && nodes[0] instanceof Node) {
		return nodes[0];
	}
	const converted = nodes.map((node) => {
		if (node instanceof Node) {
			return node;
		}
		const text = new Text(String(node));
		_(text).document = document;
		return text as Node;
	});
	if (converted.length === 1) {
		return converted[0];
	}
	const fragment =
		document.createDocumentFragment() as unknown as DocumentFragment;
	for (const node of converted) {
		appendNode(node, fragment);
	}
	return fragment;
}

const parentNodeMembers = {
	children: {
		get(this: Node): HTMLCollection {
			const slots = _(this);
			let collection = slots.children;
			if (collection == null) {
				collection = new HTMLCollection(() => getElementChildren(this), this, (
					node,
				) => nodeTypeOf(node) === ELEMENT_NODE);
				ensureList(collection);
				slots.children = collection;
			}
			return collection;
		},
		configurable: true,
		enumerable: true,
	},
	firstElementChild: {
		get(this: Node): Element | null {
			for (let nodeSlots = _(this).firstChild;
				nodeSlots !== null;
				nodeSlots = nodeSlots.next) {
				const node = objectOf(nodeSlots);
				if (nodeTypeOf(node) === ELEMENT_NODE) {
					return node as Element;
				}
			}
			return null;
		},
		configurable: true,
		enumerable: true,
	},
	lastElementChild: {
		get(this: Node): Element | null {
			for (let nodeSlots = _(this).lastChild;
				nodeSlots !== null;
				nodeSlots = nodeSlots.previous) {
				const node = objectOf(nodeSlots);
				if (nodeTypeOf(node) === ELEMENT_NODE) {
					return node as Element;
				}
			}
			return null;
		},
		configurable: true,
		enumerable: true,
	},
	childElementCount: {
		get(this: Node): number {
			return countChildren(this, ELEMENT_NODE);
		},
		configurable: true,
		enumerable: true,
	},
	prepend: {
		value(this: Node, ...nodes: Insertable[]): void {
			const slots = _(this);
			const node = convertNodesIntoNode(nodes, slots.document);
			preInsert(node, this, objectOf(slots.firstChild));
		},
		configurable: true,
		enumerable: true,
		writable: true,
	},
	append: {
		value(this: Node, ...nodes: Insertable[]): void {
			const node = convertNodesIntoNode(nodes, _(this).document);
			preInsert(node, this, null);
		},
		configurable: true,
		enumerable: true,
		writable: true,
	},
	moveBefore: {
		value(this: Node, node: Node, child: Node | null): void {
			if (arguments.length < 2) {
				throw new TypeError("moveBefore needs a node and a child");
			}
			if (!(node instanceof Node)) {
				throw new TypeError("That is not a node");
			}
			if (child != null && !(child instanceof Node)) {
				throw new TypeError("That is not a node");
			}
			let reference = child ?? null;
			if (reference === node) {
				reference = objectOf(_(node).next);
			}
			moveNode(node, this, reference);
		},
		configurable: true,
		enumerable: true,
		writable: true,
	},
	replaceChildren: {
		value(this: Node, ...nodes: Insertable[]): void {
			const node = convertNodesIntoNode(nodes, _(this).document);
			ensurePreInsertionValidity(node, this, null, true);
			replaceAll(node, this);
		},
		configurable: true,
		enumerable: true,
		writable: true,
	},
	querySelector: {
		value(this: Node, selectors: string): Element | null {
			if (arguments.length < 1) {
				throw new TypeError("querySelector needs a selector");
			}
			try {
				return selectFirst(this, String(selectors), {scope: this});
			} catch (error) {
				throw asSyntaxError(error);
			}
		},
		configurable: true,
		enumerable: true,
		writable: true,
	},
	querySelectorAll: {
		value(this: Node, selectors: string): NodeList {
			if (arguments.length < 1) {
				throw new TypeError("querySelectorAll needs a selector");
			}
			try {
				return createStaticNodeList(
					selectAll(this, String(selectors), {scope: this}),
				);
			} catch (error) {
				throw asSyntaxError(error);
			}
		},
		configurable: true,
		enumerable: true,
		writable: true,
	},
};

const childNodeMembers = {
	before: {
		value(this: Node, ...nodes: Insertable[]): void {
			const slots = _(this);
			const parent = objectOf(slots.parent);
			if (parent === null) {
				return;
			}
			let viable = objectOf(slots.previous);
			while (viable !== null && nodes.includes(viable)) {
				viable = objectOf(_(viable).previous);
			}
			const node = convertNodesIntoNode(nodes, slots.document);
			if (viable === null) {
				preInsert(node, parent, objectOf(_(parent).firstChild));
			} else {
				preInsert(node, parent, objectOf(_(viable).next));
			}
		},
		configurable: true,
		enumerable: true,
		writable: true,
	},
	after: {
		value(this: Node, ...nodes: Insertable[]): void {
			const slots = _(this);
			const parent = objectOf(slots.parent);
			if (parent === null) {
				return;
			}
			let viable = objectOf(slots.next);
			while (viable !== null && nodes.includes(viable)) {
				viable = objectOf(_(viable).next);
			}
			const node = convertNodesIntoNode(nodes, slots.document);
			preInsert(node, parent, viable);
		},
		configurable: true,
		enumerable: true,
		writable: true,
	},
	replaceWith: {
		value(this: Node, ...nodes: Insertable[]): void {
			const slots = _(this);
			const parent = objectOf(slots.parent);
			if (parent === null) {
				return;
			}
			let viable = objectOf(slots.next);
			while (viable !== null && nodes.includes(viable)) {
				viable = objectOf(_(viable).next);
			}
			const node = convertNodesIntoNode(nodes, slots.document);
			if (objectOf(slots.parent) === parent) {
				replaceChild(this, node, parent);
			} else {
				preInsert(node, parent, viable);
			}
		},
		configurable: true,
		enumerable: true,
		writable: true,
	},
	remove: {
		value(this: Node): void {
			if (_(this).parent === null) {
				return;
			}
			removeNode(this);
		},
		configurable: true,
		enumerable: true,
		writable: true,
	},
};

const nonDocumentTypeChildNodeMembers = {
	previousElementSibling: {
		get(this: Node): Element | null {
			for (let nodeSlots = _(this).previous;
				nodeSlots !== null;
				nodeSlots = nodeSlots.previous) {
				const node = objectOf(nodeSlots);
				if (nodeTypeOf(node) === ELEMENT_NODE) {
					return node as Element;
				}
			}
			return null;
		},
		configurable: true,
		enumerable: true,
	},
	nextElementSibling: {
		get(this: Node): Element | null {
			for (let nodeSlots = _(this).next;
				nodeSlots !== null;
				nodeSlots = nodeSlots.next) {
				const node = objectOf(nodeSlots);
				if (nodeTypeOf(node) === ELEMENT_NODE) {
					return node as Element;
				}
			}
			return null;
		},
		configurable: true,
		enumerable: true,
	},
};

for (const prototype of [
	Document.prototype,
	DocumentFragment.prototype,
	Element.prototype,
]) {
	Object.defineProperties(prototype, parentNodeMembers);
}
for (const prototype of [
	DocumentType.prototype,
	Element.prototype,
	CharacterData.prototype,
]) {
	Object.defineProperties(prototype, childNodeMembers);
}
for (const prototype of [Element.prototype, CharacterData.prototype]) {
	Object.defineProperties(prototype, nonDocumentTypeChildNodeMembers);
}

// Marked [Unscopable] in the IDL, so a `with` statement over a node does
// not shadow a variable named after one of them.
function markUnscopable(prototype: object, names: string[]): void {
	const existing = (prototype as Record<symbol, Record<string, true>>)[
		Symbol.unscopables
	];
	const unscopables: Record<string, true> = existing === undefined
		? Object.create(null)
		: existing;
	for (const name of names) {
		unscopables[name] = true;
	}
	Object.defineProperty(prototype, Symbol.unscopables, {
		value: unscopables,
		configurable: true,
	});
}

const PARENT_NODE_UNSCOPABLES = ["append", "prepend", "replaceChildren"];
const CHILD_NODE_UNSCOPABLES = ["after", "before", "remove", "replaceWith"];

markUnscopable(Document.prototype, PARENT_NODE_UNSCOPABLES);
markUnscopable(DocumentFragment.prototype, PARENT_NODE_UNSCOPABLES);
markUnscopable(Element.prototype, [
	...PARENT_NODE_UNSCOPABLES,
	...CHILD_NODE_UNSCOPABLES,
	"slot",
]);
markUnscopable(CharacterData.prototype, CHILD_NODE_UNSCOPABLES);
markUnscopable(DocumentType.prototype, CHILD_NODE_UNSCOPABLES);

function getScrollTarget(
	xOrOptions?: number | globalThis.ScrollToOptions,
	y?: number,
): {left?: number; top?: number} {
	if (typeof xOrOptions === "object" && xOrOptions !== null) {
		return {left: xOrOptions.left, top: xOrOptions.top};
	}
	return {left: xOrOptions, top: y};
}

function scrollElementTo(
	this: Element,
	xOrOptions?: number | globalThis.ScrollToOptions,
	y?: number,
): void {
	const target = getScrollTarget(xOrOptions, y);
	if (target.left !== undefined) {
		this.scrollLeft = target.left;
	}
	if (target.top !== undefined) {
		this.scrollTop = target.top;
	}
}

function writeScrollOffset(
	element: globalThis.Element,
	axis: "left" | "top",
	value: number,
): void {
	let offsets = scrollOffsets.get(element);
	if (offsets === undefined) {
		offsets = {left: 0, top: 0};
		scrollOffsets.set(element, offsets);
	}
	offsets[axis] = value;
}

/** html and body scroll the document. */
function isDocumentScroller(element: Element): boolean {
	const document = _(element).document;
	return (
		document != null &&
		(element === (document.documentElement as unknown) ||
			element === (document.body as unknown))
	);
}

const scrolledElements = new WeakMap<Document, Set<Element>>();

// A write on an attached document rounds to whole cells (everything
// paints on the cell grid, like the document scroll), clamps into the
// range layout reports for the box, stores the value, and tells the
// engine what moved so the frame journal can price it. A box whose
// extent layout cannot report (a text control's value span, an opaque measured
// run) stores the write unclamped; the caret-reveal code owns those
// offsets and keeps them sane. On a headless document the write is
// stored and read back, and nothing moves.
// The scroll steps of "update the rendering": each box scrolled since the
// last frame gets one "scroll" event, and the document one that bubbles
// to the window, before the frame's callbacks run.
const pendingScrollTargets = new WeakMap<Document, Set<Element>>();
const reportedDocumentScrollTop = new WeakMap<Document, number>();

function setScrollOffset(
	element: Element,
	axis: "left" | "top",
	value: number,
): void {
	const attached = getAttachedDocument(element);
	if (attached === undefined) {
		writeScrollOffset(element, axis, toDouble(value));
		return;
	}
	const cell = getCellSize(element);
	const size = axis === "top" ? cell.height : cell.width;
	const elementSlots = _(element);
	if (isDocumentScroller(element)) {
		if (axis === "top") {
			scrollDocumentTo(elementSlots.document, Number(value) / size);
		}
		return;
	}
	const numeric = Number(value) / size;
	let next = Number.isFinite(numeric) ? Math.max(0, Math.round(numeric)) : 0;
	if (element.isConnected) {
		flushLayout(element);
		const room = _(attached).extra.layout.scrollRange(element, axis);
		if (room !== null) {
			next = Math.min(next, room);
		}
	}
	const previous = scrollOffsets.get(element)?.[axis] ?? 0;
	if (previous === next) {
		return;
	}
	writeScrollOffset(element, axis, next);
	const document = elementSlots.document;
	if (next !== 0) {
		let held = scrolledElements.get(document);
		if (held === undefined) {
			held = new Set();
			scrolledElements.set(document, held);
		}
		held.add(element);
	}
	// A vertical scroll is a run of rows the terminal may be able to shift for
	// us. A horizontal one is not, and dirties the frame like anything else.
	if (axis === "top") {
		recordScrollShift(attached, document, element, next - previous);
	} else {
		_(attached).extra.framebuffer.invalidate();
	}
	let pending = pendingScrollTargets.get(document);
	if (pending === undefined) {
		pending = new Set();
		pendingScrollTargets.set(document, pending);
	}
	pending.add(element);
	void _(attached).extra.render();
}

export function runScrollSteps(document: globalThis.Document): void {
	const attached = getAttachedDocument(document);
	if (attached === undefined) {
		return;
	}
	const top = _(attached).extra.framebuffer.scrollTop;
	if (top !== (reportedDocumentScrollTop.get(attached) ?? 0)) {
		reportedDocumentScrollTop.set(attached, top);
		dispatchAsUserAgent(
			attached,
			constructInternal(() => new Event("scroll", {bubbles: true})),
		);
		awaitScrollEnd(attached, attached);
	}
	const pending = pendingScrollTargets.get(attached);
	if (pending === undefined || pending.size === 0) {
		return;
	}
	const targets = [...pending];
	pending.clear();
	for (const target of targets) {
		dispatchAsUserAgent(target, constructInternal(() => new Event("scroll")));
		awaitScrollEnd(attached, target);
	}
}

// A scroll ends when nothing has scrolled for a moment. A wheel's ticks
// arrive a few frames apart, so each one restarts the wait, and the
// gesture ends once.
const SCROLL_END_MS = 100;

const scrollEnds = new WeakMap<
	Document,
	{targets: Set<Document | Element>; timer: ReturnType<typeof setTimeout>}
>();

function awaitScrollEnd(document: Document, target: Document | Element): void {
	const waiting = scrollEnds.get(document);
	if (waiting !== undefined) {
		clearTimeout(waiting.timer);
	}
	const targets = waiting?.targets ?? new Set<Document | Element>();
	// A removed box gets no scrollend, so the wait does not keep it alive
	// while other boxes go on scrolling.
	for (const held of targets) {
		if (held !== document && !(held as Element).isConnected) {
			targets.delete(held);
		}
	}
	targets.add(target);
	const timer = setTimeout(() => {
		scrollEnds.delete(document);
		if (getAttachedDocument(document) === undefined) {
			return;
		}
		for (const ended of targets) {
			if (ended === document) {
				dispatchAsUserAgent(
					ended,
					constructInternal(() => new Event("scrollend", {bubbles: true})),
				);
			} else if (ended.isConnected) {
				dispatchAsUserAgent(
					ended,
					constructInternal(() => new Event("scrollend")),
				);
			}
		}
	}, SCROLL_END_MS);
	scrollEnds.set(document, {targets, timer});
}

// The one box whose vertical scroll this frame can express as a scroll shift,
// meaning rows the terminal may shift instead of repainting. Repeated
// scrolls on one box add up. A second box scrolling means no single shift
// describes the frame, so the record is dropped in favor of the screen's
// dirty bit.
const scrollShifts = new WeakMap<Document, {element: Element; delta: number}>();

/**
 * Pull every stored scroll offset back into its box's scrollable range
 * against fresh layout. A mutation that shrinks a box's content must not
 * leave the box scrolled past what remains. Offsets are written to the
 * store directly, because the accessor's own clamp would re-enter the
 * engine's flush. A change sets the dirty bit, drops any pending scroll shift,
 * and requests a repaint. A clamp is not a scroll shift: it moves offsets the
 * journal already priced, and can move several boxes at once.
 */
export function clampScrollOffsets(document: globalThis.Document): void {
	const attached = getAttachedDocument(document);
	const held = scrolledElements.get(document as Document);
	if (attached === undefined || held === undefined) {
		return;
	}
	let changed = false;
	for (const element of held) {
		const offsets = scrollOffsets.get(element) ?? {left: 0, top: 0};
		if (offsets.left === 0 && offsets.top === 0) {
			held.delete(element);
			continue;
		}
		// A removed box has no box to be scrolled in, so it keeps no offset,
		// as a browser's does not, and the set does not keep it alive.
		if (!element.isConnected) {
			scrollOffsets.delete(element);
			held.delete(element);
			continue;
		}
		const extent = _(attached).extra.layout.getScrollExtent(element);
		const port = _(attached).extra.layout.contentRect(element);
		if (!extent || !port) {
			continue;
		}
		// An unknowable horizontal extent leaves that axis unclamped.
		const maxLeft = extent.width === null
			? offsets.left
			: Math.max(0, extent.width - Math.round(port.width));
		const maxTop = Math.max(0, extent.height - Math.round(port.height));
		if (offsets.left <= maxLeft && offsets.top <= maxTop) {
			continue;
		}
		writeScrollOffset(element, "left", Math.min(offsets.left, maxLeft));
		writeScrollOffset(element, "top", Math.min(offsets.top, maxTop));
		changed = true;
	}
	if (changed) {
		scrollShifts.delete(document as Document);
		_(attached).extra.framebuffer.invalidate();
		void _(attached).extra.render();
	}
}

function recordScrollShift(
	attached: AttachedDocument,
	document: Document,
	element: Element,
	delta: number,
): void {
	const shift = scrollShifts.get(document);
	if (shift === undefined) {
		scrollShifts.set(document, {element, delta});
	} else if (shift.element === element) {
		shift.delta += delta;
	} else {
		scrollShifts.delete(document);
		_(attached).extra.framebuffer.invalidate();
	}
}

/** Take the frame's scroll shift, if one survived until paint. */
export function takeScrollShift(
	document: globalThis.Document,
): {element: globalThis.Element; delta: number} | null {
	const shift = scrollShifts.get(document as Document);
	if (shift === undefined) {
		return null;
	}
	scrollShifts.delete(document as Document);
	return shift as unknown as {element: globalThis.Element; delta: number};
}

function insertAdjacent(
	element: Element,
	where: string,
	node: Node,
): Node | null {
	const elementSlots = _(element);
	switch (toASCIILowercase(where)) {
		case "beforebegin": {
			const parent = objectOf(elementSlots.parent);
			if (parent === null) {
				return null;
			}
			preInsert(node, parent, element);
			return node;
		}
		case "afterbegin":
			preInsert(node, element, objectOf(elementSlots.firstChild));
			return node;
		case "beforeend":
			preInsert(node, element, null);
			return node;
		case "afterend": {
			const parent = objectOf(elementSlots.parent);
			if (parent === null) {
				return null;
			}
			preInsert(node, parent, objectOf(elementSlots.next));
			return node;
		}
		default:
			throw domError("SyntaxError", `"${where}" is not a position`);
	}
}

function cloneNode(
	node: Node,
	document: Document | undefined,
	deep: boolean,
): Node {
	const nodeSlots = _(node);
	const target = document ?? nodeSlots.document;
	const copy = nodeSlots[kCloneSingle](target);
	const copySlots = _(copy);
	if (nodeTypeOf(copy) === DOCUMENT_NODE) {
		copySlots.document = copy as Document;
	}
	nodeSlots[kCloningSteps](copy, target, deep);
	if (nodeTypeOf(node) === ELEMENT_NODE) {
		const shadow = _((node as Element)).shadowRoot;
		if (shadow !== null && _(shadow).extra.clonable) {
			attachShadowRoot(
				copy as Element,
				_(shadow).extra.shadowMode,
				true,
				_(shadow).extra.serializable,
				_(shadow).extra.delegatesFocus,
				_(shadow).extra.slotAssignment,
				_(shadow).registry,
			);
			const copiedShadow = _((copy as Element)).shadowRoot as ShadowRoot;
			_(copiedShadow).extra.declarative = _(shadow).extra.declarative;
			for (
				let childSlots = _(shadow).firstChild;
				childSlots !== null;
				childSlots = childSlots.next
			) {
				const child = objectOf(childSlots);
				appendNode(
					cloneNode(child, _(copiedShadow).document, true),
					copiedShadow,
				);
			}
		}
	}
	if (deep) {
		for (let childSlots = nodeSlots.firstChild;
			childSlots !== null;
			childSlots = childSlots.next) {
			const child = objectOf(childSlots);
			appendNode(cloneNode(child, copySlots.document, true), copy);
		}
	}
	return copy;
}

function equalNodes(a: Node, b: Node): boolean {
	if (nodeTypeOf(a) !== nodeTypeOf(b)) {
		return false;
	}
	switch (nodeTypeOf(a)) {
		case DOCUMENT_TYPE_NODE: {
			const one = a as DocumentType;
			const two = b as DocumentType;
			if (
				_(one).extra.name !== _(two).extra.name ||
				_(one).extra.publicId !== _(two).extra.publicId ||
				_(one).extra.systemId !== _(two).extra.systemId
			) {
				return false;
			}
			break;
		}
		case ELEMENT_NODE: {
			const one = a as Element;
			const two = b as Element;
			if (
				_(one).namespace !== _(two).namespace ||
				_(one).prefix !== _(two).prefix ||
				_(one).localName !== _(two).localName ||
				_(one).attributeList.length !== _(two).attributeList.length
			) {
				return false;
			}
			for (const attribute of _(one).attributeList) {
				const other = getAttributeByNamespace(
					two,
					attribute.extra.namespace,
					attribute.extra.localName,
				);
				if (other === null || _(other).extra.value !== attribute.extra.value) {
					return false;
				}
			}
			break;
		}
		case ATTRIBUTE_NODE: {
			const one = a as Attr;
			const two = b as Attr;
			if (
				_(one).extra.namespace !== _(two).extra.namespace ||
				_(one).extra.localName !== _(two).extra.localName ||
				_(one).extra.value !== _(two).extra.value
			) {
				return false;
			}
			break;
		}
		case PROCESSING_INSTRUCTION_NODE: {
			const one = a as ProcessingInstruction;
			const two = b as ProcessingInstruction;
			if (
				_(one).extra.target !== _(two).extra.target ||
				_(one).data !== _(two).data
			) {
				return false;
			}
			break;
		}
		case TEXT_NODE:
		case CDATA_SECTION_NODE:
		case COMMENT_NODE:
			if (_((a as CharacterData)).data !== _((b as CharacterData)).data) {
				return false;
			}
			break;
		default:
			break;
	}
	let childA = objectOf(_(a).firstChild);
	let childB = objectOf(_(b).firstChild);
	while (childA !== null && childB !== null) {
		if (!equalNodes(childA, childB)) {
			return false;
		}
		childA = objectOf(_(childA).next);
		childB = objectOf(_(childB).next);
	}
	return childA === null && childB === null;
}

function locateNamespacePrefix(
	element: Element,
	namespace: string,
): string | null {
	const elementSlots = _(element);
	if (elementSlots.namespace === namespace && elementSlots.prefix !== null) {
		return elementSlots.prefix;
	}
	for (const attribute of elementSlots.attributeList) {
		if (
			attribute.extra.prefix === "xmlns" && attribute.extra.value === namespace
		) {
			return attribute.extra.localName;
		}
	}
	const parent = element.parentElement;
	return parent === null
		? null
		: locateNamespacePrefix(parent as unknown as Element, namespace);
}

function locateNamespace(node: Node, prefix: string | null): string | null {
	switch (nodeTypeOf(node)) {
		case ELEMENT_NODE: {
			// The two prefixes the XML specifications bind permanently.
			if (prefix === "xml") {
				return XML_NAMESPACE;
			}
			if (prefix === "xmlns") {
				return XMLNS_NAMESPACE;
			}
			const element = node as Element;
			if (_(element).namespace !== null && _(element).prefix === prefix) {
				return _(element).namespace;
			}
			for (const attribute of _(element).attributeList) {
				if (
					attribute.extra.namespace === XMLNS_NAMESPACE &&
					attribute.extra.prefix === "xmlns" &&
					attribute.extra.localName === prefix
				) {
					return attribute.extra.value === "" ? null : attribute.extra.value;
				}
				if (
					attribute.extra.namespace === XMLNS_NAMESPACE &&
					attribute.extra.prefix === null &&
					attribute.extra.localName === "xmlns" &&
					prefix === null
				) {
					return attribute.extra.value === "" ? null : attribute.extra.value;
				}
			}
			const parent = element.parentElement;
			return parent === null
				? null
				: locateNamespace(parent as unknown as Element, prefix);
		}
		case DOCUMENT_NODE: {
			const element = (node as Document).documentElement as unknown as Element |
				null;
			return element === null ? null : locateNamespace(element, prefix);
		}
		case DOCUMENT_TYPE_NODE:
		case DOCUMENT_FRAGMENT_NODE:
			return null;
		case ATTRIBUTE_NODE: {
			const owner = (node as Attr).ownerElement;
			return owner === null ? null : locateNamespace(owner, prefix);
		}
		default: {
			const parent = node.parentElement;
			return parent === null
				? null
				: locateNamespace(parent as unknown as Element, prefix);
		}
	}
}

const BEFORE = -1;
const EQUAL = 0;
const AFTER = 1;

function getNodeIndex(node: Node): number {
	let index = 0;
	for (
		let previousSlots = _(node).previous;
		previousSlots !== null;
		previousSlots = previousSlots.previous
	) {
		index++;
	}
	return index;
}

// Zero for a doctype, the data length for character data, and the
// child count for everything else.
function getNodeLength(node: Node): number {
	if (nodeTypeOf(node) === DOCUMENT_TYPE_NODE) {
		return 0;
	}
	if (isCharacterData(node)) {
		return _((node as CharacterData)).data.length;
	}
	let length = 0;
	for (let childSlots = _(node).firstChild;
		childSlots !== null;
		childSlots = childSlots.next) {
		length++;
	}
	return length;
}

function getAncestorChain(node: Node): Node[] {
	const chain: Node[] = [];
	for (
		let currentSlots: Slots<Node> | null = slotsOf(node);
		currentSlots !== null;
		currentSlots = currentSlots.parent
	) {
		const current = objectOf(currentSlots);
		chain.push(current);
	}
	chain.reverse();
	return chain;
}

function isPrecedingSibling(node: Node, other: Node): boolean {
	for (let nextSlots = _(node).next;
		nextSlots !== null;
		nextSlots = nextSlots.next) {
		const next = objectOf(nextSlots);
		if (next === other) {
			return true;
		}
	}
	return false;
}

// Both nodes must have the same root.
function comparePoints(
	nodeA: Node,
	offsetA: number,
	nodeB: Node,
	offsetB: number,
): number {
	if (nodeA === nodeB) {
		if (offsetA === offsetB) {
			return EQUAL;
		}
		return offsetA < offsetB ? BEFORE : AFTER;
	}
	const chainA = getAncestorChain(nodeA);
	const chainB = getAncestorChain(nodeB);
	let depth = 0;
	while (
		depth < chainA.length &&
		depth < chainB.length &&
		chainA[depth] === chainB[depth]
	) {
		depth++;
	}
	// One node is an ancestor of the other. Compare the ancestor's offset
	// against the index of the child that contains the other node.
	if (depth === chainA.length) {
		return getNodeIndex(chainB[depth]) < offsetA ? AFTER : BEFORE;
	}
	if (depth === chainB.length) {
		return getNodeIndex(chainA[depth]) < offsetB ? BEFORE : AFTER;
	}
	return isPrecedingSibling(chainA[depth], chainB[depth]) ? BEFORE : AFTER;
}

function registerNodeIterator(treeRoot: Node, iterator: NodeIterator): void {
	let set = nodeIteratorsByRoot.get(treeRoot);
	if (set === undefined) {
		set = new Set();
		nodeIteratorsByRoot.set(treeRoot, set);
	}
	set.add(iterator);
}

// The mutation steps' fast path.
let liveRangesEver = 0;

function rehomeLiveRange(range: Range, oldRoot: Node): void {
	const newRoot = getRoot(_(range).startNode);
	if (newRoot === oldRoot) {
		return;
	}
	liveRangesByRoot.get(oldRoot)?.delete(range);
	let set = liveRangesByRoot.get(newRoot);
	if (set === undefined) {
		set = new Set();
		liveRangesByRoot.set(newRoot, set);
	}
	set.add(range);
}

function forEachLiveRange(context: Node, steps: (range: Range) => void): void {
	if (liveRangesEver === 0) {
		return;
	}
	const set = liveRangesByRoot.get(getRoot(context));
	if (set === undefined) {
		return;
	}
	for (const range of set) {
		steps(range);
	}
}

// A node inserted before a child shifts every boundary point in the
// parent that is past that child.
function liveRangeInsertSteps(parent: Node, child: Node, count: number): void {
	const index = getLazyIndex(child);
	forEachLiveRange(parent, (range) => {
		const rangeSlots = _(range);
		if (rangeSlots.startNode === parent && rangeSlots.startOffset > index()) {
			rangeSlots.startOffset += count;
		}
		if (rangeSlots.endNode === parent && rangeSlots.endOffset > index()) {
			rangeSlots.endOffset += count;
		}
	});
}

// A node's index costs a walk over its earlier siblings, so it is taken
// only when a range has a boundary in the parent, and then once.
function getLazyIndex(node: Node): () => number {
	let index = -1;
	return () => (index < 0 ? (index = getNodeIndex(node)) : index);
}

// A boundary point inside the removed node collapses to the node's own
// position. A point after it in the parent moves back by one.
function liveRangePreRemoveSteps(node: Node): void {
	const parent = objectOf(_(node).parent) as Node;
	const index = getLazyIndex(node);
	forEachLiveRange(node, (range) => {
		const rangeSlots = _(range);
		if (isInclusiveAncestor(node, rangeSlots.startNode)) {
			rangeSlots.startNode = parent;
			rangeSlots.startOffset = index();
		}
		if (isInclusiveAncestor(node, rangeSlots.endNode)) {
			rangeSlots.endNode = parent;
			rangeSlots.endOffset = index();
		}
		if (rangeSlots.startNode === parent && rangeSlots.startOffset > index()) {
			rangeSlots.startOffset -= 1;
		}
		if (rangeSlots.endNode === parent && rangeSlots.endOffset > index()) {
			rangeSlots.endOffset -= 1;
		}
	});
}

// A point inside the replaced run collapses to its start. A point after
// the run moves by the difference in length.
function liveRangeReplaceDataSteps(
	node: CharacterData,
	offset: number,
	count: number,
	length: number,
): void {
	forEachLiveRange(node, (range) => {
		const rangeSlots = _(range);
		if (
			rangeSlots.startNode === node &&
			rangeSlots.startOffset > offset &&
			rangeSlots.startOffset <= offset + count
		) {
			rangeSlots.startOffset = offset;
		}
		if (
			rangeSlots.endNode === node &&
			rangeSlots.endOffset > offset &&
			rangeSlots.endOffset <= offset + count
		) {
			rangeSlots.endOffset = offset;
		}
		if (
			rangeSlots.startNode === node && rangeSlots.startOffset > offset + count
		) {
			rangeSlots.startOffset += length - count;
		}
		if (rangeSlots.endNode === node && rangeSlots.endOffset > offset + count) {
			rangeSlots.endOffset += length - count;
		}
	});
}

// A point past the split moves into the new node. A point that sat just
// after the node in its parent moves past the new node too.
function liveRangeSplitSteps(
	node: Text,
	newNode: Text,
	offset: number,
	parent: Node,
): void {
	const index = getLazyIndex(node);
	forEachLiveRange(node, (range) => {
		const rangeSlots = _(range);
		if (rangeSlots.startNode === node && rangeSlots.startOffset > offset) {
			rangeSlots.startNode = newNode;
			rangeSlots.startOffset -= offset;
		}
		if (rangeSlots.endNode === node && rangeSlots.endOffset > offset) {
			rangeSlots.endNode = newNode;
			rangeSlots.endOffset -= offset;
		}
		if (
			rangeSlots.startNode === parent && rangeSlots.startOffset === index() + 1
		) {
			rangeSlots.startOffset += 1;
		}
		if (rangeSlots.endNode === parent && rangeSlots.endOffset === index() + 1) {
			rangeSlots.endOffset += 1;
		}
	});
}

// Runs for each text node that normalize merges into the one before it.
// A point in the merged node, or one that referenced it in its parent,
// moves to where its data ended up.
function liveRangeNormalizeSteps(
	node: Text,
	currentNode: Text,
	length: number,
): void {
	const parent = objectOf(_(currentNode).parent) as Node;
	const index = getLazyIndex(currentNode);
	forEachLiveRange(node, (range) => {
		const rangeSlots = _(range);
		if (rangeSlots.startNode === currentNode) {
			rangeSlots.startNode = node;
			rangeSlots.startOffset += length;
		}
		if (rangeSlots.endNode === currentNode) {
			rangeSlots.endNode = node;
			rangeSlots.endOffset += length;
		}
		if (rangeSlots.startNode === parent && rangeSlots.startOffset === index()) {
			rangeSlots.startNode = node;
			rangeSlots.startOffset = length;
		}
		if (rangeSlots.endNode === parent && rangeSlots.endOffset === index()) {
			rangeSlots.endNode = node;
			rangeSlots.endOffset = length;
		}
	});
}

interface AbstractRangeSlots {
	startNode: Node;
	startOffset: number;
	endNode: Node;
	endOffset: number;
}

interface AbstractRange {
	readonly [internals]: AbstractRangeSlots;
}

class AbstractRange {
	constructor(
		startNode: Node,
		startOffset: number,
		endNode: Node,
		endOffset: number,
	) {
		seal(this, new.target, AbstractRange);
		if (new.target === AbstractRange) {
			throw new TypeError("AbstractRange cannot be constructed");
		}
		const slots = _(this);
		slots.startNode = startNode;
		slots.startOffset = startOffset;
		slots.endNode = endNode;
		slots.endOffset = endOffset;
	}

	get startContainer(): Node {
		return _(this).startNode;
	}

	get startOffset(): number {
		return _(this).startOffset;
	}

	get endContainer(): Node {
		return _(this).endNode;
	}

	get endOffset(): number {
		return _(this).endOffset;
	}

	get collapsed(): boolean {
		const slots = _(this);
		return (
			slots.startNode === slots.endNode && slots.startOffset === slots.endOffset
		);
	}
}

declareSealedRoot(AbstractRange);

Object.defineProperty(AbstractRange.prototype, Symbol.toStringTag, {
	value: "AbstractRange",
	configurable: true,
});

interface StaticRangeInit {
	startContainer: Node;
	startOffset: number;
	endContainer: Node;
	endOffset: number;
}

class StaticRange extends AbstractRange implements globalThis.StaticRange {
	constructor(init: StaticRangeInit) {
		super(...getStaticRangePoints(init));
	}
}

function getStaticRangePoints(init: unknown): [Node, number, Node, number] {
	const dictionary = toDictionary<Partial<StaticRangeInit>>(
		init,
		"StaticRange",
	);
	const members = [
		"startContainer",
		"startOffset",
		"endContainer",
		"endOffset",
	] as const;
	for (const member of members) {
		if (dictionary[member] === undefined) {
			throw new TypeError(`StaticRange needs a ${member}`);
		}
	}
	const startContainer = dictionary.startContainer as Node;
	const endContainer = dictionary.endContainer as Node;
	for (const container of [startContainer, endContainer]) {
		if (!(container instanceof Node)) {
			throw new TypeError("That is not a node");
		}
		if (
			nodeTypeOf(container) === DOCUMENT_TYPE_NODE ||
			nodeTypeOf(container) === ATTRIBUTE_NODE
		) {
			throw domError(
				"InvalidNodeTypeError",
				"A boundary point cannot be a doctype or an attribute",
			);
		}
	}
	return [
		startContainer,
		toUnsignedLong(dictionary.startOffset),
		endContainer,
		toUnsignedLong(dictionary.endOffset),
	];
}

Object.defineProperty(StaticRange.prototype, Symbol.toStringTag, {
	value: "StaticRange",
	configurable: true,
});

const START_TO_START = 0;
const START_TO_END = 1;
const END_TO_END = 2;
const END_TO_START = 3;

function rangeRoot(range: Range): Node {
	return getRoot(_(range).startNode);
}

function isContained(node: Node, range: Range): boolean {
	if (getRoot(node) !== rangeRoot(range)) {
		return false;
	}
	const rangeSlots = _(range);
	return (
		comparePoints(node, 0, rangeSlots.startNode, rangeSlots.startOffset) ===
		AFTER &&
		comparePoints(
			node,
			getNodeLength(node),
			rangeSlots.endNode,
			rangeSlots.endOffset,
		) === BEFORE
	);
}

function isPartiallyContained(node: Node, range: Range): boolean {
	const rangeSlots = _(range);
	const holdsStart = isInclusiveAncestor(node, rangeSlots.startNode);
	const holdsEnd = isInclusiveAncestor(node, rangeSlots.endNode);
	return holdsStart !== holdsEnd;
}

function getCommonAncestor(range: Range): Node {
	const rangeSlots = _(range);
	let container = rangeSlots.startNode;
	while (!isInclusiveAncestor(container, rangeSlots.endNode)) {
		container = objectOf(_(container).parent) as Node;
	}
	return container;
}

function setRangePoints(
	range: Range,
	startNode: Node,
	startOffset: number,
	endNode: Node,
	endOffset: number,
): void {
	moveRange(range, startNode, startOffset, endNode, endOffset);
	rangeBoundaryPointsChanged(range, "both");
}

function moveRange(
	range: Range,
	startNode: Node,
	startOffset: number,
	endNode: Node,
	endOffset: number,
): void {
	const rangeSlots = _(range);
	const oldRoot = getRoot(rangeSlots.startNode);
	rangeSlots.startNode = startNode;
	rangeSlots.startOffset = startOffset;
	rangeSlots.endNode = endNode;
	rangeSlots.endOffset = endOffset;
	rehomeLiveRange(range, oldRoot);
}

/** Any node except a doctype. */
function assertBoundaryNode(node: unknown): asserts node is Node {
	if (!(node instanceof Node)) {
		throw new TypeError("That is not a node");
	}
	if (nodeTypeOf(node) === DOCUMENT_TYPE_NODE) {
		throw domError(
			"InvalidNodeTypeError",
			"A boundary point cannot be a doctype",
		);
	}
}

/** The offset a boundary point settles on, or a throw. */
function checkBoundaryPoint(node: Node, offset: number): number {
	assertBoundaryNode(node);
	const at = toUnsignedLong(offset);
	if (at > getNodeLength(node)) {
		throw indexSizeError("The offset is past the end of the node");
	}
	return at;
}

function setRangeBoundary(
	range: Range,
	node: Node,
	offset: number,
	isStart: boolean,
): void {
	const at = checkBoundaryPoint(node, offset);
	const rangeSlots = _(range);
	const oldRoot = getRoot(rangeSlots.startNode);
	if (isStart) {
		if (
			rangeRoot(range) !== getRoot(node) ||
			comparePoints(node, at, rangeSlots.endNode, rangeSlots.endOffset) ===
			AFTER
		) {
			rangeSlots.endNode = node;
			rangeSlots.endOffset = at;
		}
		rangeSlots.startNode = node;
		rangeSlots.startOffset = at;
	} else {
		if (
			rangeRoot(range) !== getRoot(node) ||
			comparePoints(node, at, rangeSlots.startNode, rangeSlots.startOffset) ===
			BEFORE
		) {
			rangeSlots.startNode = node;
			rangeSlots.startOffset = at;
		}
		rangeSlots.endNode = node;
		rangeSlots.endOffset = at;
	}
	rehomeLiveRange(range, oldRoot);
	rangeBoundaryPointsChanged(range, isStart ? "start" : "end");
}

function getBoundaryParent(node: unknown): Node {
	if (!(node instanceof Node)) {
		throw new TypeError("That is not a node");
	}
	const parent = objectOf(_(node).parent);
	if (parent === null) {
		throw domError(
			"InvalidNodeTypeError",
			"That node has no parent to take a boundary point in",
		);
	}
	return parent;
}

function createFragment(document: Document): DocumentFragment {
	const fragment = new DocumentFragment();
	_(fragment).document = document;
	return fragment;
}

// The child the range starts inside, the children it contains whole,
// and the child it ends inside.
function getExtractionShape(range: Range): {
	commonAncestor: Node;
	firstPartiallyContained: Node | null;
	lastPartiallyContained: Node | null;
	containedChildren: Node[];
} {
	const commonAncestor = getCommonAncestor(range);
	const rangeSlots = _(range);
	const startNode = rangeSlots.startNode;
	const endNode = rangeSlots.endNode;
	let firstPartiallyContained: Node | null = null;
	const commonAncestorSlots = _(commonAncestor);
	if (!isInclusiveAncestor(startNode, endNode)) {
		for (
			let childSlots = commonAncestorSlots.firstChild;
			childSlots !== null;
			childSlots = childSlots.next
		) {
			const child = objectOf(childSlots);
			if (isPartiallyContained(child, range)) {
				firstPartiallyContained = child;
				break;
			}
		}
	}
	let lastPartiallyContained: Node | null = null;
	if (!isInclusiveAncestor(endNode, startNode)) {
		for (
			let childSlots = commonAncestorSlots.lastChild;
			childSlots !== null;
			childSlots = childSlots.previous
		) {
			const child = objectOf(childSlots);
			if (isPartiallyContained(child, range)) {
				lastPartiallyContained = child;
				break;
			}
		}
	}
	const containedChildren: Node[] = [];
	for (
		let childSlots = commonAncestorSlots.firstChild;
		childSlots !== null;
		childSlots = childSlots.next
	) {
		const child = objectOf(childSlots);
		if (!isContained(child, range)) {
			continue;
		}
		if (nodeTypeOf(child) === DOCUMENT_TYPE_NODE) {
			throw hierarchyRequestError("A doctype cannot be taken out of a range");
		}
		containedChildren.push(child);
	}
	return {
		commonAncestor,
		firstPartiallyContained,
		lastPartiallyContained,
		containedChildren,
	};
}

function getPointAfterExtraction(range: Range): [Node, number] {
	const rangeSlots = _(range);
	const startNode = rangeSlots.startNode;
	if (isInclusiveAncestor(startNode, rangeSlots.endNode)) {
		return [startNode, rangeSlots.startOffset];
	}
	let reference = startNode;
	while (
		_(reference).parent !== null &&
		!isInclusiveAncestor(
			objectOf(_(reference).parent) as Node,
			rangeSlots.endNode,
		)
	) {
		reference = objectOf(_(reference).parent) as Node;
	}
	return [objectOf(_(reference).parent) as Node, getNodeIndex(reference) + 1];
}

function cloneCharacterDataSlice(
	node: CharacterData,
	offset: number,
	count: number,
): CharacterData {
	const clone = cloneNode(node, undefined, false) as CharacterData;
	_(clone).data = _(node).data.slice(offset, offset + count);
	return clone;
}

interface RangeSlots extends AbstractRangeSlots {
	rangeSelection: Selection | null;
	// A range the selection made for itself and no author has been handed:
	// released when the selection moves on from it.
	selectionOwned: boolean;
}

interface Range {
	readonly [internals]: RangeSlots;
}

class Range extends AbstractRange implements globalThis.Range {
	static readonly START_TO_START = START_TO_START;
	static readonly START_TO_END = START_TO_END;
	static readonly END_TO_END = END_TO_END;
	static readonly END_TO_START = END_TO_START;
	declare readonly START_TO_START: globalThis.Range["START_TO_START"];
	declare readonly START_TO_END: globalThis.Range["START_TO_END"];
	declare readonly END_TO_END: globalThis.Range["END_TO_END"];
	declare readonly END_TO_START: globalThis.Range["END_TO_START"];

	// Installed on the prototype, where the engine that measures them is.
	declare getBoundingClientRect: () => globalThis.DOMRect;
	declare getClientRects: () => globalThis.DOMRectList;
	constructor() {
		const document = getCurrentDocument();
		super(document, 0, document, 0);
		const slots = _(this);
		slots.rangeSelection = null;
		slots.selectionOwned = false;
		registerLiveRange(this);
	}

	get commonAncestorContainer(): Node {
		return getCommonAncestor(this);
	}

	setStart(node: Node, offset: number): void {
		if (arguments.length < 2) {
			throw new TypeError("setStart needs a node and an offset");
		}
		setRangeBoundary(this, node, offset, true);
	}

	setEnd(node: Node, offset: number): void {
		if (arguments.length < 2) {
			throw new TypeError("setEnd needs a node and an offset");
		}
		setRangeBoundary(this, node, offset, false);
	}

	setStartBefore(node: Node): void {
		if (arguments.length < 1) {
			throw new TypeError("setStartBefore needs a node");
		}
		const parent = getBoundaryParent(node);
		setRangeBoundary(this, parent, getNodeIndex(node), true);
	}

	setStartAfter(node: Node): void {
		if (arguments.length < 1) {
			throw new TypeError("setStartAfter needs a node");
		}
		const parent = getBoundaryParent(node);
		setRangeBoundary(this, parent, getNodeIndex(node) + 1, true);
	}

	setEndBefore(node: Node): void {
		if (arguments.length < 1) {
			throw new TypeError("setEndBefore needs a node");
		}
		const parent = getBoundaryParent(node);
		setRangeBoundary(this, parent, getNodeIndex(node), false);
	}

	setEndAfter(node: Node): void {
		if (arguments.length < 1) {
			throw new TypeError("setEndAfter needs a node");
		}
		const parent = getBoundaryParent(node);
		setRangeBoundary(this, parent, getNodeIndex(node) + 1, false);
	}

	collapse(toStart = false): void {
		const slots = _(this);
		if (toStart) {
			setRangePoints(
				this,
				slots.startNode,
				slots.startOffset,
				slots.startNode,
				slots.startOffset,
			);
		} else {
			setRangePoints(
				this,
				slots.endNode,
				slots.endOffset,
				slots.endNode,
				slots.endOffset,
			);
		}
	}

	selectNode(node: Node): void {
		if (arguments.length < 1) {
			throw new TypeError("selectNode needs a node");
		}
		selectNodeWithin(this, node);
	}

	selectNodeContents(node: Node): void {
		if (arguments.length < 1) {
			throw new TypeError("selectNodeContents needs a node");
		}
		assertBoundaryNode(node);
		setRangePoints(this, node, 0, node, getNodeLength(node));
	}

	compareBoundaryPoints(how: number, sourceRange: Range): number {
		if (arguments.length < 2) {
			throw new TypeError("compareBoundaryPoints needs a how and a range");
		}
		if (!(sourceRange instanceof Range)) {
			throw new TypeError("That is not a range");
		}
		const which = toUnsignedShort(how);
		if (
			which !== START_TO_START &&
			which !== START_TO_END &&
			which !== END_TO_END &&
			which !== END_TO_START
		) {
			throw domError(
				"NotSupportedError",
				"That is not one of the boundary point comparisons",
			);
		}
		if (rangeRoot(this) !== rangeRoot(sourceRange)) {
			throw domError(
				"WrongDocumentError",
				"The two ranges are in different trees",
			);
		}
		const thisAtStart = which === START_TO_START || which === END_TO_START;
		const sourceAtStart = which === START_TO_START || which === START_TO_END;
		const sourceRangeSlots = _(sourceRange);
		const slots = _(this);
		return comparePoints(
			thisAtStart ? slots.startNode : slots.endNode,
			thisAtStart ? slots.startOffset : slots.endOffset,
			sourceAtStart ? sourceRangeSlots.startNode : sourceRangeSlots.endNode,
			sourceAtStart ? sourceRangeSlots.startOffset : sourceRangeSlots.endOffset,
		);
	}

	deleteContents(): void {
		if (this.collapsed) {
			return;
		}
		const slots = _(this);
		const startNode = slots.startNode;
		const startOffset = slots.startOffset;
		const endNode = slots.endNode;
		const endOffset = slots.endOffset;
		if (startNode === endNode && isCharacterData(startNode)) {
			replaceData(
				startNode as CharacterData,
				startOffset,
				endOffset - startOffset,
				"",
			);
			return;
		}
		const nodesToRemove: Node[] = [];
		for (const node of descendants(getCommonAncestor(this))) {
			if (!isContained(node, this)) {
				continue;
			}
			const parent = objectOf(_(node).parent);
			if (parent !== null && isContained(parent, this)) {
				continue;
			}
			nodesToRemove.push(node);
		}
		const [newNode, newOffset] = getPointAfterExtraction(this);
		setRangePoints(this, newNode, newOffset, newNode, newOffset);
		if (isCharacterData(startNode)) {
			const data = startNode as CharacterData;
			replaceData(data, startOffset, _(data).data.length - startOffset, "");
		}
		for (const node of nodesToRemove) {
			removeNode(node);
		}
		if (isCharacterData(endNode)) {
			replaceData(endNode as CharacterData, 0, endOffset, "");
		}
	}

	extractContents(): DocumentFragment {
		return extractRange(this);
	}

	cloneContents(): DocumentFragment {
		return cloneRangeContents(this);
	}

	insertNode(node: Node): void {
		if (arguments.length < 1) {
			throw new TypeError("insertNode needs a node");
		}
		insertIntoRange(this, node);
	}

	// The context is the start node's element (a text node's parent, or
	// the body when the start is the document), exactly the context
	// innerHTML would use for the same markup.
	createContextualFragment(markup: string): DocumentFragment {
		const start = _(this).startNode;
		const startSlots = _(start);
		let context: Element | null = start instanceof Element
			? start
			: objectOf(startSlots.parent) instanceof Element
			? (objectOf(startSlots.parent) as Element)
			: null;
		if (context === null) {
			const document = start instanceof Document
				? start
				: (ownerDocumentOf(start) as Document | null);
			context = (document?.body ?? document?.documentElement ?? null) as
			Element | null;
		}
		if (context === null) {
			throw domError("NotSupportedError", "The range has no context");
		}
		return parseHTMLFragment(String(markup ?? ""), context);
	}

	surroundContents(newParent: Node): void {
		if (arguments.length < 1) {
			throw new TypeError("surroundContents needs a node");
		}
		if (!(newParent instanceof Node)) {
			throw new TypeError("That is not a node");
		}
		const slots = _(this);
		for (const node of [slots.startNode, slots.endNode]) {
			let current: Node | null = node;
			while (current !== null) {
				if (isPartiallyContained(current, this) && !(current instanceof Text)) {
					throw domError(
						"InvalidStateError",
						"The range starts or ends inside a node it does not cover",
					);
				}
				current = objectOf(_(current).parent);
			}
		}
		const type = nodeTypeOf(newParent);
		if (
			type === DOCUMENT_NODE ||
			type === DOCUMENT_TYPE_NODE ||
			type === DOCUMENT_FRAGMENT_NODE
		) {
			throw domError(
				"InvalidNodeTypeError",
				"That node cannot be the parent of a range's contents",
			);
		}
		const fragment = extractRange(this);
		if (_(newParent).firstChild !== null) {
			replaceAll(null, newParent);
		}
		insertIntoRange(this, newParent);
		appendNode(fragment, newParent);
		selectNodeWithin(this, newParent);
	}

	cloneRange(): Range {
		const range = new Range();
		const slots = _(this);
		setRangePoints(
			range,
			slots.startNode,
			slots.startOffset,
			slots.endNode,
			slots.endOffset,
		);
		return range;
	}

	detach(): void {
		// The spec makes this a no-op.
	}

	isPointInRange(node: Node, offset: number): boolean {
		if (arguments.length < 2) {
			throw new TypeError("isPointInRange needs a node and an offset");
		}
		if (!(node instanceof Node)) {
			throw new TypeError("That is not a node");
		}
		if (getRoot(node) !== rangeRoot(this)) {
			return false;
		}
		if (nodeTypeOf(node) === DOCUMENT_TYPE_NODE) {
			throw domError(
				"InvalidNodeTypeError",
				"A boundary point cannot be a doctype",
			);
		}
		const at = toUnsignedLong(offset);
		if (at > getNodeLength(node)) {
			throw indexSizeError("The offset is past the end of the node");
		}
		const slots = _(this);
		return (
			comparePoints(node, at, slots.startNode, slots.startOffset) !== BEFORE &&
			comparePoints(node, at, slots.endNode, slots.endOffset) !== AFTER
		);
	}

	comparePoint(node: Node, offset: number): number {
		if (arguments.length < 2) {
			throw new TypeError("comparePoint needs a node and an offset");
		}
		if (!(node instanceof Node)) {
			throw new TypeError("That is not a node");
		}
		if (getRoot(node) !== rangeRoot(this)) {
			throw domError(
				"WrongDocumentError",
				"The point is in a different tree from the range",
			);
		}
		if (nodeTypeOf(node) === DOCUMENT_TYPE_NODE) {
			throw domError(
				"InvalidNodeTypeError",
				"A boundary point cannot be a doctype",
			);
		}
		const at = toUnsignedLong(offset);
		if (at > getNodeLength(node)) {
			throw indexSizeError("The offset is past the end of the node");
		}
		const slots = _(this);
		if (
			comparePoints(node, at, slots.startNode, slots.startOffset) === BEFORE
		) {
			return -1;
		}
		if (comparePoints(node, at, slots.endNode, slots.endOffset) === AFTER) {
			return 1;
		}
		return 0;
	}

	intersectsNode(node: Node): boolean {
		if (arguments.length < 1) {
			throw new TypeError("intersectsNode needs a node");
		}
		if (!(node instanceof Node)) {
			throw new TypeError("That is not a node");
		}
		if (getRoot(node) !== rangeRoot(this)) {
			return false;
		}
		const parent = objectOf(_(node).parent);
		if (parent === null) {
			return true;
		}
		const offset = getNodeIndex(node);
		const slots = _(this);
		return (
			comparePoints(parent, offset, slots.endNode, slots.endOffset) ===
			BEFORE &&
			comparePoints(parent, offset + 1, slots.startNode, slots.startOffset) ===
			AFTER
		);
	}

	override toString(): string {
		const slots = _(this);
		const startNode = slots.startNode;
		const endNode = slots.endNode;
		if (startNode === endNode && startNode instanceof Text) {
			return _(startNode).data.slice(slots.startOffset, slots.endOffset);
		}
		let string = "";
		if (startNode instanceof Text) {
			string += _(startNode).data.slice(slots.startOffset);
		}
		for (const node of descendants(getCommonAncestor(this))) {
			if (!(node instanceof Text)) {
				continue;
			}
			if (isContained(node, this)) {
				string += _(node).data;
			}
		}
		if (endNode instanceof Text) {
			string += _(endNode).data.slice(0, slots.endOffset);
		}
		return string;
	}
}

function registerLiveRange(range: Range): void {
	const root = getRoot(_(range).startNode);
	let set = liveRangesByRoot.get(root);
	if (set === undefined) {
		set = new Set();
		liveRangesByRoot.set(root, set);
	}
	set.add(range);
	liveRangesEver++;
}

// For a range the engine made for itself and is done with. An author's
// range stays live for as long as the author holds it.
function releaseLiveRange(range: Range): void {
	liveRangesByRoot.get(getRoot(_(range).startNode))?.delete(range);
}

function selectNodeWithin(range: Range, node: Node): void {
	const parent = getBoundaryParent(node);
	const index = getNodeIndex(node);
	setRangePoints(range, parent, index, parent, index + 1);
}

function extractRange(range: Range): DocumentFragment {
	const rangeSlots = _(range);
	const fragment = createFragment(_(rangeSlots.startNode).document);
	if (range.collapsed) {
		return fragment;
	}
	const startNode = rangeSlots.startNode;
	const startOffset = rangeSlots.startOffset;
	const endNode = rangeSlots.endNode;
	const endOffset = rangeSlots.endOffset;
	if (startNode === endNode && isCharacterData(startNode)) {
		const data = startNode as CharacterData;
		appendNode(
			cloneCharacterDataSlice(data, startOffset, endOffset - startOffset),
			fragment,
		);
		replaceData(data, startOffset, endOffset - startOffset, "");
		return fragment;
	}
	const shape = getExtractionShape(range);
	const [newNode, newOffset] = getPointAfterExtraction(range);
	setRangePoints(range, newNode, newOffset, newNode, newOffset);
	const first = shape.firstPartiallyContained;
	if (first !== null && isCharacterData(first)) {
		const data = startNode as CharacterData;
		const count = _(data).data.length - startOffset;
		appendNode(cloneCharacterDataSlice(data, startOffset, count), fragment);
		replaceData(data, startOffset, count, "");
	} else if (first !== null) {
		const clone = cloneNode(first, undefined, false);
		appendNode(clone, fragment);
		const subrange = new Range();
		setRangePoints(
			subrange,
			startNode,
			startOffset,
			first,
			getNodeLength(first),
		);
		appendNode(extractRange(subrange), clone);
		releaseLiveRange(subrange);
	}
	for (const child of shape.containedChildren) {
		appendNode(child, fragment);
	}
	const last = shape.lastPartiallyContained;
	if (last !== null && isCharacterData(last)) {
		const data = endNode as CharacterData;
		appendNode(cloneCharacterDataSlice(data, 0, endOffset), fragment);
		replaceData(data, 0, endOffset, "");
	} else if (last !== null) {
		const clone = cloneNode(last, undefined, false);
		appendNode(clone, fragment);
		const subrange = new Range();
		setRangePoints(subrange, last, 0, endNode, endOffset);
		appendNode(extractRange(subrange), clone);
		releaseLiveRange(subrange);
	}
	return fragment;
}

function cloneRangeContents(range: Range): DocumentFragment {
	const rangeSlots = _(range);
	const fragment = createFragment(_(rangeSlots.startNode).document);
	if (range.collapsed) {
		return fragment;
	}
	const startNode = rangeSlots.startNode;
	const startOffset = rangeSlots.startOffset;
	const endNode = rangeSlots.endNode;
	const endOffset = rangeSlots.endOffset;
	if (startNode === endNode && isCharacterData(startNode)) {
		const data = startNode as CharacterData;
		appendNode(
			cloneCharacterDataSlice(data, startOffset, endOffset - startOffset),
			fragment,
		);
		return fragment;
	}
	const shape = getExtractionShape(range);
	const first = shape.firstPartiallyContained;
	if (first !== null && isCharacterData(first)) {
		const data = startNode as CharacterData;
		const count = _(data).data.length - startOffset;
		appendNode(cloneCharacterDataSlice(data, startOffset, count), fragment);
	} else if (first !== null) {
		const clone = cloneNode(first, undefined, false);
		appendNode(clone, fragment);
		const subrange = new Range();
		setRangePoints(
			subrange,
			startNode,
			startOffset,
			first,
			getNodeLength(first),
		);
		appendNode(cloneRangeContents(subrange), clone);
		releaseLiveRange(subrange);
	}
	for (const child of shape.containedChildren) {
		appendNode(cloneNode(child, undefined, true), fragment);
	}
	const last = shape.lastPartiallyContained;
	if (last !== null && isCharacterData(last)) {
		const data = endNode as CharacterData;
		appendNode(cloneCharacterDataSlice(data, 0, endOffset), fragment);
	} else if (last !== null) {
		const clone = cloneNode(last, undefined, false);
		appendNode(clone, fragment);
		const subrange = new Range();
		setRangePoints(subrange, last, 0, endNode, endOffset);
		appendNode(cloneRangeContents(subrange), clone);
		releaseLiveRange(subrange);
	}
	return fragment;
}

function insertIntoRange(range: Range, node: Node): void {
	if (!(node instanceof Node)) {
		throw new TypeError("That is not a node");
	}
	const rangeSlots = _(range);
	const startNode = rangeSlots.startNode;
	const type = nodeTypeOf(startNode);
	if (
		type === PROCESSING_INSTRUCTION_NODE ||
		type === COMMENT_NODE ||
		(startNode instanceof Text && _(startNode).parent === null) ||
		startNode === node
	) {
		throw hierarchyRequestError("That range cannot take an inserted node");
	}
	let referenceNode: Node | null;
	if (startNode instanceof Text) {
		referenceNode = startNode;
	} else {
		let child = objectOf(_(startNode).firstChild);
		for (
			let index = 0; index < rangeSlots.startOffset && child !== null; index++
		) {
			child = objectOf(_(child).next);
		}
		referenceNode = child;
	}
	const parent = referenceNode === null
		? startNode
		: (objectOf(_(referenceNode).parent) as Node);
	ensurePreInsertionValidity(node, parent, referenceNode);
	if (startNode instanceof Text) {
		referenceNode = startNode.splitText(rangeSlots.startOffset);
	}
	const nodeSlots = _(node);
	if (node === referenceNode) {
		referenceNode = objectOf(nodeSlots.next);
	}
	if (nodeSlots.parent !== null) {
		removeNode(node);
	}
	let newOffset = referenceNode === null
		? getNodeLength(parent)
		: getNodeIndex(referenceNode);
	newOffset += nodeTypeOf(node) === DOCUMENT_FRAGMENT_NODE
		? getNodeLength(node)
		: 1;
	preInsert(node, parent, referenceNode);
	if (range.collapsed) {
		rangeSlots.endNode = parent;
		rangeSlots.endOffset = newOffset;
		rangeBoundaryPointsChanged(range, "end");
	}
}

for (const [name, value] of [
	["START_TO_START", START_TO_START],
	["START_TO_END", START_TO_END],
	["END_TO_END", END_TO_END],
	["END_TO_START", END_TO_START],
] as Array<[string, number]>) {
	Object.defineProperty(Range.prototype, name, {value, enumerable: true});
}

ceReactions(Range.prototype, [
	"deleteContents",
	"extractContents",
	"cloneContents",
	"insertNode",
	"surroundContents",
]);

Object.defineProperty(Range.prototype, Symbol.toStringTag, {
	value: "Range",
	configurable: true,
});

// The start container, or the element containing it when it is a text
// node. Whether to subtract the document scroll depends on the box the range is
// in, not on the range.
function rangeAnchor(range: Range): Element | null {
	const container = range.startContainer;
	return nodeTypeOf(container) === ELEMENT_NODE
		? (container as unknown as Element)
		: ((container as unknown as Node).parentElement as Element | null);
}

// Range geometry reads the same layout the element members read, and
// converts the same way. The caret and selection painters read the
// layout's document-relative rects directly, as scrollIntoView does.
Object.defineProperties(Range.prototype, {
	getBoundingClientRect: {
		value(this: Range): globalThis.DOMRect {
			return getBoundingRect(getRangeClientRects(this));
		},
		writable: true,
		configurable: true,
	},
	getClientRects: {
		value(this: Range): globalThis.DOMRectList {
			return createRectList(getRangeClientRects(this));
		},
		writable: true,
		configurable: true,
	},
});

// In tree order, as CSSOM View lists them: the border boxes of each
// element the range contains whose parent it does not, and the selected
// part of each text node.
function getRangeClientRects(range: Range): globalThis.DOMRect[] {
	const attached = getAttachedDocument(range.startContainer);
	if (attached === undefined) {
		return [];
	}
	flushLayout(range.startContainer);
	const layout = _(attached).extra.layout;
	const anchor = rangeAnchor(range);
	if (range.collapsed) {
		return layout
			.getRangeRects(range)
			.map((rect) => toViewportRect(attached, rect, anchor));
	}
	const rects: globalThis.DOMRect[] = [];
	const visit = (node: Node): void => {
		const nodeSlots = _(node);
		if (nodeTypeOf(node) === TEXT_NODE && range.intersectsNode(node)) {
			const text = node as Text;
			const from = range.startContainer === text ? range.startOffset : 0;
			const to = range.endContainer === text
				? range.endOffset
				: _(text).data.length;
			for (const span of layout.getTextSpans(text, from, to)) {
				rects.push(toViewportRect(attached, span.rect, anchor));
			}
		} else if (
			nodeTypeOf(node) === ELEMENT_NODE &&
			isContained(node, range) &&
			(nodeSlots.parent === null ||
				!isContained(objectOf(nodeSlots.parent)!, range))
		) {
			for (const rect of layout.getRects(node as Element)) {
				rects.push(toViewportRect(attached, rect, node as Element));
			}
		}
		for (let childSlots = nodeSlots.firstChild;
			childSlots !== null;
			childSlots = childSlots.next) {
			const child = objectOf(childSlots);
			visit(child);
		}
	};
	visit(range.commonAncestorContainer as unknown as Node);
	return rects;
}

// All zero with nothing listed, the first rect when every rect is empty,
// and otherwise the union of the rects that are not.
function getBoundingRect(rects: globalThis.DOMRect[]): globalThis.DOMRect {
	if (rects.length === 0) {
		return new DOMRect(0, 0, 0, 0);
	}
	const sized = rects.filter((rect) => rect.width !== 0 && rect.height !== 0);
	return sized.length === 0 ? rects[0] : unionRect(sized);
}

// Every change the Range API makes to the boundary points fires a
// selectionchange event on the selection this range belongs to.
function rangeBoundaryPointsChanged(
	range: Range,
	which: "start" | "end" | "both",
): void {
	const selection = _(range).rangeSelection;
	if (selection !== null) {
		selectionChanged(selection, which);
	}
	rangeHighlightsChanged(range);
}

/** At most one per task. */
function scheduleSelectionChange(document: Document): void {
	// A selection move is not a mutation and no record names the rows it
	// covers, so the repaint is requested here, before the coalescing guard
	// below. That guard drops the second move in a task but not its paint.
	const attached = getAttachedDocument(document);
	if (attached !== undefined) {
		_(attached).extra.framebuffer.invalidate();
		void _(attached).extra.render();
	}
	const documentSlots = _(document);
	if (documentSlots.extra.selectionChangeScheduled) {
		return;
	}
	documentSlots.extra.selectionChangeScheduled = true;
	setTimeout(() => {
		documentSlots.extra.selectionChangeScheduled = false;
		document.dispatchEvent(
			constructInternal(() => new Event("selectionchange")),
		);
	}, 0);
}

// A shadow root sits at its host, before the host's children, so a
// boundary point in a shadow tree can be ordered against one in the
// light tree.
function getComposedParent(node: Node): Node | null {
	const parent = objectOf(_(node).parent);
	if (parent !== null) {
		return parent;
	}
	return isShadowRoot(node)
		? (_((node as ShadowRoot)).extra.host as Node)
		: null;
}

function getComposedChain(node: Node): Node[] {
	const chain: Node[] = [];
	for (
		let current: Node | null = node;
		current !== null;
		current = getComposedParent(current)
	) {
		chain.push(current);
	}
	chain.reverse();
	return chain;
}

/** A shadow root precedes its host's children. */
function getComposedIndex(node: Node): number {
	return _(node).parent === null && isShadowRoot(node)
		? -1
		: getNodeIndex(node);
}

// Treats a shadow tree as part of the tree its host is in.
function compareComposedPoints(
	nodeA: Node,
	offsetA: number,
	nodeB: Node,
	offsetB: number,
): number {
	if (nodeA === nodeB) {
		if (offsetA === offsetB) {
			return EQUAL;
		}
		return offsetA < offsetB ? BEFORE : AFTER;
	}
	const chainA = getComposedChain(nodeA);
	const chainB = getComposedChain(nodeB);
	let depth = 0;
	while (
		depth < chainA.length &&
		depth < chainB.length &&
		chainA[depth] === chainB[depth]
	) {
		depth++;
	}
	if (depth === chainA.length) {
		return getComposedIndex(chainB[depth]) < offsetA ? AFTER : BEFORE;
	}
	if (depth === chainB.length) {
		return getComposedIndex(chainA[depth]) < offsetB ? BEFORE : AFTER;
	}
	return getComposedIndex(chainA[depth]) < getComposedIndex(chainB[depth])
		? BEFORE
		: AFTER;
}

// A selection stores each boundary point as a collapsed live range.
function createLivePoint(node: Node, offset: number): Range {
	const point = new Range();
	movePoint(point, node, offset);
	return point;
}

function movePoint(point: Range, node: Node, offset: number): void {
	moveRange(point, node, offset, node, offset);
}

let selectionUnderConstruction: Document | null = null;

function createSelection(document: Document): Selection {
	selectionUnderConstruction = document;
	try {
		return new Selection();
	} finally {
		selectionUnderConstruction = null;
	}
}

interface SelectionSlots {
	document: Document;
	// The range the Range API sees, which lives in a single tree.
	range: Range | null;
	// The composed boundary points, in tree order, each a collapsed live
	// range so tree mutations move it. A selection that crosses a shadow
	// boundary keeps both of these while its range collapses. Made once
	// and moved, so nothing needs to release them.
	start: Range;
	end: Range;
	direction: "forwards" | "backwards" | "directionless";
}

interface Selection {
	readonly [internals]: SelectionSlots;
}

class Selection implements globalThis.Selection {
	constructor() {
		seal(this, new.target, Selection);
		const slots = _(this);
		slots.range = null;
		slots.direction = "directionless";
		if (selectionUnderConstruction === null) {
			throw new TypeError("Selection cannot be constructed");
		}
		slots.document = selectionUnderConstruction;
		slots.start = createLivePoint(slots.document, 0);
		slots.end = createLivePoint(slots.document, 0);
	}

	get anchorNode(): Node | null {
		const anchor = getAnchorPoint(this);
		if (anchor === null || !isInDocument(this, anchor[0])) {
			return null;
		}
		return anchor[0];
	}

	get anchorOffset(): number {
		const anchor = getAnchorPoint(this);
		if (anchor === null || !isInDocument(this, anchor[0])) {
			return 0;
		}
		return anchor[1];
	}

	get focusNode(): Node | null {
		const focus = getFocusPoint(this);
		if (focus === null || !isInDocument(this, focus[0])) {
			return null;
		}
		return focus[0];
	}

	get focusOffset(): number {
		const focus = getFocusPoint(this);
		if (focus === null || !isInDocument(this, focus[0])) {
			return 0;
		}
		return focus[1];
	}

	get isCollapsed(): boolean {
		const range = _(this).range;
		return range === null || range.collapsed;
	}

	get rangeCount(): number {
		return getDocumentRange(this) === null ? 0 : 1;
	}

	get type(): string {
		const range = getDocumentRange(this);
		if (range === null) {
			return "None";
		}
		return range.collapsed ? "Caret" : "Range";
	}

	get direction(): string {
		const slots = _(this);
		if (slots.range === null) {
			return "none";
		}
		if (slots.direction === "forwards") {
			return "forward";
		}
		if (slots.direction === "backwards") {
			return "backward";
		}
		return "none";
	}

	getRangeAt(index: number): Range {
		if (arguments.length < 1) {
			throw new TypeError("getRangeAt needs an index");
		}
		const range = getDocumentRange(this);
		if (toUnsignedLong(index) !== 0 || range === null) {
			throw indexSizeError("The selection has no range at that index");
		}
		_(range).selectionOwned = false;
		return range;
	}

	addRange(range: Range): void {
		if (arguments.length < 1) {
			throw new TypeError("addRange needs a range");
		}
		if (!(range instanceof Range)) {
			throw new TypeError("That is not a range");
		}
		const rangeSlots = _(range);
		if (!isInDocument(this, rangeSlots.startNode)) {
			return;
		}
		if (this.rangeCount !== 0) {
			return;
		}
		associateSelectionRange(
			this,
			range,
			[rangeSlots.startNode, rangeSlots.startOffset],
			[rangeSlots.endNode, rangeSlots.endOffset],
			"forwards",
		);
	}

	removeRange(range: Range): void {
		if (arguments.length < 1) {
			throw new TypeError("removeRange needs a range");
		}
		if (!(range instanceof Range)) {
			throw new TypeError("That is not a range");
		}
		if (range !== _(this).range) {
			throw notFoundError("That range is not the selection's range");
		}
		this.removeAllRanges();
	}

	removeAllRanges(): void {
		const slots = _(this);
		const range = slots.range;
		if (range === null) {
			return;
		}
		_(range).rangeSelection = null;
		if (_(range).selectionOwned) {
			releaseLiveRange(range);
		}
		slots.range = null;
		slots.direction = "directionless";
		scheduleSelectionChange(slots.document);
	}

	empty(): void {
		this.removeAllRanges();
	}

	getComposedRanges(
		options?: globalThis.GetComposedRangesOptions,
	): StaticRange[] {
		const dictionary = toDictionary<{shadowRoots?: unknown}>(
			options,
			"getComposedRanges",
		);
		const roots: ShadowRoot[] = [];
		if (dictionary.shadowRoots != null) {
			for (const root of dictionary.shadowRoots as Iterable<unknown>) {
				if (!(root instanceof ShadowRoot)) {
					throw new TypeError("That is not a shadow root");
				}
				roots.push(root);
			}
		}
		const slots = _(this);
		if (slots.range === null) {
			return [];
		}
		const start = slots.start;
		const end = slots.end;
		const rescope = (
			node: Node,
			offset: number,
			after: boolean,
		): [Node, number] => {
			let current = node;
			let at = offset;
			for (;;) {
				const root = getRoot(current);
				if (!isShadowRoot(root)) {
					break;
				}
				if (
					roots.some((given) => isShadowIncludingInclusiveAncestor(root, given))
				) {
					break;
				}
				const host = _((root as ShadowRoot)).extra.host as Element;
				at = getNodeIndex(host) + (after ? 1 : 0);
				const parent = objectOf(_(host).parent);
				if (parent === null) {
					break;
				}
				current = parent;
			}
			return [current, at];
		};
		const startSlots = _(start);
		const [startNode, startOffset] = rescope(
			startSlots.startNode,
			startSlots.startOffset,
			false,
		);
		const endSlots = _(end);
		const [endNode, endOffset] = rescope(
			endSlots.endNode,
			endSlots.endOffset,
			true,
		);
		return [
			new StaticRange({
				startContainer: startNode,
				startOffset,
				endContainer: endNode,
				endOffset,
			}),
		];
	}

	collapse(node: Node | null, offset = 0): void {
		if (arguments.length < 1) {
			throw new TypeError("collapse needs a node");
		}
		if (node == null) {
			this.removeAllRanges();
			return;
		}
		assertBoundaryNode(node);
		const at = toUnsignedLong(offset);
		if (at > getNodeLength(node)) {
			throw indexSizeError("The offset is past the end of the node");
		}
		const slots = _(this);
		if (!isShadowIncludingInclusiveAncestor(slots.document, node)) {
			return;
		}
		const point: [Node, number] = [node, at];
		associateSelectionRange(
			this,
			createRangeBetween(this, point, point),
			point,
			point,
			slots.direction,
		);
	}

	setPosition(node: Node | null, offset = 0): void {
		if (arguments.length < 1) {
			throw new TypeError("setPosition needs a node");
		}
		this.collapse(node, offset);
	}

	collapseToStart(): void {
		const slots = _(this);
		const range = slots.range;
		if (range === null) {
			throw domError("InvalidStateError", "The selection has no range");
		}
		const point: [Node, number] = [_(range).startNode, _(range).startOffset];
		associateSelectionRange(
			this,
			createRangeBetween(this, point, point),
			point,
			point,
			slots.direction,
		);
	}

	collapseToEnd(): void {
		const slots = _(this);
		const range = slots.range;
		if (range === null) {
			throw domError("InvalidStateError", "The selection has no range");
		}
		const point: [Node, number] = [_(range).endNode, _(range).endOffset];
		associateSelectionRange(
			this,
			createRangeBetween(this, point, point),
			point,
			point,
			slots.direction,
		);
	}

	extend(node: Node, offset = 0): void {
		if (arguments.length < 1) {
			throw new TypeError("extend needs a node");
		}
		if (!(node instanceof Node)) {
			throw new TypeError("That is not a node");
		}
		const slots = _(this);
		if (!isShadowIncludingInclusiveAncestor(slots.document, node)) {
			return;
		}
		if (slots.range === null) {
			throw domError("InvalidStateError", "The selection has no range");
		}
		const anchor = getAnchorPoint(this) as [Node, number];
		const focus: [Node, number] = [node, toUnsignedLong(offset)];
		const anchorFirst =
			compareComposedPoints(anchor[0], anchor[1], focus[0], focus[1]) !== AFTER;
		const range = anchorFirst
			? createRangeBetween(this, anchor, focus)
			: createRangeBetween(this, focus, anchor);
		associateSelectionRange(
			this,
			range,
			anchor,
			focus,
			anchorFirst ? "forwards" : "backwards",
		);
	}

	setBaseAndExtent(
		anchorNode: Node,
		anchorOffset: number,
		focusNode: Node,
		focusOffset: number,
	): void {
		if (arguments.length < 4) {
			throw new TypeError("setBaseAndExtent needs two boundary points");
		}
		if (!(anchorNode instanceof Node) || !(focusNode instanceof Node)) {
			throw new TypeError("That is not a node");
		}
		const anchorAt = toUnsignedLong(anchorOffset);
		const focusAt = toUnsignedLong(focusOffset);
		if (
			anchorAt > getNodeLength(anchorNode) || focusAt > getNodeLength(focusNode)
		) {
			throw indexSizeError("The offset is past the end of the node");
		}
		const slots = _(this);
		if (
			!isShadowIncludingInclusiveAncestor(slots.document, anchorNode) ||
			!isShadowIncludingInclusiveAncestor(slots.document, focusNode)
		) {
			return;
		}
		const anchor: [Node, number] = [anchorNode, anchorAt];
		const focus: [Node, number] = [focusNode, focusAt];
		const anchorFirst =
			compareComposedPoints(anchorNode, anchorAt, focusNode, focusAt) !== AFTER;
		const range = anchorFirst
			? createRangeBetween(this, anchor, focus)
			: createRangeBetween(this, focus, anchor);
		associateSelectionRange(
			this,
			range,
			anchor,
			focus,
			anchorFirst ? "forwards" : "backwards",
		);
	}

	selectAllChildren(node: Node): void {
		if (arguments.length < 1) {
			throw new TypeError("selectAllChildren needs a node");
		}
		assertBoundaryNode(node);
		if (getRoot(node) !== _(this).document) {
			return;
		}
		let childCount = 0;
		for (let childSlots = _(node).firstChild;
			childSlots !== null;
			childSlots = childSlots.next) {
			childCount++;
		}
		const anchor: [Node, number] = [node, 0];
		const focus: [Node, number] = [node, childCount];
		associateSelectionRange(
			this,
			createRangeBetween(this, anchor, focus),
			anchor,
			focus,
			"forwards",
		);
	}

	deleteFromDocument(): void {
		const range = getDocumentRange(this);
		if (range === null) {
			return;
		}
		range.deleteContents();
	}

	containsNode(node: Node, allowPartialContainment = false): boolean {
		if (arguments.length < 1) {
			throw new TypeError("containsNode needs a node");
		}
		if (!(node instanceof Node)) {
			throw new TypeError("That is not a node");
		}
		const slots = _(this);
		const range = slots.range;
		if (range === null || getRoot(node) !== slots.document) {
			return false;
		}
		if (rangeRoot(range) !== slots.document) {
			return false;
		}
		const length = getNodeLength(node);
		if (allowPartialContainment) {
			return (
				comparePoints(
					_(range).startNode,
					_(range).startOffset,
					node,
					length,
				) !==
				AFTER &&
				comparePoints(_(range).endNode, _(range).endOffset, node, 0) !== BEFORE
			);
		}
		return (
			comparePoints(_(range).startNode, _(range).startOffset, node, 0) !==
			AFTER &&
			comparePoints(_(range).endNode, _(range).endOffset, node, length) !==
			BEFORE
		);
	}

	// Keyboard-style motion, in the one place a page can request it.
	// `alter` is "move" (collapse where the motion lands) or "extend" (move
	// the focus there and leave the anchor). A "move" over a range starts
	// from the edge it is heading toward, so a forward character move over a
	// selection collapses to its end without going further, as browsers do.
	// "left" and "right" mean "backward" and "forward"; a right-to-left
	// run's visual order is not followed.
	//
	// "character" and "word" are computed from the text. "line" and
	// "lineboundary" depend on laid-out lines rather than the string, so
	// they need a document attached to a terminal and do nothing without one.
	// A line's ends are its first and last text in tree order, which is its
	// visual order only for left-to-right text. "sentence", "paragraph" and
	// their boundaries are not implemented. Anything unrecognized does
	// nothing, as in a browser.
	modify(alter?: string, direction?: string, granularity?: string): void {
		const how = String(alter ?? "move").toLowerCase();
		const where = String(direction ?? "forward").toLowerCase();
		const unit = String(granularity ?? "character").toLowerCase();
		if (how !== "move" && how !== "extend") {
			return;
		}
		const forward = where === "forward" || where === "right";
		if (!forward && where !== "backward" && where !== "left") {
			return;
		}
		const range = getDocumentRange(this);
		if (range === null) {
			return;
		}
		const extending = how === "extend";
		const from = extending
			? (getFocusPoint(this) as [Node, number])
			: forward
					? ([_(range).endNode, _(range).endOffset] as [Node, number])
					: ([_(range).startNode, _(range).startOffset] as [Node, number]);
		// Collapsing a range by a character is the whole motion. The caret
		// lands on the edge the direction points at, not one character past it.
		const to = !extending && !range.collapsed && unit === "character"
			? from
			: getModifiedPoint(this, from, forward, unit);
		if (to === null) {
			return;
		}
		if (extending) {
			this.extend(to[0], to[1]);
			return;
		}
		this.setBaseAndExtent(to[0], to[1], to[0], to[1]);
	}

	// The rendered text, as the Selection API says, rather than the range's
	// DOM text: nothing from a closed details, a select's options, a
	// textarea's default value, or user-select: none content.
	toString(): string {
		const slots = _(this);
		const range = slots.range;
		if (range === null) {
			return "";
		}
		const document = slots.document;
		const attached = getAttachedDocument(document);
		// A document nothing renders has no rendered text.
		if (attached === undefined) {
			return range.toString();
		}
		_(attached).extra.layout.performLayout();
		const run = flattenSelectionText(getSelectionTextNodes(document, attached));
		const start = getRenderedIndex(
			run,
			range.startContainer,
			range.startOffset,
			"start",
		);
		const end = getRenderedIndex(
			run,
			range.endContainer,
			range.endOffset,
			"end",
		);
		return end <= start ? "" : run.text.slice(start, end);
	}
}

declareSealedRoot(Selection);

// A range boundary in unpainted content maps to the painted text that
// follows it, or for an end, that precedes it.
function getRenderedIndex(
	run: SelectionText,
	node: Node,
	offset: number,
	side: "start" | "end",
): number {
	const index = getSelectionIndex(run, node, offset);
	if (index !== null) {
		return index;
	}
	if (side === "start") {
		for (const part of run.parts) {
			if (comparePoints(node, offset, part.node, 0) <= 0) {
				return part.start;
			}
		}
		return run.text.length;
	}
	for (let i = run.parts.length - 1; i >= 0; i--) {
		const part = run.parts[i];
		if (comparePoints(part.node, part.length, node, offset) <= 0) {
			return part.start + part.length;
		}
	}
	return 0;
}

// Character and word motion are string operations, and a caret crosses
// from one text node into the next without noticing, so both work on the
// document's painted text as one string rather than one node at a time.
// Built per call. A selection moves at keystroke speed, and a cache of
// the document's text would need invalidating on every mutation.
// A part is a painted text node, or a <br>, which is one character of
// its own: the caret can rest on an empty line. Parts in different
// blocks are a character apart, so the end of one block and the start
// of the next are two places, as they are on screen.
interface SelectionPart {
	node: Text | Element;
	start: number;
	length: number;
}

interface SelectionText {
	text: string;
	parts: SelectionPart[];
}

// Offsets into the flattened text.
interface SelectionLine {
	y: number;
	start: number;
	end: number;
}

function isPaintedText(node: Text, layout: Layout | null): boolean {
	if (_(node).data.length === 0) {
		return false;
	}
	if (layout === null) {
		return true;
	}
	for (const fragment of layout.lineFragments(node)) {
		if (fragment.endOffset > fragment.startOffset) {
			return true;
		}
	}
	// Math lays its text out as cells rather than line fragments.
	return layout.getRects(node).length > 0;
}

function isLineBreakElement(node: Node): node is Element {
	return nodeTypeOf(node) === ELEMENT_NODE &&
		localNameOf((node as Element)) === "br";
}

// The nearest ancestor that is not laid out inline, which is the block
// whose lines the node's text falls on. An inline-block, an inline
// flex or grid, or inline math sits on its parent's line.
function getBlockOf(node: Node): Element | null {
	for (
		let ancestor = node.parentElement as Element | null;
		ancestor !== null;
		ancestor = ancestor.parentElement as Element | null
	) {
		const display = getComputedValue(ancestor, "display");
		if (!display.startsWith("inline") && display !== "contents") {
			return ancestor;
		}
	}
	return null;
}

// The isSelectable filter checks each text node's parent rather than
// pruning the subtree, because user-select: none does not inherit. A
// `text` descendant inside a `none` ancestor is isSelectable again.
function getSelectionTextNodes(
	document: Document,
	attached: AttachedDocument | undefined,
): Array<Text | Element> {
	const layout = attached === undefined ? null : _(attached).extra.layout;
	const nodes: Array<Text | Element> = [];
	// What renders inside a node: an author shadow root's content in place
	// of the host's children, and a slot's assigned nodes in place of its
	// fallback. A UA shadow tree is a control's own, not document text.
	const renderedChildren = (node: Node): Node[] => {
		const shadow = nodeTypeOf(node) === ELEMENT_NODE
			? _((node as Element)).shadowRoot
			: null;
		const source = shadow !== null && !_(shadow).extra.uaShadowTree
			? shadow
			: node;
		if (
			source instanceof HTMLSlotElement &&
			_(source).extra.assignedNodes.length > 0
		) {
			return [..._(source).extra.assignedNodes] as Node[];
		}
		const children: Node[] = [];
		for (let childSlots = _(source).firstChild;
			childSlots !== null;
			childSlots = childSlots.next) {
			const child = objectOf(childSlots);
			children.push(child);
		}
		return children;
	};
	const collect = (node: Node): void => {
		for (const child of renderedChildren(node)) {
			if (nodeTypeOf(child) === TEXT_NODE) {
				if (
					isPaintedText(child as Text, layout) &&
					(attached === undefined ||
						_(attached).extra.cascade.isSelectable(node))
				) {
					nodes.push(child as Text);
				}
			} else if (isLineBreakElement(child)) {
				if (
					(layout === null || layout.getRects(child).length > 0) &&
					(attached === undefined ||
						_(attached).extra.cascade.isSelectable(node))
				) {
					nodes.push(child);
				}
			} else if (nodeTypeOf(child) === ELEMENT_NODE) {
				const name = localNameOf((child as Element));
				if (name !== "script" && name !== "style" && name !== "template") {
					collect(child);
				}
			}
		}
	};
	const root = document.body ?? document.documentElement;
	if (root !== null) {
		collect(root as unknown as Node);
	}
	return nodes;
}

function flattenSelectionText(nodes: Array<Text | Element>): SelectionText {
	let text = "";
	const parts: SelectionPart[] = [];
	let previous: Text | Element | null = null;
	for (const node of nodes) {
		if (
			previous !== null &&
			!isLineBreakElement(previous) &&
			getBlockOf(previous) !== getBlockOf(node)
		) {
			text += "\n";
		}
		const piece = isLineBreakElement(node) ? "\n" : _((node as Text)).data;
		parts.push({node, start: text.length, length: piece.length});
		text += piece;
		previous = node;
	}
	return {text, parts};
}

// Null for a point in unpainted content. An element boundary point sits
// before the child at its offset, so it maps to the first painted text
// at or after that child, or past the last child, to the end of the
// element's text.
function getSelectionIndex(
	run: SelectionText,
	node: Node,
	offset: number,
): number | null {
	if (nodeTypeOf(node) === TEXT_NODE) {
		for (const part of run.parts) {
			if (part.node === node) {
				return part.start + Math.min(offset, part.length);
			}
		}
		return null;
	}
	let child = objectOf(_(node).firstChild);
	for (let i = 0; child !== null && i < offset; i++) {
		child = objectOf(_(child).next);
	}
	if (child !== null) {
		for (const part of run.parts) {
			if (isInclusiveAncestor(child, part.node)) {
				return part.start;
			}
		}
	}
	let last: number | null = null;
	for (const part of run.parts) {
		if (isInclusiveAncestor(node, part.node)) {
			last = part.start + part.length;
		}
	}
	return last;
}

// An offset on the seam between two nodes maps to the earlier node's
// end, which is the same position as the later node's start.
// An index where one text node ends and the next begins is a point in
// either. The end of the earlier node is the default; a line start wants
// the later one.
function getSelectionPoint(
	run: SelectionText,
	index: number,
	atStart = false,
): [Node, number] | null {
	const at = Math.max(0, Math.min(index, run.text.length));
	const candidates = run.parts.filter(
		(part) => part.start <= at && at <= part.start + part.length,
	);
	// The place after a <br> is the start of what follows it, when
	// anything does.
	const kept = candidates.filter(
		(part) =>
			candidates.length === 1 ||
			!isLineBreakElement(part.node) ||
			at === part.start,
	);
	let part: SelectionPart | null = kept.length > 0
		? kept[atStart ? kept.length - 1 : 0]
		: null;
	for (let i = run.parts.length - 1; part === null && i >= 0; i--) {
		if (run.parts[i].start <= at) {
			part = run.parts[i];
		}
	}
	if (part === null) {
		return null;
	}
	if (isLineBreakElement(part.node)) {
		const parent = objectOf(_(part.node).parent);
		if (parent === null) {
			return null;
		}
		const index = Array.prototype.indexOf.call(parent.childNodes, part.node);
		return [parent, at === part.start ? index : index + 1];
	}
	return [part.node, Math.min(at - part.start, part.length)];
}

// Two fragments on the same row are the same line no matter how many
// nodes they came from, so lines are keyed by row.
function getSelectionLines(
	run: SelectionText,
	layout: Layout,
): SelectionLine[] {
	const rows = new Map<number, SelectionLine>();
	const add = (y: number, start: number, end: number): void => {
		const row = rows.get(y);
		if (row === undefined) {
			rows.set(y, {y, start, end});
		} else {
			row.start = Math.min(row.start, start);
			row.end = Math.max(row.end, end);
		}
	};
	for (const part of run.parts) {
		if (isLineBreakElement(part.node)) {
			const rect = layout.getRects(part.node)[0];
			// The line ends before the break, where its caret rests.
			if (rect !== undefined) {
				add(Math.round(rect.y), part.start, part.start);
			}
			continue;
		}
		for (const fragment of layout.lineFragments(part.node)) {
			if (fragment.endOffset <= fragment.startOffset) {
				continue;
			}
			add(
				Math.round(fragment.rect.y),
				part.start + fragment.startOffset,
				part.start + fragment.endOffset,
			);
		}
	}
	return [...rows.values()].sort((a, b) => a.y - b.y);
}

// A caret exactly at a soft wrap belongs to the next line's start. Both
// lines claim the offset and the later one wins, the same rule the
// textarea's vertical motion uses.
function getSelectionLine(lines: SelectionLine[], index: number): number {
	for (let i = 0; i < lines.length; i++) {
		if (index <= lines[i].end) {
			const next = lines[i + 1];
			if (next !== undefined && next.start <= index) {
				continue;
			}
			return i;
		}
	}
	return lines.length - 1;
}

function getCaretColumn(layout: Layout, point: [Node, number]): number | null {
	const rect = layout.getCaretRect(point[0], point[1]);
	return rect === null ? null : rect.x;
}

// Moving up from the first line or down from the last line goes to that
// line's end, as a browser's arrow key does. The column is a screen
// column and the target is a screen row, so the landing offset comes
// from the layout's hit test, the same result a click there would give.
function selectionLineMove(
	document: Document,
	run: SelectionText,
	layout: Layout,
	from: [Node, number],
	index: number,
	forward: boolean,
): [Node, number] | null {
	const lines = getSelectionLines(run, layout);
	if (lines.length === 0) {
		return null;
	}
	const at = getSelectionLineOf(lines, layout, from, index);
	const target = at + (forward ? 1 : -1);
	if (target < 0) {
		return getSelectionPoint(run, lines[0].start, true);
	}
	if (target >= lines.length) {
		return getSelectionPoint(run, lines[lines.length - 1].end);
	}
	const column = getCaretColumn(layout, from);
	// Within the target line's own block. Scrolled out of its box, the
	// line shares its rows with whatever covers them there, and a search of
	// the whole document landed in that instead.
	const lineStart = getSelectionPoint(run, lines[target].start, true);
	const root =
		(lineStart === null ? null : getBlockOf(lineStart[0])) ??
		document.body ??
		document.documentElement;
	const found = column === null || root === null
		? null
		: layout.caretPositionFromPoint(
			column,
			lines[target].y,
			root as unknown as globalThis.Node,
			true,
		);
	const landed = found === null
		? null
		: getSelectionIndex(run, found.node as unknown as Node, found.offset);
	if (
		found === null ||
		landed === null ||
		landed < lines[target].start ||
		landed > lines[target].end
	) {
		return getSelectionPoint(run, lines[target].start, true);
	}
	return [found.node as unknown as Node, found.offset];
}

/** What a double or triple click selects: a word, or a paragraph. */
export type SelectionUnit = "word" | "paragraph";

const wordSegmenter = new Intl.Segmenter(undefined, {granularity: "word"});

/**
 * The span of `text` a multi-click selects around `index`: the word or the
 * run of spaces there, by the language's word rules, or the paragraph,
 * the text between line breaks.
 */
export function getUnitBounds(
	text: string,
	index: number,
	unit: SelectionUnit,
	isBreak: (at: number) => boolean = () => true,
): [number, number] {
	if (unit === "paragraph") {
		let start = Math.min(index, text.length);
		while (start > 0 && !(text[start - 1] === "\n" && isBreak(start - 1))) {
			start--;
		}
		let end = Math.min(index, text.length);
		while (end < text.length && !(text[end] === "\n" && isBreak(end))) {
			end++;
		}
		return [start, end];
	}
	// Past the end of a line, the pointer is on the line's last word.
	const endsLine = (i: number): boolean => text[i] === "\n" && isBreak(i);
	let at = Math.min(index, text.length);
	if (at > 0 && (at === text.length || endsLine(at)) && !endsLine(at - 1)) {
		at--;
	}
	if (at >= text.length || endsLine(at)) {
		return [at, at];
	}
	for (const {segment, index: start} of wordSegmenter.segment(text)) {
		if (start <= at && at < start + segment.length) {
			return [start, start + segment.length];
		}
	}
	return [at, at];
}

/**
 * The document selection a multi-click makes: the unit around the press,
 * or, as a drag goes on, from the unit around the press to the unit around
 * the pointer, a whole unit at a time. Painted text only, so text a
 * user-select: none rule keeps out is kept out here too.
 */
export function selectUnits(
	document: globalThis.Document,
	anchor: {node: globalThis.Node; offset: number},
	focus: {node: globalThis.Node; offset: number},
	unit: SelectionUnit,
): void {
	const attached = getAttachedDocument(document as unknown as Document);
	_maybe(attached)?.extra.layout.performLayout();
	const run = flattenSelectionText(
		getSelectionTextNodes(document as unknown as Document, attached),
	);
	const from = getSelectionIndex(run, anchor.node as Node, anchor.offset);
	const to = getSelectionIndex(run, focus.node as Node, focus.offset);
	if (from === null || to === null) {
		return;
	}
	// A newline ends a paragraph where it is rendered as one: between
	// blocks, at a <br>, or in text whose white-space keeps it. A newline in
	// the source of a wrapped paragraph collapses to a space.
	const isBreak = (at: number): boolean => {
		const part = run.parts.find(
			(each) => each.start <= at && at < each.start + each.length,
		);
		if (part === undefined || isLineBreakElement(part.node)) {
			return true;
		}
		const parent = flatParentElement(part.node);
		const whiteSpace = parent === null ? "" : getWhiteSpace(parent as Element);
		return /^(pre|pre-wrap|pre-line|break-spaces)$/.test(whiteSpace);
	};
	const [anchorStart, anchorEnd] = getUnitBounds(run.text, from, unit, isBreak);
	const [focusStart, focusEnd] = getUnitBounds(run.text, to, unit, isBreak);
	const [base, extent] = to >= from
		? [anchorStart, Math.max(focusEnd, anchorEnd)]
		: [anchorEnd, Math.min(focusStart, anchorStart)];
	const basePoint = getSelectionPoint(run, base, true);
	const extentPoint = getSelectionPoint(run, extent, extent < base);
	if (basePoint === null || extentPoint === null) {
		return;
	}
	(document as unknown as Document)
		.getSelection()
		?.setBaseAndExtent(
			basePoint[0],
			basePoint[1],
			extentPoint[0],
			extentPoint[1],
		);
}

function getModifiedPoint(
	selection: Selection,
	from: [Node, number],
	forward: boolean,
	granularity: string,
): [Node, number] | null {
	const document = _(selection).document;
	const attached = getAttachedDocument(document);
	const layout = attached === undefined ? null : _(attached).extra.layout;
	if (layout === null) {
		if (granularity === "line" || granularity === "lineboundary") {
			return null;
		}
	} else {
		// Lines are read from the layout in the same turn, so whatever the page
		// just mutated has to be laid out first.
		layout.performLayout();
	}
	// A caret in an editing host stays in it, as it does in a browser. Moving
	// between lines, it stops only on text it can edit, so a line that is
	// all contenteditable=false island is no stop. Along a line, the island
	// stays in the run, so stepping over it is one step.
	const host = getEditingHost(from[0] as unknown as globalThis.Node);
	let nodes = getSelectionTextNodes(document, attached);
	if (host !== null) {
		nodes = nodes.filter((node) =>
			granularity === "line"
				? getEditingHost(node as unknown as globalThis.Node) === host
				: host.contains(node as unknown as globalThis.Node),
		);
	}
	const run = flattenSelectionText(nodes);
	if (run.parts.length === 0) {
		return null;
	}
	const index = getSelectionIndex(run, from[0], from[1]);
	if (index === null) {
		return null;
	}
	if (granularity === "character") {
		return getSelectionPoint(
			run,
			forward
				? getNextGraphemeBoundary(run.text, index)
				: getPreviousGraphemeBoundary(run.text, index),
		);
	}
	if (granularity === "word") {
		return getSelectionPoint(
			run,
			forward ? getWordEnd(run.text, index) : getWordStart(run.text, index),
		);
	}
	if (granularity === "documentboundary") {
		return getSelectionPoint(run, forward ? run.text.length : 0);
	}
	if (layout === null) {
		return null;
	}
	if (granularity === "lineboundary") {
		const lines = getSelectionLines(run, layout);
		if (lines.length === 0) {
			return null;
		}
		const line = lines[getSelectionLineOf(lines, layout, from, index)];
		return forward
			? getSelectionPoint(run, line.end)
			: getSelectionPoint(run, line.start, true);
	}
	if (granularity === "line") {
		return selectionLineMove(document, run, layout, from, index, forward);
	}
	return null;
}

// Two blocks' text nodes meet in the flattened string, so an index on
// that seam names the end of one line and the start of the next. The
// caret's own node settles which, and within one node a wrap point
// belongs to the row that begins there.
function getSelectionLineOf(
	lines: SelectionLine[],
	layout: Layout,
	from: [Node, number],
	index: number,
): number {
	const [node, offset] = from;
	let y: number | null = null;
	if (nodeTypeOf(node) === TEXT_NODE) {
		for (const fragment of layout.lineFragments(node as Text)) {
			if (fragment.startOffset <= offset && offset < fragment.endOffset) {
				y = Math.round(fragment.rect.y);
				break;
			}
			if (offset === fragment.endOffset) {
				y = Math.round(fragment.rect.y);
			}
		}
	} else {
		const child = node.childNodes[offset] as unknown as Node | undefined;
		if (child !== undefined && isLineBreakElement(child)) {
			const rect = layout.getRects(child)[0];
			y = rect === undefined ? null : Math.round(rect.y);
		}
	}
	if (y !== null) {
		const at = lines.findIndex((line) => line.y === y);
		if (at !== -1) {
			return at;
		}
	}
	return getSelectionLine(lines, index);
}

function isInDocument(selection: Selection, node: Node): boolean {
	return getShadowIncludingRoot(node) === _(selection).document;
}

// The selection has a range while its range is in the document,
// including a shadow tree of the document. A range that has left the
// document is not returned.
function getDocumentRange(selection: Selection): Range | null {
	const range = _(selection).range;
	if (range === null) {
		return null;
	}
	return isInDocument(selection, _(range).startNode) ? range : null;
}

function getAnchorPoint(selection: Selection): [Node, number] | null {
	const selectionSlots = _(selection);
	const range = selectionSlots.range;
	if (range === null) {
		return null;
	}
	return selectionSlots.direction === "forwards"
		? [_(range).startNode, _(range).startOffset]
		: [_(range).endNode, _(range).endOffset];
}

function getFocusPoint(selection: Selection): [Node, number] | null {
	const selectionSlots = _(selection);
	const range = selectionSlots.range;
	if (range === null) {
		return null;
	}
	return selectionSlots.direction === "forwards"
		? [_(range).endNode, _(range).endOffset]
		: [_(range).startNode, _(range).startOffset];
}

// The selection's range, moved to the points. A script that took the
// range through getRangeAt keeps it, live, and the selection makes a
// new one. Nothing else can reach the old one, so the spec's "new
// range" is served by moving it.
function createRangeBetween(
	selection: Selection,
	start: [Node, number],
	end: [Node, number],
): Range {
	// Both points are checked before anything moves, because the range is
	// reused: a bad offset must leave the selection as it was rather than
	// half-moved.
	checkBoundaryPoint(start[0], start[1]);
	checkBoundaryPoint(end[0], end[1]);
	let range = _(selection).range;
	if (range === null || !_(range).selectionOwned) {
		range = new Range();
		_(range).selectionOwned = true;
	}
	// Set as the Range API sets them, so an end in another tree collapses
	// the range. The selection's own points are set after, not by the
	// boundary hook.
	_(range).rangeSelection = null;
	setRangeBoundary(range, start[0], start[1], true);
	setRangeBoundary(range, end[0], end[1], false);
	return range;
}

function associateSelectionRange(
	selection: Selection,
	range: Range,
	anchor: [Node, number],
	focus: [Node, number],
	direction: "forwards" | "backwards" | "directionless",
): void {
	const selectionSlots = _(selection);
	const previous = selectionSlots.range;
	if (previous !== null && previous !== range) {
		_(previous).rangeSelection = null;
		if (_(previous).selectionOwned) {
			releaseLiveRange(previous);
		}
	}
	selectionSlots.range = range;
	_(range).rangeSelection = selection;
	const anchorFirst =
		compareComposedPoints(anchor[0], anchor[1], focus[0], focus[1]) !== AFTER;
	const start = anchorFirst ? anchor : focus;
	const end = anchorFirst ? focus : anchor;
	movePoint(selectionSlots.start, start[0], start[1]);
	movePoint(selectionSlots.end, end[0], end[1]);
	selectionSlots.direction = direction;
	scheduleSelectionChange(selectionSlots.document);
}

// The composed point that the change moved follows it. A range that
// leaves the document takes the selection with it.
function selectionChanged(
	selection: Selection,
	which: "start" | "end" | "both",
): void {
	const selectionSlots = _(selection);
	const range = selectionSlots.range;
	if (range === null) {
		return;
	}
	if (!isInDocument(selection, _(range).startNode)) {
		selection.removeAllRanges();
		return;
	}
	const start = selectionSlots.start;
	const end = selectionSlots.end;
	if (which !== "end") {
		movePoint(start, _(range).startNode, _(range).startOffset);
	}
	if (which !== "start") {
		movePoint(end, _(range).endNode, _(range).endOffset);
	}
	// A point moved past the other takes it along.
	const endSlots = _(end);
	const startSlots = _(start);
	if (which === "start" && getComposedOrder(start, end) === AFTER) {
		movePoint(end, startSlots.startNode, startSlots.startOffset);
	} else if (which === "end" && getComposedOrder(end, start) === BEFORE) {
		movePoint(start, endSlots.startNode, endSlots.startOffset);
	}
	scheduleSelectionChange(selectionSlots.document);
}

function getComposedOrder(point: Range, other: Range): number {
	const otherSlots = _(other);
	const pointSlots = _(point);
	return compareComposedPoints(
		pointSlots.startNode,
		pointSlots.startOffset,
		otherSlots.startNode,
		otherSlots.startOffset,
	);
}

ceReactions(Selection.prototype, ["deleteFromDocument"]);

Object.defineProperty(Selection.prototype, Symbol.toStringTag, {
	value: "Selection",
	configurable: true,
});

/**
 * The document's fonts, which a terminal has none of: an empty set that
 * is already loaded, so code that waits on `fonts.ready` goes on.
 */
class FontFaceSet extends EventTarget {
	declare readonly [Symbol.toStringTag]: string;
	declare onloading: globalThis.FontFaceSet["onloading"];
	declare onloadingdone: globalThis.FontFaceSet["onloadingdone"];
	declare onloadingerror: globalThis.FontFaceSet["onloadingerror"];

	get ready(): Promise<globalThis.FontFaceSet> {
		return Promise.resolve(this as unknown as globalThis.FontFaceSet);
	}

	get status(): globalThis.FontFaceSetLoadStatus {
		return "loaded";
	}

	get size(): number {
		return 0;
	}

	check(_font: string, _text?: string): boolean {
		return true;
	}

	load(_font: string, _text?: string): Promise<globalThis.FontFace[]> {
		return Promise.resolve([]);
	}

	add(_font: globalThis.FontFace): this {
		throw new TypeError("This document loads no fonts");
	}

	clear(): void {}

	delete(_font: globalThis.FontFace): boolean {
		return false;
	}

	has(_font: globalThis.FontFace): boolean {
		return false;
	}

	forEach(
		_callback: (
			value: globalThis.FontFace,
			key: globalThis.FontFace,
			parent: globalThis.FontFaceSet,
		) => void,
		_thisArg?: unknown,
	): void {}

	entries(): SetIterator<[globalThis.FontFace, globalThis.FontFace]> {
		return new Set<globalThis.FontFace>().entries();
	}

	keys(): SetIterator<globalThis.FontFace> {
		return new Set<globalThis.FontFace>().keys();
	}

	values(): SetIterator<globalThis.FontFace> {
		return new Set<globalThis.FontFace>().values();
	}

	[Symbol.iterator](): SetIterator<globalThis.FontFace> {
		return this.values();
	}
}

Object.defineProperty(FontFaceSet.prototype, Symbol.toStringTag, {
	value: "FontFaceSet",
	configurable: true,
});
for (const name of ["onloading", "onloadingdone", "onloadingerror"]) {
	installEventHandler(FontFaceSet.prototype, name);
}

type HighlightType = "grammar-error" | "highlight" | "spelling-error";

const HIGHLIGHT_TYPES = ["highlight", "spelling-error", "grammar-error"];

interface HighlightSlots {
	highlightRanges: Set<AbstractRange>;
	highlightPriority: number;
	highlightType: HighlightType;
	// The registries a highlight is registered in. A highlight belongs to no
	// document of its own, so this is the only way from a mutated highlight
	// to the screens that have to repaint.
	highlightRegistries: Set<HighlightRegistry>;
}

interface Highlight {
	readonly [internals]: HighlightSlots;
}

/** A set of ranges to paint under one `::highlight()` name. */
class Highlight {
	declare readonly [Symbol.toStringTag]: string;

	constructor(...initialRanges: AbstractRange[]) {
		seal(this, new.target, Highlight);
		const slots = _(this);
		slots.highlightRanges = new Set<AbstractRange>();
		slots.highlightPriority = 0;
		slots.highlightType = "highlight";
		slots.highlightRegistries = new Set<HighlightRegistry>();
		for (const range of initialRanges) {
			this.add(range);
		}
	}

	get priority(): number {
		return _(this).highlightPriority;
	}

	set priority(value: number) {
		_(this).highlightPriority = toLong(value);
		highlightChanged(this);
	}

	get type(): HighlightType {
		return _(this).highlightType;
	}

	set type(value: HighlightType) {
		if (!HIGHLIGHT_TYPES.includes(String(value))) {
			return;
		}
		_(this).highlightType = String(value) as HighlightType;
		highlightChanged(this);
	}

	get size(): number {
		return _(this).highlightRanges.size;
	}

	add(range: AbstractRange): Highlight {
		if (!(range instanceof AbstractRange)) {
			throw new TypeError("That is not a range");
		}
		_(this).highlightRanges.add(range);
		joinHighlight(range, this);
		highlightChanged(this);
		return this;
	}

	delete(range: AbstractRange): boolean {
		if (arguments.length < 1) {
			throw new TypeError("delete needs a range");
		}
		const deleted = _(this).highlightRanges.delete(range);
		if (deleted) {
			leaveHighlight(range, this);
			highlightChanged(this);
		}
		return deleted;
	}

	has(range: AbstractRange): boolean {
		if (arguments.length < 1) {
			throw new TypeError("has needs a range");
		}
		return _(this).highlightRanges.has(range);
	}

	clear(): void {
		const slots = _(this);
		if (slots.highlightRanges.size === 0) {
			return;
		}
		for (const range of slots.highlightRanges) {
			leaveHighlight(range, this);
		}
		slots.highlightRanges.clear();
		highlightChanged(this);
	}

	forEach(
		callback: (
			value: AbstractRange,
			key: AbstractRange,
			parent: Highlight,
		) => void,
		thisArg?: any,
	): void {
		if (typeof callback !== "function") {
			throw new TypeError("That is not a callback");
		}
		for (const range of [..._(this).highlightRanges]) {
			callback.call(thisArg, range, range, this);
		}
	}

	keys(): SetIterator<globalThis.AbstractRange> {
		return _(this).highlightRanges.values();
	}

	values(): SetIterator<globalThis.AbstractRange> {
		return _(this).highlightRanges.values();
	}

	entries(): SetIterator<[globalThis.AbstractRange, globalThis.AbstractRange]> {
		return _(this).highlightRanges.entries();
	}

	[Symbol.iterator](): SetIterator<globalThis.AbstractRange> {
		return _(this).highlightRanges.values();
	}
}

declareSealedRoot(Highlight);

Object.defineProperty(Highlight.prototype, Symbol.toStringTag, {
	value: "Highlight",
	configurable: true,
});

let registryUnderConstruction: Document | null = null;

interface HighlightRegistrySlots {
	highlightsByName: Map<string, Highlight>;
	registryDocument: Document;
}

interface HighlightRegistry {
	readonly [internals]: HighlightRegistrySlots;
}

/**
 * A document's registered highlights, as `CSS.highlights`. Insertion
 * ordered: two highlights of equal priority paint in the order their
 * names were registered, so re-registering a name moves it last.
 */
class HighlightRegistry {
	constructor() {
		seal(this, new.target, HighlightRegistry);
		if (!internalConstruction) {
			throw new TypeError("Illegal constructor");
		}
		const slots = _(this);
		slots.highlightsByName = new Map<string, Highlight>();
		slots.registryDocument = registryUnderConstruction as Document;
	}

	get size(): number {
		return _(this).highlightsByName.size;
	}

	set(name: string, highlight: Highlight): HighlightRegistry {
		if (arguments.length < 2) {
			throw new TypeError("set needs a name and a highlight");
		}
		if (!(highlight instanceof Highlight)) {
			throw new TypeError("That is not a highlight");
		}
		const key = String(name);
		const slots = _(this);
		const previous = slots.highlightsByName.get(key);
		if (previous !== undefined) {
			slots.highlightsByName.delete(key);
			dropRegistration(this, previous);
		}
		slots.highlightsByName.set(key, highlight);
		_(highlight).highlightRegistries.add(this);
		invalidateHighlights(slots.registryDocument);
		return this;
	}

	get(name: string): Highlight | undefined {
		if (arguments.length < 1) {
			throw new TypeError("get needs a name");
		}
		return _(this).highlightsByName.get(String(name));
	}

	has(name: string): boolean {
		if (arguments.length < 1) {
			throw new TypeError("has needs a name");
		}
		return _(this).highlightsByName.has(String(name));
	}

	delete(name: string): boolean {
		if (arguments.length < 1) {
			throw new TypeError("delete needs a name");
		}
		const key = String(name);
		const slots = _(this);
		const highlight = slots.highlightsByName.get(key);
		if (highlight === undefined) {
			return false;
		}
		slots.highlightsByName.delete(key);
		dropRegistration(this, highlight);
		invalidateHighlights(slots.registryDocument);
		return true;
	}

	clear(): void {
		const slots = _(this);
		if (slots.highlightsByName.size === 0) {
			return;
		}
		const registered = [...slots.highlightsByName.values()];
		slots.highlightsByName.clear();
		for (const highlight of registered) {
			dropRegistration(this, highlight);
		}
		invalidateHighlights(slots.registryDocument);
	}

	forEach(
		callback: (
			value: Highlight,
			key: string,
			parent: HighlightRegistry,
		) => void,
		thisArg?: any,
	): void {
		if (typeof callback !== "function") {
			throw new TypeError("That is not a callback");
		}
		for (const [name, highlight] of [..._(this).highlightsByName]) {
			callback.call(thisArg, highlight, name, this);
		}
	}

	keys(): MapIterator<string> {
		return _(this).highlightsByName.keys();
	}

	values(): MapIterator<globalThis.Highlight> {
		return _(this).highlightsByName.values();
	}

	entries(): MapIterator<[string, globalThis.Highlight]> {
		return _(this).highlightsByName.entries();
	}

	[Symbol.iterator](): MapIterator<[string, globalThis.Highlight]> {
		return _(this).highlightsByName.entries();
	}
}

declareSealedRoot(HighlightRegistry);

Object.defineProperty(HighlightRegistry.prototype, Symbol.toStringTag, {
	value: "HighlightRegistry",
	configurable: true,
});

/** The document's registry, built on the first `CSS.highlights` read. */
export function getHighlightRegistry(
	document: globalThis.Document,
): HighlightRegistry {
	const owner = document as Document;
	const ownerSlots = _(owner);
	let registry = ownerSlots.extra.highlights;
	if (registry === null) {
		registryUnderConstruction = owner;
		try {
			registry = constructInternal(() => new HighlightRegistry());
		} finally {
			registryUnderConstruction = null;
		}
		ownerSlots.extra.highlights = registry;
	}
	return registry;
}

/** A torn-down document paints nothing, and holds no highlight. */
export function clearHighlights(document: globalThis.Document): void {
	_((document as Document)).extra.highlights?.clear();
}

// A highlight that is no longer registered under any name in this
// registry stops repainting through it.
function dropRegistration(
	registry: HighlightRegistry,
	highlight: Highlight,
): void {
	for (const registered of _(registry).highlightsByName.values()) {
		if (registered === highlight) {
			return;
		}
	}
	_(highlight).highlightRegistries.delete(registry);
}

// Which highlights a range is in, so that moving its boundary points
// repaints them. Only ranges that join one are ever in here, and the
// count keeps the lookup off the path of every other range.
const highlightsByRange = new WeakMap<AbstractRange, Set<Highlight>>();
let highlightedRangesEver = 0;

function joinHighlight(range: AbstractRange, highlight: Highlight): void {
	let highlights = highlightsByRange.get(range);
	if (highlights === undefined) {
		highlights = new Set<Highlight>();
		highlightsByRange.set(range, highlights);
	}
	highlights.add(highlight);
	highlightedRangesEver++;
}

function leaveHighlight(range: AbstractRange, highlight: Highlight): void {
	highlightsByRange.get(range)?.delete(highlight);
}

/** The highlights a range moved under, for the mutation steps. */
function rangeHighlightsChanged(range: Range): void {
	if (highlightedRangesEver === 0) {
		return;
	}
	const highlights = highlightsByRange.get(range);
	if (highlights === undefined) {
		return;
	}
	for (const highlight of highlights) {
		highlightChanged(highlight);
	}
}

// A highlight belongs to whatever registries hold it, and each of those
// belongs to a document with a screen to repaint.
function highlightChanged(highlight: Highlight): void {
	for (const registry of _(highlight).highlightRegistries) {
		invalidateHighlights(_(registry).registryDocument);
	}
}

// Neither registering a highlight nor moving one is a DOM mutation, and
// no record names the rows it covers, so the repaint is asked for here.
function invalidateHighlights(document: Document): void {
	const attached = getAttachedDocument(document);
	if (attached === undefined) {
		return;
	}
	_(attached).extra.framebuffer.invalidate();
	void _(attached).extra.render();
}

/** A registered highlight and what it covers, for the painter. */
interface PaintedHighlight {
	name: string;
	ranges: globalThis.AbstractRange[];
}

/**
 * Every registered highlight that covers something, lowest priority
 * first, which is the order the painter folds their styles in.
 */
export function getPaintedHighlights(
	document: globalThis.Document,
): PaintedHighlight[] {
	const registry = _((document as Document)).extra.highlights;
	if (registry === null || _(registry).highlightsByName.size === 0) {
		return [];
	}
	const painted: Array<PaintedHighlight & {priority: number}> = [];
	for (const [name, highlight] of _(registry).highlightsByName) {
		const ranges = [..._(highlight).highlightRanges].filter(
			(range) => !range.collapsed,
		);
		if (ranges.length > 0) {
			painted.push({name, ranges, priority: _(highlight).highlightPriority});
		}
	}
	return painted.sort((a, b) => a.priority - b.priority);
}

/** Whether anything at all highlights this document. */
export function hasPaintedHighlights(document: globalThis.Document): boolean {
	const registry = _((document as Document)).extra.highlights;
	if (registry === null) {
		return false;
	}
	for (const highlight of _(registry).highlightsByName.values()) {
		for (const range of _(highlight).highlightRanges) {
			if (!range.collapsed) {
				return true;
			}
		}
	}
	return false;
}

/**
 * The text nodes one of a highlight's ranges covers, with the offsets it
 * covers of each.
 */
export function getHighlightedTextNodes(
	range: globalThis.AbstractRange,
): Array<{textNode: globalThis.Text; from: number; to: number}> {
	const start = _((range as AbstractRange)).startNode;
	const end = _((range as AbstractRange)).endNode;
	if (getRoot(start) !== getRoot(end)) {
		return [];
	}
	let container = start;
	while (!isInclusiveAncestor(container, end)) {
		container = objectOf(_(container).parent) as Node;
	}
	const covered: Array<{textNode: Text; from: number; to: number}> = [];
	for (
		let node: Node | null = container;
		node !== null;
		node = nextInTree(node, container)
	) {
		if (!(node instanceof Text)) {
			continue;
		}
		const offsets = getHighlightedOffsets(range, node);
		if (offsets !== null) {
			covered.push({textNode: node, from: offsets.from, to: offsets.to});
		}
	}
	return covered;
}

/**
 * The offsets of a text node one of a highlight's ranges covers, or null
 * when it covers none of it. A static range whose boundary points no
 * longer describe the tree describes nothing.
 */
function getHighlightedOffsets(
	range: globalThis.AbstractRange,
	textNode: globalThis.Text,
): {from: number; to: number} | null {
	const start = _((range as AbstractRange)).startNode;
	const startOffset = _((range as AbstractRange)).startOffset;
	const end = _((range as AbstractRange)).endNode;
	const endOffset = _((range as AbstractRange)).endOffset;
	const node = textNode as Text;
	if (
		startOffset > getNodeLength(start) ||
		endOffset > getNodeLength(end) ||
		getRoot(start) !== getRoot(node) ||
		getRoot(end) !== getRoot(node)
	) {
		return null;
	}
	const from = start === node ? startOffset : 0;
	const to = end === node ? endOffset : getNodeLength(node);
	if (
		to <= from ||
		comparePoints(node, from, end, endOffset) !== BEFORE ||
		comparePoints(node, to, start, startOffset) !== AFTER
	) {
		return null;
	}
	return {from, to};
}

const FILTER_ACCEPT = 1;
const FILTER_REJECT = 2;
const FILTER_SKIP = 3;

type NodeFilterInput =
	((node: Node) => number) |
	{acceptNode(node: Node): number} |
	null |
	undefined;

export const NodeFilter = {
	FILTER_ACCEPT,
	FILTER_REJECT,
	FILTER_SKIP,
	SHOW_ALL: 0xffffffff,
	SHOW_ELEMENT: 0x1,
	SHOW_ATTRIBUTE: 0x2,
	SHOW_TEXT: 0x4,
	SHOW_CDATA_SECTION: 0x8,
	SHOW_ENTITY_REFERENCE: 0x10,
	SHOW_ENTITY: 0x20,
	SHOW_PROCESSING_INSTRUCTION: 0x40,
	SHOW_COMMENT: 0x80,
	SHOW_DOCUMENT: 0x100,
	SHOW_DOCUMENT_TYPE: 0x200,
	SHOW_DOCUMENT_FRAGMENT: 0x400,
	SHOW_NOTATION: 0x800,
};

Object.freeze(NodeFilter);

function filterNode(
	traverser: {
		whatToShow: number;
		filter: NodeFilterInput;
		active: {value: boolean};
	},
	node: Node,
): number {
	if (traverser.active.value) {
		throw domError("InvalidStateError", "The filter is already running");
	}
	if (((1 << (nodeTypeOf(node) - 1)) & traverser.whatToShow) === 0) {
		return FILTER_SKIP;
	}
	const filter = traverser.filter;
	if (filter == null) {
		return FILTER_ACCEPT;
	}
	traverser.active.value = true;
	let result: unknown;
	try {
		result = typeof filter === "function"
			? filter(node)
			: (filter as {acceptNode(node: Node): number}).acceptNode(node);
	} finally {
		traverser.active.value = false;
	}
	return toUnsignedLong(result);
}

function precedingWithin(node: Node, root: Node): Node | null {
	if (node === root) {
		return null;
	}
	const nodeSlots = _(node);
	let previous = objectOf(nodeSlots.previous);
	if (previous === null) {
		return objectOf(nodeSlots.parent);
	}
	while (_(previous).lastChild !== null) {
		previous = objectOf(_(previous).lastChild) as Node;
	}
	return previous;
}

interface NodeIteratorSlots {
	root: Node;
	reference: Node;
	pointerBefore: boolean;
	whatToShow: number;
	filter: NodeFilterInput;
	active: {value: boolean};
}

interface NodeIterator {
	readonly [internals]: NodeIteratorSlots;
}

class NodeIterator {
	constructor(root: Node, whatToShow: number, filter: NodeFilterInput) {
		seal(this, new.target, NodeIterator);
		const slots = _(this);
		slots.pointerBefore = true;
		slots.active = {value: false};
		slots.root = root;
		slots.reference = root;
		slots.whatToShow = whatToShow;
		slots.filter = filter ?? null;
	}

	get root(): Node {
		return _(this).root;
	}

	get referenceNode(): Node {
		return _(this).reference;
	}

	get pointerBeforeReferenceNode(): boolean {
		return _(this).pointerBefore;
	}

	get whatToShow(): number {
		return _(this).whatToShow;
	}

	get filter(): globalThis.NodeFilter | null {
		return _(this).filter as globalThis.NodeFilter | null;
	}

	nextNode(): Node | null {
		return traverseIterator(this, true);
	}

	previousNode(): Node | null {
		return traverseIterator(this, false);
	}

	detach(): void {
		// The spec makes this a no-op.
	}
}

declareSealedRoot(NodeIterator);

function traverseIterator(
	iterator: NodeIterator,
	forward: boolean,
): Node | null {
	const iteratorSlots = _(iterator);
	let node: Node | null = iteratorSlots.reference;
	let before = iteratorSlots.pointerBefore;
	const state = {
		whatToShow: iteratorSlots.whatToShow,
		filter: iteratorSlots.filter,
		active: iteratorSlots.active,
	};
	for (;;) {
		if (forward) {
			if (!before) {
				node = nextInTree(node as Node, iteratorSlots.root);
				if (node === null) {
					return null;
				}
			} else {
				before = false;
			}
		} else {
			if (before) {
				node = precedingWithin(node as Node, iteratorSlots.root);
				if (node === null) {
					return null;
				}
			} else {
				before = true;
			}
		}
		if (filterNode(state, node as Node) === FILTER_ACCEPT) {
			// A filter that removed the node it was filtering leaves the
			// reference where the pre-removing steps put it. A node outside the
			// root can never be the reference.
			if (isInclusiveAncestor(iteratorSlots.root, node as Node)) {
				iteratorSlots.reference = node as Node;
				iteratorSlots.pointerBefore = before;
			}
			break;
		}
	}
	return node;
}

function preRemoveFromIterator(
	iterator: NodeIterator,
	toBeRemoved: Node,
): void {
	const iteratorSlots = _(iterator);
	if (
		!isInclusiveAncestor(toBeRemoved, iteratorSlots.reference) ||
		isInclusiveAncestor(toBeRemoved, iteratorSlots.root)
	) {
		return;
	}
	if (iteratorSlots.pointerBefore) {
		let next = nextInTree(toBeRemoved, iteratorSlots.root);
		while (next !== null && isInclusiveAncestor(toBeRemoved, next)) {
			next = nextInTree(next, iteratorSlots.root);
		}
		if (next !== null) {
			iteratorSlots.reference = next;
			return;
		}
		iteratorSlots.pointerBefore = false;
	}
	const toBeRemovedSlots = _(toBeRemoved);
	const previous = objectOf(toBeRemovedSlots.previous);
	if (previous === null) {
		iteratorSlots.reference = objectOf(toBeRemovedSlots.parent) as Node;
		return;
	}
	let last: Node = previous;
	while (_(last).lastChild !== null) {
		last = objectOf(_(last).lastChild) as Node;
	}
	iteratorSlots.reference = last;
}

Object.defineProperty(NodeIterator.prototype, Symbol.toStringTag, {
	value: "NodeIterator",
	configurable: true,
});

export interface TreeWalkerSlots {
	root: Node;
	current: Node;
	whatToShow: number;
	filter: NodeFilterInput;
	active: {value: boolean};
	[kState]: Step<TreeWalker[typeof kState]>;
}

export interface TreeWalker {
	readonly [internals]: TreeWalkerSlots;
}

export class TreeWalker implements globalThis.TreeWalker {
	constructor(root: Node, whatToShow: number, filter: NodeFilterInput) {
		seal(this, new.target, TreeWalker);
		const slots = _(this);
		slots.active = {value: false};
		slots.root = root;
		slots.current = root;
		slots.whatToShow = whatToShow;
		slots.filter = filter ?? null;
	}

	get root(): globalThis.Node {
		return _(this).root as unknown as globalThis.Node;
	}

	get whatToShow(): number {
		return _(this).whatToShow;
	}

	get filter(): globalThis.NodeFilter | null {
		return _(this).filter as globalThis.NodeFilter | null;
	}

	get currentNode(): globalThis.Node {
		return _(this).current as unknown as globalThis.Node;
	}

	set currentNode(node: globalThis.Node) {
		if (!(node instanceof Node)) {
			throw new TypeError("That is not a node");
		}
		_(this).current = node as Node;
	}

	get [kState](): {
		whatToShow: number;
		filter: NodeFilterInput;
		active: {value: boolean};
	} {
		const slots = this as unknown as Slots<TreeWalker>;
		return {
			whatToShow: slots.whatToShow,
			filter: slots.filter,
			active: slots.active,
		};
	}

	parentNode(): globalThis.Node | null {
		return walkParent(this) as unknown as globalThis.Node | null;
	}

	firstChild(): globalThis.Node | null {
		return walkChildren(this, true) as unknown as globalThis.Node | null;
	}

	lastChild(): globalThis.Node | null {
		return walkChildren(this, false) as unknown as globalThis.Node | null;
	}

	previousSibling(): globalThis.Node | null {
		return walkSiblings(this, false) as unknown as globalThis.Node | null;
	}

	nextSibling(): globalThis.Node | null {
		return walkSiblings(this, true) as unknown as globalThis.Node | null;
	}

	previousNode(): globalThis.Node | null {
		return walkPrevious(this) as unknown as globalThis.Node | null;
	}

	nextNode(): globalThis.Node | null {
		return walkNext(this) as unknown as globalThis.Node | null;
	}
}

declareSealedRoot(TreeWalker);

// DOM Standard, "traverse children".
function walkChildren(walk: TreeWalker, first: boolean): Node | null {
	const walkSlots = _(walk);
	let node: Node | null = first
		? objectOf(_(walkSlots.current).firstChild)
		: objectOf(_(walkSlots.current).lastChild);
	while (node !== null) {
		const result = filterNode(walkSlots[kState], node);
		if (result === FILTER_ACCEPT) {
			walkSlots.current = node;
			return node;
		}
		if (result === FILTER_SKIP) {
			const child = first
				? objectOf(_(node).firstChild)
				: objectOf(_(node).lastChild);
			if (child !== null) {
				node = child;
				continue;
			}
		}
		for (;;) {
			const sibling = first
				? objectOf(_(node).next)
				: objectOf(_(node).previous);
			if (sibling !== null) {
				node = sibling;
				break;
			}
			const parent: Node | null = objectOf(_(node).parent);
			if (
				parent === null ||
				parent === walkSlots.root ||
				parent === walkSlots.current
			) {
				return null;
			}
			node = parent;
		}
	}
	return null;
}

// DOM Standard, "traverse siblings". A walk rooted at a node never
// visits that node's siblings. Returning one would escape the subtree
// the walk was scoped to, which is how an empty inline element once
// measured the width of the sibling after it.
function walkSiblings(walk: TreeWalker, next: boolean): Node | null {
	const walkSlots = _(walk);
	let node = walkSlots.current;
	if (node === walkSlots.root) {
		return null;
	}
	for (;;) {
		let sibling = next ? objectOf(_(node).next) : objectOf(_(node).previous);
		while (sibling !== null) {
			node = sibling;
			const result = filterNode(walkSlots[kState], node);
			if (result === FILTER_ACCEPT) {
				walkSlots.current = node;
				return node;
			}
			sibling = next
				? objectOf(_(node).firstChild)
				: objectOf(_(node).lastChild);
			if (result === FILTER_REJECT || sibling === null) {
				sibling = next ? objectOf(_(node).next) : objectOf(_(node).previous);
			}
		}
		const parent = objectOf(_(node).parent);
		if (parent === null || parent === walkSlots.root) {
			return null;
		}
		node = parent;
		if (filterNode(walkSlots[kState], node) === FILTER_ACCEPT) {
			return null;
		}
	}
}

function walkParent(walk: TreeWalker): Node | null {
	const walkSlots = _(walk);
	let node: Node | null = walkSlots.current;
	while (node !== null && node !== walkSlots.root) {
		node = objectOf(_(node).parent);
		if (
			node !== null && filterNode(walkSlots[kState], node) === FILTER_ACCEPT
		) {
			walkSlots.current = node;
			return node;
		}
	}
	return null;
}

// Down to the first child, else to the next sibling, else up until some level
// has one. The climb asks each level for its OWN next sibling, starting at the
// node itself.
function walkNext(walk: TreeWalker): Node | null {
	const walkSlots = _(walk);
	let node = walkSlots.current;
	let result = FILTER_ACCEPT;
	for (;;) {
		while (result !== FILTER_REJECT) {
			const child = objectOf(_(node).firstChild);
			if (child === null) {
				break;
			}
			node = child;
			result = filterNode(walkSlots[kState], node);
			if (result === FILTER_ACCEPT) {
				walkSlots.current = node;
				return node;
			}
		}
		let sibling: Node | null = null;
		let temporary: Node | null = node;
		while (temporary !== null) {
			if (temporary === walkSlots.root) {
				return null;
			}
			sibling = objectOf(_(temporary).next);
			if (sibling !== null) {
				break;
			}
			temporary = objectOf(_(temporary).parent);
		}
		if (sibling === null) {
			return null;
		}
		node = sibling;
		result = filterNode(walkSlots[kState], node);
		if (result === FILTER_ACCEPT) {
			walkSlots.current = node;
			return node;
		}
	}
}

function walkPrevious(walk: TreeWalker): Node | null {
	const walkSlots = _(walk);
	let node = walkSlots.current;
	while (node !== walkSlots.root) {
		let sibling = objectOf(_(node).previous);
		while (sibling !== null) {
			node = sibling;
			let result = filterNode(walkSlots[kState], node);
			for (;;) {
				if (result === FILTER_REJECT) {
					break;
				}
				const child = objectOf(_(node).lastChild);
				if (child === null) {
					break;
				}
				node = child;
				result = filterNode(walkSlots[kState], node);
			}
			if (result === FILTER_ACCEPT) {
				walkSlots.current = node;
				return node;
			}
			sibling = objectOf(_(node).previous);
		}
		const parent = objectOf(_(node).parent);
		if (parent === null) {
			return null;
		}
		node = parent;
		if (filterNode(walkSlots[kState], node) === FILTER_ACCEPT) {
			walkSlots.current = node;
			return node;
		}
	}
	return null;
}

Object.defineProperty(TreeWalker.prototype, Symbol.toStringTag, {
	value: "TreeWalker",
	configurable: true,
});

// Hover is not a mutation and no attribute records it. The engine
// writes it here as motion reports arrive, and the `:hover` resolver
// reads it. Absent means nothing is hovered, because the document has no
// motion reporting or the pointer left.
const activeElements = new WeakMap<Document, Element>();

/** Record the element a mouse button is held down on, for `:active`. */
export function setActiveElement(
	document: globalThis.Document,
	element: globalThis.Element | null,
): void {
	if (element === null) {
		activeElements.delete(document as Document);
	} else {
		activeElements.set(document as Document, element as Element);
	}
}

export function getActiveElement(
	document: globalThis.Document,
): globalThis.Element | null {
	return (activeElements.get(document as Document) ??
		null) as globalThis.Element |
		null;
}

// True for the pressed element and anything that contains it in the flat
// tree, as :hover is.
export function isActive(element: Element): boolean {
	const document = _(element).document;
	for (
		let node: Element | null = activeElements.get(document) ?? null;
		node !== null;
		node = getFlatTreeParent(node)
	) {
		if (node === element) {
			return true;
		}
	}
	return false;
}

const hoveredElements = new WeakMap<Document, Element>();

/**
 * The mouse's buttons held down, and its capture: `pending` is what
 * setPointerCapture asked for, `active` what pointer events target now.
 */
export interface PointerState {
	buttons: number;
	pending: Element | null;
	active: Element | null;
}

const pointerStates = new WeakMap<Document, PointerState>();

export function getPointerState(document: globalThis.Document): PointerState {
	let state = pointerStates.get(document as Document);
	if (state === undefined) {
		state = {buttons: 0, pending: null, active: null};
		pointerStates.set(document as Document, state);
	}
	return state;
}

// An element that leaves the document loses its capture at once. A move
// is not a removal, so moveBefore keeps it.
function releasePointerCaptureOnRemoval(document: Document, node: Node): void {
	const state = pointerStates.get(document);
	if (
		state?.pending != null &&
		isShadowIncludingInclusiveAncestor(node, state.pending)
	) {
		state.pending = null;
	}
}

// The pressed or hovered element leaving the tree hands :active and :hover
// to the parent it left, as browsers do, while the button is still down
// and the pointer still over the place it was. The parent already matched
// through it, so nothing changes style.
function movePointerStatesOffRemoval(
	document: Document,
	node: Node,
	parent: Node,
): void {
	const heir = parent instanceof ShadowRoot
		? (_(parent).extra.host as Element)
		: nodeTypeOf(parent) === ELEMENT_NODE ? (parent as Element) : null;
	for (const states of [activeElements, hoveredElements]) {
		const element = states.get(document);
		if (
			element !== undefined && isShadowIncludingInclusiveAncestor(node, element)
		) {
			if (heir === null) {
				states.delete(document);
			} else {
				states.set(document, heir);
			}
		}
	}
}

/** Record what `:hover` should match. */
export function setHoveredElement(
	document: globalThis.Document,
	element: globalThis.Element | null,
): void {
	if (element === null) {
		hoveredElements.delete(document as Document);
	} else {
		hoveredElements.set(document as Document, element as Element);
	}
}

const focusVisibleDocuments = new WeakMap<Document, boolean>();

/**
 * A focus ring depends on how focus was moved: a key shows one, a click
 * does not. The input handler sets this, and the cascade repaints when it
 * changes. Returns whether it changed.
 */
export function setDocumentFocusVisible(
	document: globalThis.Document,
	active: boolean,
): boolean {
	const node = document as Document;
	if ((focusVisibleDocuments.get(node) ?? true) === active) {
		return false;
	}
	focusVisibleDocuments.set(node, active);
	return true;
}

/** Also true for a host above the focused element. */
export function hasFocus(element: Element): boolean {
	const active = _(_(element).document).extra.activeElement;
	if (active === null) {
		return false;
	}
	if (element === active) {
		return true;
	}
	for (
		let root = getRoot(active as unknown as Node);
		isShadowRoot(root);
		root = getRoot(root)
	) {
		const host = _((root as ShadowRoot)).extra.host as unknown as Element;
		if (host === element) {
			return true;
		}
		root = host as unknown as Node;
	}
	return false;
}

export function getPartNames(element: Element): string[] {
	const value = attributeOf(element, "part");
	return value === null ? [] : splitOnASCIIWhitespace(value);
}

/** Whether `:target` matches. */
export function isTargetElement(element: Element): boolean {
	const document = _(element).document;
	if (getRoot(element as unknown as Node) !== (document as unknown as Node)) {
		return false;
	}
	const url = _(document).extra.documentURL;
	const hash = url.indexOf("#");
	if (hash === -1) {
		return false;
	}
	const fragment = url.slice(hash + 1);
	if (fragment === "") {
		return false;
	}
	let decoded = fragment;
	try {
		decoded = decodeURIComponent(fragment);
	} catch (_err) {
		// A fragment that is not valid percent-encoding is used as-is.
	}
	const id = attributeOf(element, "id");
	if (id === decoded || id === fragment) {
		return true;
	}
	// The `a` element's name attribute is the old way to write an anchor.
	return (
		namespaceOf(element) === HTML_NAMESPACE &&
		localNameOf(element) === "a" &&
		attributeOf(element, "name") === decoded
	);
}

// The element the URL's fragment names, or null (HTML's indicated part).
function getTargetElement(document: Document): Element | null {
	for (const node of descendants(document)) {
		if (nodeTypeOf(node) === ELEMENT_NODE && isTargetElement(node as Element)) {
			return node as Element;
		}
	}
	return null;
}

// The part of a URL before its fragment, which is what a same-document
// navigation keeps.
function withoutFragment(url: string): string {
	const hash = url.indexOf("#");
	return hash === -1 ? url : url.slice(0, hash);
}

// Whether going to `url` from the document's own URL moves only the
// fragment: HTML's "navigate to a fragment", the one navigation a
// terminal document can make.
function isFragmentNavigation(document: Document, url: string): boolean {
	return url.includes("#") &&
		withoutFragment(url) === withoutFragment(_(document).extra.documentURL);
}

function navigateToFragment(document: Document, url: string): void {
	const documentSlots = _(document);
	const oldURL = documentSlots.extra.documentURL;
	const previous = getTargetElement(document);
	documentSlots.extra.documentURL = url;
	const next = getTargetElement(document);
	for (const element of [previous, next]) {
		if (element !== null) {
			stateChanged(element, ["target", "target-within"]);
		}
	}
	(next as HTMLElement | null)?.scrollIntoView();
	if (oldURL === url) {
		return;
	}
	const window = documentSlots.extra.defaultView as unknown as EventTarget |
		null;
	if (window !== null) {
		setTimeout(() => {
			dispatchAsUserAgent(
				window,
				constructInternal(() =>
					new HashChangeEvent("hashchange", {oldURL, newURL: url}),
				),
			);
		}, 0);
	}
}

const PLACEHOLDER_INPUT_TYPES = new Set([
	"email",
	"number",
	"password",
	"search",
	"tel",
	"text",
	"url",
]);

export function isPlaceholderShown(element: Element): boolean {
	if (namespaceOf(element) !== HTML_NAMESPACE) {
		return false;
	}
	const name = localNameOf(element);
	if (name !== "input" && name !== "textarea") {
		return false;
	}
	// An empty placeholder is still the one presented, as browsers match it.
	const placeholder = attributeOf(element, "placeholder");
	if (placeholder === null || /[\r\n]/.test(placeholder)) {
		return false;
	}
	if (
		name === "input" && !PLACEHOLDER_INPUT_TYPES.has(getInputTypeValue(element))
	) {
		return false;
	}
	return (element as unknown as {value: string}).value === "";
}

function getInputTypeValue(element: Element): string {
	return toASCIILowercase(attributeOf(element, "type") ?? "text");
}

export function isDefaultControl(element: Element): boolean {
	if (namespaceOf(element) !== HTML_NAMESPACE) {
		return false;
	}
	const name = localNameOf(element);
	if (name === "option") {
		return attributeOf(element, "selected") !== null;
	}
	if (name === "input") {
		const type = getInputTypeValue(element);
		if (type === "checkbox" || type === "radio") {
			return attributeOf(element, "checked") !== null;
		}
	}
	if (name !== "button" && name !== "input") {
		return false;
	}
	const type = name === "button"
		? toASCIILowercase(attributeOf(element, "type") ?? "submit")
		: getInputTypeValue(element);
	if (type !== "submit" && type !== "image") {
		return false;
	}
	const form = (element as unknown as {form?: Element | null}).form ?? null;
	if (form === null) {
		return false;
	}
	// The default button is the first submit button in tree order.
	for (const candidate of form.querySelectorAll(
		"button, input",
	) as unknown as Iterable<
		Element
	>) {
		const local = localNameOf(candidate);
		const kind = local === "button"
			? toASCIILowercase(attributeOf(candidate, "type") ?? "submit")
			: getInputTypeValue(candidate);
		if (kind === "submit" || kind === "image") {
			return candidate === element;
		}
	}
	return false;
}

/** Whether `:open` matches. */
export function isOpenElement(element: Element): boolean {
	if (namespaceOf(element) !== HTML_NAMESPACE) {
		return false;
	}
	switch (localNameOf(element)) {
		case "details":
		case "dialog":
			return attributeOf(element, "open") !== null;
		case "select":
			return (_(element as HTMLSelectElement).extra.pickerHighlight != null);
		default:
			return false;
	}
}

// State a selector cannot read from the node itself: state the user
// agent keeps, a flat-tree link the node tree lacks, or a fact about the
// element's document. A headless tree uses the same functions, and the
// states simply return false.
export function getShadowHost(root: Node): Element | null {
	return isShadowRoot(root) ? _((root as ShadowRoot)).extra.host : null;
}

export function getOpenAssignedSlot(element: Element): Element | null {
	return (element.assignedSlot as Element | null) ?? null;
}

export function isHTMLNode(node: Node): boolean {
	return isHTMLDocument(_(node).document);
}

export function isInQuirksMode(node: Node): boolean {
	return _(_(node).document).extra.mode === "quirks";
}

// True for the element and anything it contains in the FLAT tree, which
// slot projection reorders relative to the node tree.
export function isHovered(element: Element): boolean {
	const document = _(element).document;
	for (
		let node: Element | null = hoveredElements.get(document) ?? null;
		node !== null;
		node = getFlatTreeParent(node)
	) {
		if (node === element) {
			return true;
		}
	}
	return false;
}

export function isFocusVisible(element: Element): boolean {
	const document = _(element).document;
	return (focusVisibleDocuments.get(document) ?? true) && hasFocus(element);
}

// The climb continues past every shadow host above the focused element,
// which is where the node tree's parent chain ends.
export function hasFocusWithin(element: Element): boolean {
	let node: Element | null = _(_(element).document).extra.activeElement;
	while (node !== null) {
		if (node === element) {
			return true;
		}
		const parent = node.parentElement as unknown as Element | null;
		if (parent !== null) {
			node = parent;
			continue;
		}
		const root = getRoot(node);
		node = isShadowRoot(root) ? _((root as ShadowRoot)).extra.host : null;
	}
	return false;
}

export function isFullscreenElement(element: Element): boolean {
	const stack = fullscreenStacks.get(_(element).document);
	return stack !== undefined && stack.includes(element);
}

export function isDefinedElement(element: Element): boolean {
	return _(element).customState !== "undefined";
}

// An h1 to h6 is a heading, at its number plus the heading offset around
// it: the headingoffset of it and each ancestor, summed until an element
// with headingreset, and at most 9 (HTML §4.3.6). The ancestors are the
// document's, not the flat tree's, so a heading slotted somewhere keeps
// its level.
export function getHeadingLevel(element: Element): number | null {
	if (namespaceOf(element) !== HTML_NAMESPACE) {
		return null;
	}
	const match = /^h([1-6])$/.exec(localNameOf(element));
	if (match === null) {
		return null;
	}
	return Math.min(Number(match[1]) + getHeadingOffset(element), 9);
}

function getHeadingOffset(element: Element): number {
	let offset = 0;
	for (
		let node: Element | null = element;
		node !== null;
		node = node.parentElement as Element | null
	) {
		if (namespaceOf(node) !== HTML_NAMESPACE) {
			continue;
		}
		const attribute = attributeOf(node, "headingoffset");
		const value = attribute === null
			? null
			: parseNonNegativeInteger(attribute);
		if (value !== null) {
			offset += value;
		}
		if (hasAttributeOf(node, "headingreset")) {
			break;
		}
	}
	return offset;
}

export function hasCustomState(element: Element, name: string): boolean {
	const internals = _(element).internals ?? null;
	const states = internals === null ? null : (_(internals).states ?? null);
	return states !== null && _(states).states.has(name);
}

export function isCheckedControl(element: Element): boolean {
	if (namespaceOf(element) !== HTML_NAMESPACE) {
		return false;
	}
	if (localNameOf(element) === "option") {
		return (element as unknown as HTMLOptionElement).selected;
	}
	if (localNameOf(element) !== "input") {
		return false;
	}
	const type = getInputTypeValue(element);
	return (
		(type === "checkbox" || type === "radio") &&
		(element as unknown as HTMLInputElement).checked
	);
}

// A checkbox whose indeterminate IDL attribute is set, a radio button
// whose group has nothing checked, and a progress bar with no value.
export function isIndeterminateControl(element: Element): boolean {
	if (namespaceOf(element) !== HTML_NAMESPACE) {
		return false;
	}
	if (localNameOf(element) === "progress") {
		return !hasAttributeOf(element, "value");
	}
	if (localNameOf(element) !== "input") {
		return false;
	}
	const type = getInputTypeValue(element);
	if (type === "checkbox") {
		return (element as unknown as HTMLInputElement).indeterminate;
	}
	return (
		type === "radio" &&
		getRadioGroup(element as unknown as HTMLInputElement).every(
			(input) => !input.checked,
		)
	);
}

function getValidityOwners(element: Element): Element[] {
	const owners: Element[] = [];
	for (let nodeSlots = _(element).parent;
		nodeSlots !== null;
		nodeSlots = nodeSlots.parent) {
		const node = objectOf(nodeSlots);
		if (isHTMLElementNamed(node, "fieldset")) {
			owners.push(node as Element);
		}
	}
	const form = isListed(element) ? getFormOwner(element) : null;
	if (form !== null) {
		owners.push(form as unknown as Element);
	}
	return owners;
}

// What :valid and :invalid say about an element, or null for one they do
// not apply to. A form or a fieldset is invalid when anything it holds
// that is being validated is.
export function getValidityMatch(element: Element): "valid" | "invalid" | null {
	if (namespaceOf(element) !== HTML_NAMESPACE) {
		return null;
	}
	const name = localNameOf(element);
	if (name === "form" || name === "fieldset") {
		const controls = name === "form"
			? getListedElements(element as unknown as HTMLFormElement)
			: getDescendantElements(element, []).filter(isListed);
		return controls.some((control) => isInvalidCandidate(control))
			? "invalid"
			: "valid";
	}
	if (!willValidate(element)) {
		return null;
	}
	return isInvalidCandidate(element) ? "invalid" : "valid";
}

function isInvalidCandidate(element: Element): boolean {
	if (!willValidate(element)) {
		return false;
	}
	const flags = getValidityFlags(element);
	return VALIDITY_FLAG_NAMES.some((flag) => flags[flag]);
}

// What :user-valid and :user-invalid say: the control's validity, once the
// user has committed a change to it or tried to submit its form.
export function getUserValidityMatch(
	element: Element,
): "valid" | "invalid" | null {
	return userValidity.has(element) ? getValidityMatch(element) : null;
}

// What :in-range and :out-of-range say about an input that is being
// validated and has range limitations, or null for any other element.
export function getRangeMatch(element: Element): "in" | "out" | null {
	if (!(element instanceof HTMLInputElement) || !willValidate(element)) {
		return null;
	}
	const type = element.type;
	if (STEP_RULES[type] === undefined) {
		return null;
	}
	const limited =
		type === "range" ||
		getInputValueNumber(type, attributeOf(element, "min") ?? "") !== null ||
		getInputValueNumber(type, attributeOf(element, "max") ?? "") !== null;
	if (!limited) {
		return null;
	}
	const flags = getValidityFlags(element);
	return flags.rangeUnderflow || flags.rangeOverflow ? "out" : "in";
}

/** A selector the matcher rejects becomes a SyntaxError, per the DOM. */
function asSyntaxError(error: unknown): unknown {
	return error instanceof SelectorError
		? domError("SyntaxError", error.message)
		: error;
}

interface ParseAttribute {
	name: string;
	value: string;
	namespace?: string;
	prefix?: string;
}

// A fragment parsed into an element uses that element's registry, and a
// document's own markup uses the document's. This holds whichever parse
// is running.
let parseRegistry: CustomElementRegistry | null | undefined = undefined;

// Every node the adapter creates belongs to the document it was made
// for, and every insertion runs the same algorithm appendChild runs, so a
// parsed tree and a scripted tree are the same tree.
// The return type is parse5's structural TreeAdapter, spelled by the object.
// eslint-disable-next-line @b9g/explicit-declaration-return-type
function createTreeAdapter(document: Document | null) {
	let target = document;
	const adapter = {
		createDocument(): Document {
			const created = new Document();
			const createdSlots = _(created);
			createdSlots.extra.type = "html";
			createdSlots.extra.contentType = "text/html";
			if (target === null) {
				target = created;
			}
			return created;
		},
		createDocumentFragment(): DocumentFragment {
			return (target as Document)
				.createDocumentFragment() as unknown as DocumentFragment;
		},
		createElement(
			tagName: string,
			namespaceURI: string,
			attrs: ParseAttribute[],
		): Element {
			const element = createElementInternal(
				target as Document,
				tagName,
				namespaceURI,
				null,
				null,
				false,
				parseRegistry,
			);
			adapter.adoptAttributes(element, attrs);
			return element;
		},
		createCommentNode(data: string): Comment {
			return (target as Document).createComment(data) as unknown as Comment;
		},
		createTextNode(value: string): Text {
			return (target as Document).createTextNode(value) as unknown as Text;
		},
		appendChild(parentNode: Node, newNode: Node): void {
			insertNode(newNode, parentNode, null, true);
		},
		insertBefore(parentNode: Node, newNode: Node, referenceNode: Node): void {
			insertNode(newNode, parentNode, referenceNode, true);
		},
		setTemplateContent(
			templateElement: Element,
			contentElement: DocumentFragment,
		): void {
			_(contentElement).extra.host = templateElement;
			_((templateElement as HTMLTemplateElement)).extra.templateContent =
				contentElement;
		},
		getTemplateContent(templateElement: Element): DocumentFragment {
			return (templateElement as HTMLTemplateElement).content;
		},
		setDocumentType(
			documentNode: Document,
			name: string,
			publicId: string,
			systemId: string,
		): void {
			const existing = documentNode.doctype as unknown as DocumentType | null;
			if (existing !== null) {
				_(existing).extra.name = name;
				_(existing).extra.publicId = publicId;
				_(existing).extra.systemId = systemId;
				return;
			}
			const doctype = new DocumentType(name, publicId, systemId);
			_(doctype).document = documentNode;
			insertNode(doctype, documentNode, null, true);
		},
		setDocumentMode(
			documentNode: Document,
			mode: "no-quirks" | "quirks" | "limited-quirks",
		): void {
			_(documentNode).extra.mode = mode;
		},
		// A fragment parse hands the fragment in as the document, which has
		// no mode.
		getDocumentMode(documentNode: Document): string {
			return _(documentNode).extra?.mode;
		},
		detachNode(node: Node): void {
			removeNode(node, true);
		},
		insertText(parentNode: Node, text: string): void {
			const last = objectOf(_(parentNode).lastChild);
			if (last !== null && nodeTypeOf(last) === TEXT_NODE) {
				_((last as CharacterData)).data += text;
				return;
			}
			adapter.appendChild(
				parentNode,
				(target as Document).createTextNode(text) as unknown as Text,
			);
		},
		insertTextBefore(
			parentNode: Node,
			text: string,
			referenceNode: Node,
		): void {
			const previous = objectOf(_(referenceNode).previous);
			if (previous !== null && nodeTypeOf(previous) === TEXT_NODE) {
				_((previous as CharacterData)).data += text;
				return;
			}
			adapter.insertBefore(
				parentNode,
				(target as Document).createTextNode(text) as unknown as Text,
				referenceNode,
			);
		},
		adoptAttributes(recipient: Element, attrs: ParseAttribute[]): void {
			for (const attribute of attrs) {
				const namespace = attribute.namespace ?? null;
				const prefix = attribute.prefix ?? null;
				const localName = attribute.name;
				if (getAttributeByNamespace(recipient, namespace, localName) !== null) {
					continue;
				}
				const created = new Attr(namespace, prefix, localName, attribute.value);
				_(created).document = _(recipient).document;
				appendAttribute(recipient, created);
			}
		},
		getFirstChild(node: Node): Node | null {
			return objectOf(_(node).firstChild);
		},
		getChildNodes(node: Node): Node[] {
			return getChildNodeArray(node);
		},
		getParentNode(node: Node): Node | null {
			return objectOf(_(node).parent);
		},
		getAttrList(element: Element): ParseAttribute[] {
			return _(element).attributeList.map((attribute) => ({
				name: attribute[kQualifiedName],
				value: attribute.extra.value,
				namespace: attribute.extra.namespace ?? undefined,
				prefix: attribute.extra.prefix ?? undefined,
			}));
		},
		getTagName(element: Element): string {
			return _(element)[kQualifiedName];
		},
		getNamespaceURI(element: Element): string {
			return _(element).namespace as string;
		},
		getTextNodeContent(textNode: CharacterData): string {
			return _(textNode).data;
		},
		getCommentNodeContent(commentNode: CharacterData): string {
			return _(commentNode).data;
		},
		getDocumentTypeNodeName(doctypeNode: DocumentType): string {
			return _(doctypeNode).extra.name;
		},
		getDocumentTypeNodePublicId(doctypeNode: DocumentType): string {
			return _(doctypeNode).extra.publicId;
		},
		getDocumentTypeNodeSystemId(doctypeNode: DocumentType): string {
			return _(doctypeNode).extra.systemId;
		},
		isTextNode(node: Node): boolean {
			return nodeTypeOf(node) === TEXT_NODE;
		},
		isCommentNode(node: Node): boolean {
			return nodeTypeOf(node) === COMMENT_NODE;
		},
		isDocumentTypeNode(node: Node): boolean {
			return nodeTypeOf(node) === DOCUMENT_TYPE_NODE;
		},
		isElementNode(node: Node): boolean {
			return nodeTypeOf(node) === ELEMENT_NODE;
		},
		setNodeSourceCodeLocation(): void {},
		getNodeSourceCodeLocation(): undefined {
			return undefined;
		},
		updateNodeSourceCodeLocation(): void {},
	};
	return adapter;
}

// A declarative shadow root that asks to be scoped has no registry until
// one claims it, and neither does anything the parser put inside it. A
// shadow tree further down keeps whatever registry it was given.
function dropRegistry(node: Node): void {
	const nodeSlots = _(node);
	nodeSlots.registry = null;
	for (let childSlots = nodeSlots.firstChild;
		childSlots !== null;
		childSlots = childSlots.next) {
		const child = objectOf(childSlots);
		dropRegistry(child);
	}
}

// The HTML parser attaches a shadow root as soon as it sees a template
// whose shadowrootmode names a mode. parse5 has no such step, so the
// templates land as templates and this walk converts them afterwards. It
// goes depth-first over the given tree and then over each shadow tree it
// creates, which reaches a nested declarative root. A template whose
// parent cannot host a shadow tree, or already hosts one, stays a
// template, which is the parser's own error handling.
function attachDeclarativeShadowRoots(root: Node): void {
	for (const child of getChildNodeArray(root)) {
		if (nodeTypeOf(child) !== ELEMENT_NODE) {
			continue;
		}
		const element = child as Element;
		if (
			_(element).namespace === HTML_NAMESPACE &&
			_(element).localName === "template"
		) {
			if (!attachDeclarativeShadowRoot(element as HTMLTemplateElement)) {
				attachDeclarativeShadowRoots((element as HTMLTemplateElement).content);
			}
			continue;
		}
		attachDeclarativeShadowRoots(element);
	}
}

// A shadow root the engine did not watch being filled -- a declarative
// one, or any the parser built before the document was attached -- is
// observed from now on, its sheets join the cascade, and the host's boxes
// are rebuilt around it.
function connectShadowRoot(root: ShadowRoot): void {
	const host = _(root).extra.host as Element | null;
	if (host === null) {
		return;
	}
	const attached = getAttachedDocument(host);
	if (attached === undefined) {
		return;
	}
	observeShadowRoot(_(host).document, root as unknown as globalThis.ShadowRoot);
	_(attached).extra.cascade.syncShadowRoot(
		root as unknown as globalThis.ShadowRoot,
	);
	_(attached).extra.layout.invalidate();
}

function attachDeclarativeShadowRoot(template: HTMLTemplateElement): boolean {
	const named = attributeOf(template, "shadowrootmode");
	if (named === null) {
		return false;
	}
	const mode = toASCIILowercase(named);
	if (mode !== "open" && mode !== "closed") {
		return false;
	}
	const templateSlots = _(template);
	const host = objectOf(templateSlots.parent);
	if (host === null || nodeTypeOf(host) !== ELEMENT_NODE) {
		return false;
	}
	try {
		attachShadowRoot(
			host as Element,
			mode,
			hasAttributeOf(template, "shadowrootclonable"),
			hasAttributeOf(template, "shadowrootserializable"),
			hasAttributeOf(template, "shadowrootdelegatesfocus"),
			"named",
			// A declarative shadow root that names a registry attribute is
			// scoped to a registry it has not been given yet, so it starts with
			// none.
			hasAttributeOf(template, "shadowrootcustomelementregistry")
				? null
				: _(_((host as Element)).document).registry,
		);
	} catch (_err) {
		return false;
	}
	const shadow = _((host as Element)).shadowRoot as ShadowRoot;
	const shadowSlots = _(shadow);
	shadowSlots.extra.declarative = true;
	const content = templateSlots.extra.templateContent;
	removeNode(template);
	if (content !== null) {
		for (const child of getChildNodeArray(content)) {
			if (shadowSlots.registry === null) {
				dropRegistry(child);
			}
			insertNode(child, shadow, null, true);
		}
	}
	attachDeclarativeShadowRoots(shadow);
	connectShadowRoot(shadow);
	return true;
}

// Builds the one document of this realm. It carries the realm's
// registry. Every document an author builds carries none until a
// registry claims it, exactly like a document with no browsing context.
function parseHTMLDocument(
	html: string,
	url = "about:blank",
	allowDeclarativeShadowRoots = true,
	registry: CustomElementRegistry | null = null,
): Document {
	const adapter = createTreeAdapter(null);
	const outerRegistry = parseRegistry;
	parseRegistry = registry;
	let document: Document;
	try {
		document = Parse5.parse(html, {
			treeAdapter: adapter as never,
		}) as unknown as Document;
	} finally {
		parseRegistry = outerRegistry;
	}
	_(document).registry = registry;
	_(document).extra.documentURL = url;
	if (allowDeclarativeShadowRoots) {
		attachDeclarativeShadowRoots(document);
	}
	return document;
}

// A declarative shadow root becomes one only if the caller allowed it.
// innerHTML does not; setHTMLUnsafe and parseHTMLUnsafe do.
function parseHTMLFragment(
	markup: string,
	context: Element,
	allowDeclarativeShadowRoots = false,
): DocumentFragment {
	const contextSlots = _(context);
	const document = contextSlots.document;
	const adapter = createTreeAdapter(document);
	const outerRegistry = parseRegistry;
	parseRegistry = contextSlots.registry;
	let parsed: DocumentFragment;
	try {
		parsed = Parse5.parseFragment(context as never, markup, {
			treeAdapter: adapter as never,
		}) as unknown as DocumentFragment;
	} finally {
		parseRegistry = outerRegistry;
	}
	const fragment =
		document.createDocumentFragment() as unknown as DocumentFragment;
	for (const child of getChildNodeArray(parsed)) {
		insertNode(child, fragment, null, true);
	}
	if (allowDeclarativeShadowRoots) {
		attachDeclarativeShadowRoots(fragment);
	}
	return fragment;
}

/** Becomes a parsererror document. */
class XMLWellFormednessError extends Error {}

// The namespace Firefox coined for the error document, which the spec's
// DOMParser algorithm adopted for the parsererror root.
const PARSERERROR_NAMESPACE =
	"http://www.mozilla.org/newlayout/xml/parsererror.xml";

// Characters the XML Char production excludes: most C0 controls, the
// two permanent non-characters, and a surrogate half without its
// partner.
const XML_FORBIDDEN_CHAR =
	/[\0-\x08\x0B\x0C\x0E-\x1F￾￿]|[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/;

/* eslint-disable no-misleading-character-class -- the XML Name production
   matches lone combining marks by definition */
const XML_NAME_TOKEN = new RegExp(
	`(?:[${NAME_START}]|[\uD800-\uDBFF][\uDC00-\uDFFF])` +
	`(?:[${NAME_REST}]|[\uD800-\uDBFF][\uDC00-\uDFFF])*`,
	"y",
);
/* eslint-enable no-misleading-character-class */

const PREDEFINED_ENTITIES = new Map([
	["amp", "&"],
	["lt", "<"],
	["gt", ">"],
	["apos", "'"],
	["quot", '"'],
]);

/** A Char: not a control or a surrogate. */
function isXMLChar(code: number): boolean {
	return (
		code === 0x9 ||
		code === 0xa ||
		code === 0xd ||
		(code >= 0x20 && code <= 0xd7ff) ||
		(code >= 0xe000 && code <= 0xfffd) ||
		(code >= 0x10000 && code <= 0x10ffff)
	);
}

// Chained to the enclosing scope. The root scope binds the two prefixes
// XML reserves.
interface XMLNamescope {
	parent: XMLNamescope | null;
	bindings: Map<string, string | null>;
}

function lookupXMLPrefix(
	scope: XMLNamescope,
	prefix: string,
): string | null | undefined {
	for (
		let current: XMLNamescope | null = scope;
		current !== null;
		current = current.parent
	) {
		const bound = current.bindings.get(prefix);
		if (bound !== undefined) {
			return bound;
		}
	}
	return undefined;
}

// A recursive-descent parser over the whole source string. It builds
// the tree with the same internal constructors the HTML tree adapter
// uses. It enforces well-formedness (one root, matching tags, bound
// prefixes, defined entities) and throws XMLWellFormednessError where
// the XML or Namespaces recommendations say a document is not
// well-formed. A DTD internal subset is skipped rather than processed, so
// an entity it declares is still reported as undefined, as a
// non-validating processor may do.
function parseXMLIntoDocument(source: string, document: Document): void {
	const input = source.replace(/\r\n?/g, "\n");
	let pos = 0;

	function fail(message: string): never {
		let line = 1;
		let lineStart = 0;
		for (let index = 0; index < pos && index < input.length; index++) {
			if (input.charCodeAt(index) === 0xa) {
				line++;
				lineStart = index + 1;
			}
		}
		const column = pos - lineStart + 1;
		throw new XMLWellFormednessError(
			`${message} (line ${line}, column ${column})`,
		);
	}

	const forbidden = XML_FORBIDDEN_CHAR.exec(input);
	if (forbidden !== null) {
		pos = forbidden.index;
		fail("The document contains a character XML forbids");
	}

	function eat(token: string): boolean {
		if (input.startsWith(token, pos)) {
			pos += token.length;
			return true;
		}
		return false;
	}

	function skipWhitespace(): boolean {
		const start = pos;
		while (pos < input.length) {
			const code = input.charCodeAt(pos);
			if (code !== 0x20 && code !== 0x9 && code !== 0xa) {
				break;
			}
			pos++;
		}
		return pos > start;
	}

	function scanName(): string {
		XML_NAME_TOKEN.lastIndex = pos;
		const match = XML_NAME_TOKEN.exec(input);
		if (match === null) {
			fail("Expected a name");
		}
		pos = XML_NAME_TOKEN.lastIndex;
		return match[0];
	}

	// pos points at the ampersand.
	function resolveReference(): string {
		pos++;
		if (eat("#x") || eat("#X")) {
			const start = pos;
			while (pos < input.length && /[0-9A-Fa-f]/.test(input[pos])) {
				pos++;
			}
			if (pos === start || !eat(";")) {
				fail("A malformed character reference");
			}
			const code = parseInt(input.slice(start, pos - 1), 16);
			if (!isXMLChar(code)) {
				fail("A character reference to a character XML forbids");
			}
			return String.fromCodePoint(code);
		}
		if (eat("#")) {
			const start = pos;
			while (pos < input.length && /[0-9]/.test(input[pos])) {
				pos++;
			}
			if (pos === start || !eat(";")) {
				fail("A malformed character reference");
			}
			const code = parseInt(input.slice(start, pos - 1), 10);
			if (!isXMLChar(code)) {
				fail("A character reference to a character XML forbids");
			}
			return String.fromCodePoint(code);
		}
		const name = scanName();
		if (!eat(";")) {
			fail("An entity reference is missing its semicolon");
		}
		const replacement = PREDEFINED_ENTITIES.get(name);
		if (replacement === undefined) {
			fail(`The entity "&${name};" is not defined`);
		}
		return replacement;
	}

	function parseAttributeValue(): string {
		const quote = input[pos];
		if (quote !== '"' && quote !== "'") {
			fail("An attribute value must be quoted");
		}
		pos++;
		let value = "";
		while (pos < input.length) {
			const char = input[pos];
			if (char === quote) {
				pos++;
				return value;
			}
			if (char === "<") {
				fail("An attribute value cannot contain <");
			}
			if (char === "&") {
				value += resolveReference();
				continue;
			}
			value += char === "\t" || char === "\n" ? " " : char;
			pos++;
		}
		fail("An attribute value is missing its closing quote");
	}

	// An element takes the default namespace. An unprefixed attribute takes
	// none.
	function resolveQualifiedName(
		qualifiedName: string,
		scope: XMLNamescope,
		forAttribute: boolean,
	): {namespace: string | null; prefix: string | null; localName: string} {
		const colon = qualifiedName.indexOf(":");
		if (colon === -1) {
			if (forAttribute) {
				return {namespace: null, prefix: null, localName: qualifiedName};
			}
			return {
				namespace: lookupXMLPrefix(scope, "") ?? null,
				prefix: null,
				localName: qualifiedName,
			};
		}
		const prefix = qualifiedName.slice(0, colon);
		const localName = qualifiedName.slice(colon + 1);
		if (prefix === "" || localName === "" || localName.includes(":")) {
			fail(`"${qualifiedName}" is not a valid qualified name`);
		}
		if (prefix === "xmlns") {
			fail("The xmlns prefix is reserved for namespace declarations");
		}
		const namespace = lookupXMLPrefix(scope, prefix);
		if (namespace == null) {
			fail(`The prefix "${prefix}" is not bound to a namespace`);
		}
		return {namespace, prefix, localName};
	}

	function parseComment(parent: Node): void {
		const end = input.indexOf("--", pos);
		if (end === -1) {
			pos = input.length;
			fail("A comment is missing its closing -->");
		}
		const data = input.slice(pos, end);
		pos = end;
		if (!eat("-->")) {
			fail("A comment cannot contain --");
		}
		const comment = new Comment(data);
		_(comment).document = document;
		insertNode(comment, parent, null, true);
	}

	function parseProcessingInstruction(parent: Node): void {
		const target = scanName();
		if (target.toLowerCase() === "xml") {
			fail("An XML declaration is only allowed at the start of the document");
		}
		if (target.includes(":")) {
			fail("A processing instruction target cannot contain a colon");
		}
		let data = "";
		if (!eat("?>")) {
			if (!skipWhitespace()) {
				fail("A processing instruction needs space after its target");
			}
			const end = input.indexOf("?>", pos);
			if (end === -1) {
				pos = input.length;
				fail("A processing instruction is missing its closing ?>");
			}
			data = input.slice(pos, end);
			pos = end + 2;
		}
		const instruction = new ProcessingInstruction(target, data);
		_(instruction).document = document;
		insertNode(instruction, parent, null, true);
	}

	function parseDeclarationValue(name: string): string {
		skipWhitespace();
		if (!eat("=")) {
			fail(`The XML declaration's ${name} needs a value`);
		}
		skipWhitespace();
		return parseAttributeValue();
	}

	function parseXMLDeclaration(): void {
		if (!skipWhitespace()) {
			fail("The XML declaration needs space before its version");
		}
		if (!eat("version")) {
			fail("The XML declaration must open with a version");
		}
		const version = parseDeclarationValue("version");
		if (!/^1\.[0-9]+$/.test(version)) {
			fail(`"${version}" is not an XML version`);
		}
		let spaced = skipWhitespace();
		if (spaced && input.startsWith("encoding", pos)) {
			pos += "encoding".length;
			const encoding = parseDeclarationValue("encoding");
			if (!/^[A-Za-z][A-Za-z0-9._-]*$/.test(encoding)) {
				fail(`"${encoding}" is not an encoding name`);
			}
			spaced = skipWhitespace();
		}
		if (spaced && input.startsWith("standalone", pos)) {
			pos += "standalone".length;
			const standalone = parseDeclarationValue("standalone");
			if (standalone !== "yes" && standalone !== "no") {
				fail("The standalone declaration must be \"yes\" or \"no\"");
			}
			skipWhitespace();
		}
		if (!eat("?>")) {
			fail("The XML declaration is missing its closing ?>");
		}
	}

	// Respects quotes and comments inside the subset.
	function skipInternalSubset(): void {
		while (pos < input.length) {
			const char = input[pos];
			if (char === "]") {
				pos++;
				return;
			}
			if (eat("<!--")) {
				const end = input.indexOf("-->", pos);
				if (end === -1) {
					break;
				}
				pos = end + 3;
				continue;
			}
			if (eat("<?")) {
				const end = input.indexOf("?>", pos);
				if (end === -1) {
					break;
				}
				pos = end + 2;
				continue;
			}
			if (char === '"' || char === "'") {
				const end = input.indexOf(char, pos + 1);
				if (end === -1) {
					break;
				}
				pos = end + 1;
				continue;
			}
			pos++;
		}
		pos = input.length;
		fail("The doctype's internal subset is missing its closing ]");
	}

	// Quoted, and taken as-is with no reference expansion.
	function parseDoctypeLiteral(): string {
		const quote = input[pos];
		if (quote !== '"' && quote !== "'") {
			fail("A doctype literal must be quoted");
		}
		const end = input.indexOf(quote, pos + 1);
		if (end === -1) {
			fail("A doctype literal is missing its closing quote");
		}
		const value = input.slice(pos + 1, end);
		pos = end + 1;
		return value;
	}

	function parseDoctype(): void {
		if (!skipWhitespace()) {
			fail("The doctype needs space before its name");
		}
		const name = scanName();
		let publicId = "";
		let systemId = "";
		const spaced = skipWhitespace();
		if (spaced && eat("SYSTEM")) {
			if (!skipWhitespace()) {
				fail("SYSTEM needs space before its literal");
			}
			systemId = parseDoctypeLiteral();
			skipWhitespace();
		} else if (spaced && eat("PUBLIC")) {
			if (!skipWhitespace()) {
				fail("PUBLIC needs space before its literals");
			}
			publicId = parseDoctypeLiteral();
			if (!skipWhitespace()) {
				fail("PUBLIC needs space between its literals");
			}
			systemId = parseDoctypeLiteral();
			skipWhitespace();
		}
		if (eat("[")) {
			skipInternalSubset();
			skipWhitespace();
		}
		if (!eat(">")) {
			fail("The doctype is missing its closing >");
		}
		const doctype = new DocumentType(name, publicId, systemId);
		_(doctype).document = document;
		insertNode(doctype, document, null, true);
	}

	function parseCDATASection(parent: Node): void {
		const end = input.indexOf("]]>", pos);
		if (end === -1) {
			pos = input.length;
			fail("A CDATA section is missing its closing ]]>");
		}
		const section = new CDATASection(input.slice(pos, end));
		_(section).document = document;
		insertNode(section, parent, null, true);
		pos = end + 3;
	}

	function appendText(parent: Node, data: string): void {
		const last = objectOf(_(parent).lastChild);
		if (last !== null && nodeTypeOf(last) === TEXT_NODE) {
			_((last as CharacterData)).data += data;
			return;
		}
		const text = document.createTextNode(data) as unknown as Text;
		insertNode(text, parent, null, true);
	}

	function parseElement(parent: Node, parentScope: XMLNamescope): void {
		const qualifiedName = scanName();
		interface ParsedAttribute {
			qualifiedName: string;
			value: string;
		}
		const attributes: ParsedAttribute[] = [];
		let selfClosing = false;
		for (;;) {
			const spaced = skipWhitespace();
			if (eat("/>")) {
				selfClosing = true;
				break;
			}
			if (eat(">")) {
				break;
			}
			if (pos >= input.length) {
				fail(`The <${qualifiedName}> tag is missing its closing >`);
			}
			if (!spaced) {
				fail("Attributes must be separated by space");
			}
			const attributeName = scanName();
			skipWhitespace();
			if (!eat("=")) {
				fail(`The attribute "${attributeName}" is missing its value`);
			}
			skipWhitespace();
			const value = parseAttributeValue();
			for (const attribute of attributes) {
				if (attribute.qualifiedName === attributeName) {
					fail(`The attribute "${attributeName}" is repeated`);
				}
			}
			attributes.push({qualifiedName: attributeName, value});
		}
		let scope = parentScope;
		const bindings = new Map<string, string | null>();
		for (const attribute of attributes) {
			let boundPrefix: string;
			if (attribute.qualifiedName === "xmlns") {
				boundPrefix = "";
			} else if (attribute.qualifiedName.startsWith("xmlns:")) {
				boundPrefix = attribute.qualifiedName.slice("xmlns:".length);
				if (boundPrefix === "" || boundPrefix.includes(":")) {
					fail(`"${attribute.qualifiedName}" is not a namespace declaration`);
				}
			} else {
				continue;
			}
			if (boundPrefix === "xmlns") {
				fail("The xmlns prefix cannot be declared");
			}
			if (boundPrefix === "xml" && attribute.value !== XML_NAMESPACE) {
				fail("The xml prefix is bound to the XML namespace and no other");
			}
			if (
				attribute.value === XMLNS_NAMESPACE ||
				(attribute.value === XML_NAMESPACE && boundPrefix !== "xml")
			) {
				fail("A reserved namespace cannot be bound to another name");
			}
			if (boundPrefix !== "" && attribute.value === "") {
				fail(`The prefix "${boundPrefix}" cannot be unbound`);
			}
			bindings.set(
				boundPrefix,
				attribute.value === "" ? null : attribute.value,
			);
		}
		if (bindings.size > 0) {
			scope = {parent: parentScope, bindings};
		}
		const resolved = resolveQualifiedName(qualifiedName, scope, false);
		const element = createElementInternal(
			document,
			resolved.localName,
			resolved.namespace,
			resolved.prefix,
			null,
			false,
			null,
		);
		const seen = new Set<string>();
		for (const attribute of attributes) {
			let namespace: string | null;
			let prefix: string | null = null;
			let localName = attribute.qualifiedName;
			if (attribute.qualifiedName === "xmlns") {
				namespace = XMLNS_NAMESPACE;
			} else if (attribute.qualifiedName.startsWith("xmlns:")) {
				namespace = XMLNS_NAMESPACE;
				prefix = "xmlns";
				localName = attribute.qualifiedName.slice("xmlns:".length);
			} else {
				const extracted = resolveQualifiedName(
					attribute.qualifiedName,
					scope,
					true,
				);
				namespace = extracted.namespace;
				prefix = extracted.prefix;
				localName = extracted.localName;
			}
			const key = `${namespace ?? ""}\0${localName}`;
			if (seen.has(key)) {
				fail(`The attribute "${localName}" appears twice in one namespace`);
			}
			seen.add(key);
			const created = new Attr(namespace, prefix, localName, attribute.value);
			_(created).document = document;
			appendAttribute(element, created);
		}
		insertNode(element, parent, null, true);
		if (selfClosing) {
			return;
		}
		parseContent(element, scope);
		if (pos >= input.length) {
			fail(`The <${qualifiedName}> element is never closed`);
		}
		const closing = scanName();
		if (closing !== qualifiedName) {
			fail(`</${closing}> does not match the open <${qualifiedName}>`);
		}
		skipWhitespace();
		if (!eat(">")) {
			fail(`The </${qualifiedName}> tag is missing its closing >`);
		}
	}

	function parseContent(parent: Node, scope: XMLNamescope): void {
		while (pos < input.length) {
			if (eat("</")) {
				return;
			}
			if (eat("<!--")) {
				parseComment(parent);
				continue;
			}
			if (eat("<![CDATA[")) {
				parseCDATASection(parent);
				continue;
			}
			if (eat("<?")) {
				parseProcessingInstruction(parent);
				continue;
			}
			if (input.startsWith("<!", pos)) {
				fail("Markup declarations cannot appear in content");
			}
			if (eat("<")) {
				parseElement(parent, scope);
				continue;
			}
			let text = "";
			while (pos < input.length) {
				const char = input[pos];
				if (char === "<") {
					break;
				}
				if (char === "&") {
					text += resolveReference();
					continue;
				}
				if (char === "]" && input.startsWith("]]>", pos)) {
					fail("Text content cannot contain ]]>");
				}
				text += char;
				pos++;
			}
			appendText(parent, text);
		}
	}

	const rootScope: XMLNamescope = {
		parent: null,
		bindings: new Map([["xml", XML_NAMESPACE]]),
	};
	if (input.startsWith("<?xml", pos) && /[ \t\n?]/.test(input[5] ?? "")) {
		pos += "<?xml".length;
		parseXMLDeclaration();
	}
	let sawRoot = false;
	let sawDoctype = false;
	while (pos < input.length) {
		if (skipWhitespace()) {
			continue;
		}
		if (eat("<!--")) {
			parseComment(document);
			continue;
		}
		if (eat("<?")) {
			parseProcessingInstruction(document);
			continue;
		}
		if (eat("<!DOCTYPE")) {
			if (sawDoctype || sawRoot) {
				fail("A doctype must come once, before the root element");
			}
			sawDoctype = true;
			parseDoctype();
			continue;
		}
		if (input.startsWith("<!", pos) || input.startsWith("</", pos)) {
			fail("Unexpected markup outside the root element");
		}
		if (eat("<")) {
			if (sawRoot) {
				fail("A document holds one root element");
			}
			sawRoot = true;
			parseElement(document, rootScope);
			continue;
		}
		fail("Text is not allowed outside the root element");
	}
	if (!sawRoot) {
		fail("The document has no root element");
	}
}

export class DOMParser {
	constructor() {
		seal(this, new.target, DOMParser);
	}

	parseFromString(
		string: string,
		type: globalThis.DOMParserSupportedType,
	): Document {
		const contentType = String(type);
		if (contentType === "text/html") {
			return parseHTMLDocument(String(string), "about:blank", false, null);
		}
		if (
			contentType === "text/xml" ||
			contentType === "application/xml" ||
			contentType === "application/xhtml+xml" ||
			contentType === "image/svg+xml"
		) {
			return parseXMLDocument(String(string), contentType);
		}
		throw new TypeError(`"${type}" is not a supported content type`);
	}
}

declareSealedRoot(DOMParser);

// A well-formed document becomes the tree it describes. Anything else
// becomes the spec's error document, whose root is a parsererror element
// holding the failure.
function parseXMLDocument(source: string, contentType: string): Document {
	const document = new XMLDocument();
	const documentSlots = _(document);
	documentSlots.extra.type = "xml";
	documentSlots.extra.contentType = contentType;
	documentSlots.registry = null;
	try {
		parseXMLIntoDocument(source, document);
	} catch (error) {
		if (!(error instanceof XMLWellFormednessError)) {
			throw error;
		}
		for (const child of getChildNodeArray(document)) {
			removeNode(child, true);
		}
		const parserError = createElementInternal(
			document,
			"parsererror",
			PARSERERROR_NAMESPACE,
		);
		const text = document.createTextNode(error.message) as unknown as Text;
		insertNode(text, parserError, null, true);
		insertNode(parserError, document, null, true);
	}
	return document;
}

Object.defineProperty(DOMParser.prototype, Symbol.toStringTag, {
	value: "DOMParser",
	configurable: true,
});

const VOID_ELEMENTS = new Set([
	"area",
	"base",
	"basefont",
	"bgsound",
	"br",
	"col",
	"embed",
	"frame",
	"hr",
	"img",
	"input",
	"keygen",
	"link",
	"meta",
	"param",
	"source",
	"track",
	"wbr",
]);

const NEWLINE_EATING_ELEMENTS = new Set(["pre", "textarea", "listing"]);

const RAW_TEXT_PARENTS = new Set([
	"style",
	"script",
	"xmp",
	"iframe",
	"noembed",
	"noframes",
	"plaintext",
	"noscript",
]);

function escapeText(value: string): string {
	return value
		.replace(/&/g, "&amp;")
		.replace(/\u00a0/g, "&nbsp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;");
}

function escapeAttribute(value: string): string {
	return value
		.replace(/&/g, "&amp;")
		.replace(/\u00a0/g, "&nbsp;")
		.replace(/"/g, "&quot;");
}

function getAttributeSerializedName(attribute: Attr): string {
	const attributeSlots = _(attribute);
	const namespace = attributeSlots.extra.namespace;
	if (namespace === null) {
		return attributeSlots.extra.localName;
	}
	if (namespace === XML_NAMESPACE) {
		return `xml:${attributeSlots.extra.localName}`;
	}
	if (namespace === XMLNS_NAMESPACE) {
		return attributeSlots.extra.localName === "xmlns"
			? "xmlns"
			: `xmlns:${attributeSlots.extra.localName}`;
	}
	if (namespace === XLINK_NAMESPACE) {
		return `xlink:${attributeSlots.extra.localName}`;
	}
	return attributeSlots[kQualifiedName];
}

// A shadow root is written out as the template the parser reads back,
// but only where the caller asked for it. getHTML's options say whether
// a serializable root counts and name the closed roots to include.
// innerHTML asks for none, so shadow trees are invisible to it.
function serializeFragment(
	node: Node,
	serializableShadowRoots: boolean,
	shadowRoots: ShadowRoot[] = [],
): string {
	let children = node;
	if (
		nodeTypeOf(node) === ELEMENT_NODE &&
		_((node as Element)).namespace === HTML_NAMESPACE &&
		_((node as Element)).localName === "template"
	) {
		const content = _((node as HTMLTemplateElement)).extra.templateContent;
		if (content != null) {
			children = content;
		}
	}
	let html = "";
	if (nodeTypeOf(node) === ELEMENT_NODE) {
		const shadow = _((node as Element)).shadowRoot;
		if (
			shadow !== null &&
			((serializableShadowRoots && _(shadow).extra.serializable) ||
				shadowRoots.includes(shadow))
		) {
			html += serializeShadowRoot(shadow, serializableShadowRoots, shadowRoots);
		}
	}
	for (
		let childSlots = _(children).firstChild;
		childSlots !== null;
		childSlots = childSlots.next
	) {
		const child = objectOf(childSlots);
		html += serializeNode(child, serializableShadowRoots, shadowRoots);
	}
	return html;
}

function serializeShadowRoot(
	shadow: ShadowRoot,
	serializableShadowRoots: boolean,
	shadowRoots: ShadowRoot[],
): string {
	const shadowSlots = _(shadow);
	let html = `<template shadowrootmode="${shadowSlots.extra.shadowMode}"`;
	if (shadowSlots.extra.delegatesFocus) {
		html += ' shadowrootdelegatesfocus=""';
	}
	if (shadowSlots.extra.serializable) {
		html += ' shadowrootserializable=""';
	}
	if (shadowSlots.extra.clonable) {
		html += ' shadowrootclonable=""';
	}
	html += ">";
	html += serializeFragment(shadow, serializableShadowRoots, shadowRoots);
	html += "</template>";
	return html;
}

function serializeNode(
	node: Node,
	serializableShadowRoots: boolean,
	shadowRoots: ShadowRoot[],
): string {
	const nodeSlots = _(node);
	switch (nodeTypeOf(node)) {
		case ELEMENT_NODE: {
			const element = node as Element;
			const namespace = _(element).namespace;
			const tagName =
				namespace === HTML_NAMESPACE ||
				namespace === MATHML_NAMESPACE ||
				namespace === SVG_NAMESPACE
					? _(element).localName
					: _(element)[kQualifiedName];
			let html = `<${tagName}`;
			for (const attribute of _(element).attributeList) {
				html += ` ${getAttributeSerializedName(objectOf(attribute))}="${escapeAttribute(attribute.extra.value)}"`;
			}
			html += ">";
			if (namespace === HTML_NAMESPACE && VOID_ELEMENTS.has(tagName)) {
				return html;
			}
			// The parser drops a newline that opens a pre, textarea or listing,
			// so serializing one writes a second newline for the parser to eat,
			// and the first survives the round trip.
			if (
				namespace === HTML_NAMESPACE && NEWLINE_EATING_ELEMENTS.has(tagName)
			) {
				const first = objectOf(_(element).firstChild);
				if (
					first !== null &&
					nodeTypeOf(first) === TEXT_NODE &&
					_((first as CharacterData)).data.startsWith("\n")
				) {
					html += "\n";
				}
			}
			html += serializeFragment(element, serializableShadowRoots, shadowRoots);
			html += `</${tagName}>`;
			return html;
		}
		case TEXT_NODE: {
			const parent = objectOf(nodeSlots.parent);
			if (
				parent !== null &&
				nodeTypeOf(parent) === ELEMENT_NODE &&
				_((parent as Element)).namespace === HTML_NAMESPACE &&
				RAW_TEXT_PARENTS.has(_((parent as Element)).localName)
			) {
				return _((node as CharacterData)).data;
			}
			return escapeText(_((node as CharacterData)).data);
		}
		case CDATA_SECTION_NODE:
			return `<![CDATA[${_((node as CharacterData)).data}]]>`;
		case COMMENT_NODE:
			return `<!--${_((node as CharacterData)).data}-->`;
		case PROCESSING_INSTRUCTION_NODE:
			return `<?${_((node as ProcessingInstruction)).extra.target} ${
				_((node as CharacterData)).data
			}>`;
		case DOCUMENT_TYPE_NODE:
			return `<!DOCTYPE ${_((node as DocumentType)).extra.name}>`;
		default: {
			let html = "";
			for (
				let childSlots = nodeSlots.firstChild;
				childSlots !== null;
				childSlots = childSlots.next
			) {
				const child = objectOf(childSlots);
				html += serializeNode(child, serializableShadowRoots, shadowRoots);
			}
			return html;
		}
	}
}

// The list comes from the [CEReactions] extended attribute on the
// interfaces this DOM has. Anything that can insert, remove, rename or
