// A window starts with its interfaces and the timers any script expects
// to find. The display fills in the rest (sizing, scrolling, animation
// frames, the clipboard) as it mounts the document.
// The runtime's own, as the module found them. installGlobals() puts the
// window's in their place, and the window's call these.
// Bound, since a browser's throws when called on anything but its global.
const runtime = {
	setTimeout,
	clearTimeout,
	setInterval: globalThis.setInterval.bind(globalThis),
	clearInterval: globalThis.clearInterval.bind(globalThis),
	queueMicrotask,
	atob: globalThis.atob.bind(globalThis),
	btoa: globalThis.btoa.bind(globalThis),
	fetch: globalThis.fetch.bind(globalThis),
	structuredClone: globalThis.structuredClone.bind(globalThis),
};

/**
 * HTML's structured clone of `value`, for the algorithm `context` names
 * in the DataCloneError it throws: "execute 'postMessage' on 'Window'".
 * A platform object is refused, unless it is one HTML can serialize, and
 * that is copied.
 */
function cloneStructured(value: unknown, context: string): any {
	return containsPlatformObject(value, new Set(), context)
		? cloneWithPlatformObjects(value, new Map(), context)
		: runtime.structuredClone(value);
}

function isContainer(value: object): boolean {
	const prototype = Object.getPrototypeOf(value) as object | null;
	return Array.isArray(value) ||
		prototype === Object.prototype ||
		prototype === null ||
		value instanceof Map ||
		value instanceof Set;
}

function containsPlatformObject(
	value: unknown,
	seen: Set<object>,
	context: string,
): boolean {
	if (
		(typeof value !== "object" && typeof value !== "function") ||
		value === null ||
		seen.has(value)
	) {
		return false;
	}
	seen.add(value);
	if (typeOf(value) !== null) {
		if (!(value instanceof DOMRectReadOnly || value instanceof ImageData)) {
			throw domError(
				"DataCloneError",
				`Failed to ${context}: ${interfaceNameOf(value)} object could not be cloned.`,
			);
		}
		return true;
	}
	if (!isContainer(value)) {
		return false;
	}
	let found = false;
	const items = value instanceof Map
		? [...value.keys(), ...value.values()]
		: value instanceof Set ? [...value] : Object.values(value);
	for (const item of items) {
		found = containsPlatformObject(item, seen, context) || found;
	}
	return found;
}

function cloneWithPlatformObjects(
	value: unknown,
	copies: Map<object, unknown>,
	context: string,
): unknown {
	if (
		(typeof value !== "object" && typeof value !== "function") || value === null
	) {
		return value;
	}
	if (copies.has(value)) {
		return copies.get(value);
	}
	let copy: unknown;
	if (value instanceof DOMRectReadOnly) {
		const Type = value instanceof DOMRect ? DOMRect : DOMRectReadOnly;
		copy = new Type(value.x, value.y, value.width, value.height);
	} else if (value instanceof ImageData) {
		copy = new ImageData(
			new Uint8ClampedArray(value.data),
			value.width,
			value.height,
		);
	} else if (Array.isArray(value)) {
		const array: unknown[] = [];
		copies.set(value, array);
		for (const [index, item] of value.entries()) {
			array[index] = cloneWithPlatformObjects(item, copies, context);
		}
		copy = array;
	} else if (value instanceof Map) {
		const map = new Map();
		copies.set(value, map);
		for (const [key, item] of value) {
			map.set(
				cloneWithPlatformObjects(key, copies, context),
				cloneWithPlatformObjects(item, copies, context),
			);
		}
		copy = map;
	} else if (value instanceof Set) {
		const set = new Set();
		copies.set(value, set);
		for (const item of value) {
			set.add(cloneWithPlatformObjects(item, copies, context));
		}
		copy = set;
	} else if (isContainer(value)) {
		const object: Record<string, unknown> = {};
		copies.set(value, object);
		for (const [key, item] of Object.entries(value)) {
			object[key] = cloneWithPlatformObjects(item, copies, context);
		}
		copy = object;
	} else {
		copy = runtime.structuredClone(value);
	}
	copies.set(value, copy);
	return copy;
}

const windowTimers = new WeakMap<
	object,
	Map<number, ReturnType<typeof setTimeout>>
>();
const processTimers = new WeakMap<object, Record<string, unknown>>();

/**
 * The window's setTimeout and setInterval as installGlobals() puts them
 * on the global: they report what their callbacks throw as the page's
 * errors, but are the whole process's, its libraries' among them, so
 * disposing the TermDOM leaves them running.
 */
export function getProcessTimers(window: Window): Record<string, unknown> {
	return processTimers.get(window)!;
}

/**
 * Stop the window's timers and idle callbacks, as a browser stops an
 * unloaded document's.
 */
export function clearWindowTimers(window: Window): void {
	const timers = windowTimers.get(window);
	for (const handle of timers?.values() ?? []) {
		runtime.clearTimeout(handle);
	}
	timers?.clear();
	const idle = _(window).idleTimers;
	for (const timer of idle?.values() ?? []) {
		clearTimeout(timer);
	}
	idle?.clear();
}

function buildWindow(document: Document): Window {
	const window = new Window(document) as unknown as Record<string, unknown>;
	// HTML reports an exception a timer or a microtask lets escape, as it
	// does a listener's, and the page goes on. The runtime's own would end
	// the process.
	const guard = (handler: unknown, args: unknown[]): unknown =>
		typeof handler !== "function"
			? handler
			: () => {
				try {
					(handler as (...args: unknown[]) => void)(...args);
				} catch (error) {
					reportError(error, document);
				}
			};
	// The page's outstanding timers, which stop with the window, by the
	// number HTML hands the page for each: the runtime's own handle is the
	// runtime's object.
	const timers = new Map<number, ReturnType<typeof setTimeout>>();
	windowTimers.set(window, timers);
	let lastTimerId = 0;
	const clearTimer = (id: unknown) => {
		const key = Number(id);
		const handle = timers.get(key);
		if (handle !== undefined) {
			timers.delete(key);
			runtime.clearTimeout(handle);
		}
	};
	processTimers.set(window, {
		setTimeout: (handler: unknown, timeout?: number, ...args: unknown[]) =>
			runtime.setTimeout(guard(handler, args) as () => void, timeout),
		setInterval: (handler: unknown, timeout?: number, ...args: unknown[]) =>
			runtime.setInterval(guard(handler, args) as () => void, timeout),
	});
	Object.assign(
		window,
		getWindowClasses(),
		Object.fromEntries(getInterfaceObjects()),
		{
		// The platform's DOMException, which is the one the DOM and the CSSOM
		// throw. A caller's `instanceof DOMException` has to match the class
		// the engine builds its errors from.
			DOMException,
			setTimeout: (handler: unknown, timeout?: number, ...args: unknown[]) => {
				const guarded = guard(handler, args);
				const id = ++lastTimerId;
				timers.set(
					id,
					runtime.setTimeout(
						(typeof guarded === "function"
							? () => {
								timers.delete(id);
								(guarded as () => void)();
							}
							: guarded) as () => void,
						timeout,
					),
				);
				return id;
			},
			clearTimeout: clearTimer,
			setInterval: (handler: unknown, timeout?: number, ...args: unknown[]) => {
				const id = ++lastTimerId;
				timers.set(
					id,
					runtime.setInterval(guard(handler, args) as () => void, timeout),
				);
				return id;
			},
			clearInterval: clearTimer,
			queueMicrotask: (callback: unknown) => {
				if (typeof callback !== "function") {
					throw new TypeError("queueMicrotask needs a function");
				}
				runtime.queueMicrotask(guard(callback, []) as () => void);
			},
			atob: runtime.atob,
			btoa: runtime.btoa,
			fetch: runtime.fetch,
			structuredClone: (
				value: unknown,
				options: StructuredSerializeOptions = {},
			) =>
				(options.transfer ?? []).length > 0
					? runtime.structuredClone(value, options)
					: cloneStructured(value, "execute 'structuredClone' on 'Window'"),
		});
	// HTML's legacy factory: new Image(width, height) is an <img> in this
	// window's document.
	const Image = function Image(this: unknown, width?: number, height?: number) {
		if (new.target === undefined) {
			throw new TypeError("Image is a constructor");
		}
		const image = document.createElement("img");
		if (width !== undefined) {
			image.setAttribute("width", String(toImageDimension(width)));
		}
		if (height !== undefined) {
			image.setAttribute("height", String(toImageDimension(height)));
		}
		return image;
	} as unknown as typeof HTMLImageElement;
	Object.defineProperty(Image, "prototype", {
		value: HTMLImageElement.prototype,
	});
	window.Image = Image;
	window.window = window;
	window.self = window;
	for (const name of Object.keys(window)) {
		const value = window[name];
		if (typeof value === "function" && /^[a-z]/.test(name)) {
			window[name] = windowMember(
				window,
				name,
				value as (...args: never[]) => unknown,
			);
		}
	}
	prepareClasses(Object.values(getWindowClasses()));
	startPendingImages(document as unknown as globalThis.Document);
	return window as unknown as Window;
}

// Images the parser built before their document had a window wait for
// one, and start here, once it does.
function startPendingImages(
	root: globalThis.Document | globalThis.ShadowRoot,
): void {
	for (const element of root.querySelectorAll("*")) {
		if (
			element instanceof HTMLImageElement && _(element).extra.imageState.pending
		) {
			updateImageData(element);
		}
		const shadow = getShadowRoot(element);
		if (shadow !== null) {
			startPendingImages(shadow);
		}
	}
}

/**
 * Parse a document from markup and display it in a window of its own. An
 * XML content type parses as XML, which is what a frame whose src names a
 * .xml, .xhtml or .svg file holds.
 */
// The classes a window exposes by name. Read when a window is made rather
// than in the module's interface table: canvas.ts is part of the import
// cycle through cssvalues, and a table built at module load would read
// its classes before they exist when canvas.ts is the first module
// imported.
function getWindowClasses(): Record<string, Constructor> {
	return {
		...platform,
		...CSSOM_INTERFACES,
		CanvasGradient,
		CanvasPattern,
		CanvasRenderingContext2D,
		ImageBitmap,
		ImageData,
		Path2D,
	} as unknown as Record<string, Constructor>;
}

/** The names of the interfaces a window exposes. */
export function getWindowInterfaceNames(): string[] {
	return Object.keys(getWindowClasses());
}

// The window's interface objects, laid out before the first document is
// made, so that every platform object has its unforgeable members.
function getInterfaceObjects(): ReadonlyMap<string, Constructor> {
	return installInterfaces(getWindowClasses());
}

export function createWindow(
	source: string,
	url?: string,
	contentType = "text/html",
): Window {
	getInterfaceObjects();
	if (contentType === "text/html") {
		return buildWindow(
			parseHTMLDocument(source, url, true, createWindowRegistry()),
		);
	}
	const document = parseXMLDocument(source, contentType);
	const documentSlots = _(document);
	documentSlots.registry = createWindowRegistry();
	if (url !== undefined) {
		documentSlots.extra.documentURL = url;
	}
	return buildWindow(document);
}

export function isElement(node: Node): node is Element {
	return _(node).nodeType === ELEMENT_NODE;
}

/** The node's nodeType, read without going through the page's binding. */
export function nodeTypeOf(node: globalThis.Node): number {
	return _(node as Node).nodeType;
}

/** The node's ownerDocument, read without going through its binding. */
export function ownerDocumentOf(node: globalThis.Node): Document | null {
	const document = _(node as Node).document;
	return document === (node as unknown) ? null : document;
}

/** The element's localName, read without going through its binding. */
export function localNameOf(element: globalThis.Element): string {
	return _(element as Element).localName;
}

/** The element's attribute's value, read without going through its binding. */
export function attributeOf(
	element: globalThis.Element,
	qualifiedName: string,
): string | null {
	const attribute = getAttributeByName(element as Element, qualifiedName);
	return attribute === null ? null : _(attribute).extra.value;
}

/** Whether the element has the attribute, without going through its binding. */
export function hasAttributeOf(
	element: globalThis.Element,
	qualifiedName: string,
): boolean {
	return getAttributeByName(element as Element, qualifiedName) !== null;
}

/** The element's namespaceURI, read without going through its binding. */
export function namespaceOf(element: globalThis.Element): string | null {
	return _(element as Element).namespace;
}

export function parentElement(node: Node): Element | null {
	const parent = objectOf(_(node).parent);
	return parent !== null && isElement(parent) ? parent : null;
}

